<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var btnAjuda=document.getElementById('btn-ajuda');
  var ultimoGatilho=null;

  function abrirGaveta(){
    gaveta.classList.add('aberta');
    btnAjuda.setAttribute('aria-expanded','true');
    gaveta.querySelector('button').focus();
  }
  function fecharGaveta(){
    gaveta.classList.remove('aberta');
    btnAjuda.setAttribute('aria-expanded','false');
    btnAjuda.focus();
  }
  btnAjuda.addEventListener('click',function(){
    gaveta.classList.contains('aberta')?fecharGaveta():abrirGaveta();
  });
  gaveta.querySelector('[data-fechar]').addEventListener('click',fecharGaveta);

  function abrirModal(m,gatilho){
    ultimoGatilho=gatilho;
    m.hidden=false;
    var f=m.querySelector('input,.btn-prim,button');
    if(f)f.focus();
  }
  function fecharModal(m){
    m.hidden=true;
    if(ultimoGatilho)ultimoGatilho.focus();
  }

  document.querySelectorAll('[aria-controls]').forEach(function(b){
    var t=document.getElementById(b.getAttribute('aria-controls'));
    if(t&&t.classList.contains('modal')){
      b.addEventListener('click',function(){abrirModal(t,b);});
    }
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.matches('.modal-x,.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)'))fecharModal(m);
    });
  });

  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      document.querySelectorAll('.modal:not([hidden])').forEach(fecharModal);
      if(gaveta.classList.contains('aberta'))fecharGaveta();
      return;
    }
    if(e.key!=='Tab')return;
    var m=document.querySelector('.modal:not([hidden])');
    if(!m)return;
    var fs=m.querySelectorAll('button,input,a[href]');
    var p=fs[0],u=fs[fs.length-1];
    if(e.shiftKey&&document.activeElement===p){u.focus();e.preventDefault();}
    else if(!e.shiftKey&&document.activeElement===u){p.focus();e.preventDefault();}
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){b.closest('.banner').remove();});
  });
})();
</script>
</body>
