(function () {
  var TITULO = 'Configurações da conta - Banco Horizonte';
  var live = document.getElementById('live');
  var ultimoFoco = null;
  var appRevogar = '';

  function anunciar(texto) { live.textContent = texto; }
  function hora() { return new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); }
  function modalAberto() { return document.querySelector('[data-modal]:not([hidden])'); }
  function abrirModal(fundo) {
    ultimoFoco = document.activeElement;
    fundo.hidden = false;
    var alvo = fundo.querySelector('input') || fundo.querySelector('[data-cancelar]');
    alvo.focus();
  }
  function fecharModal(fundo) {
    fundo.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  // Status das sessões e apps: texto visível em vez de só cor
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var t = document.createElement('span');
    t.textContent = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(t);
  });

  // Nome acessível por linha nos botões repetidos
  document.querySelectorAll('#acessos tbody tr').forEach(function (tr) {
    var app = tr.querySelector('th').textContent.trim();
    tr.querySelectorAll('button').forEach(function (b) {
      b.setAttribute('aria-label', b.textContent.trim() + ' de ' + app);
    });
  });

  // Abrir modais
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        appRevogar = b.closest('tr').querySelector('th').textContent.trim();
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + appRevogar + '?';
        document.getElementById('dlg-revogar-d').textContent = appRevogar + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrirModal(document.getElementById(id));
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });

  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      fecharModal(b.closest('[data-modal]'));
      anunciar('Acesso de ' + appRevogar + ' revogado.');
    });
  });

  // Esc fecha; Tab fica preso dentro do diálogo aberto
  document.addEventListener('keydown', function (e) {
    var m = modalAberto();
    if (!m) return;
    if (e.key === 'Escape') { fecharModal(m); return; }
    if (e.key === 'Tab') {
      var f = m.querySelectorAll('button, input, a[href]');
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  // Exclusão: exige digitar EXCLUIR
  document.getElementById('form-excluir').addEventListener('submit', function (e) {
    e.preventDefault();
    var campo = document.getElementById('confirma-excluir');
    var erro = document.getElementById('erro-confirma');
    if (campo.value.trim() !== 'EXCLUIR') {
      campo.setAttribute('aria-invalid', 'true');
      erro.innerHTML = '<span class="sr-only">Erro: </span>Digite EXCLUIR em letras maiúsculas para confirmar.';
      erro.hidden = false;
      campo.focus();
      return;
    }
    campo.removeAttribute('aria-invalid');
    erro.hidden = true;
    fecharModal(document.getElementById('fundo-excluir'));
    anunciar('Solicitação de exclusão da conta registrada.');
  });

  // Preferências
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var h = hora();
    document.getElementById('texto-sucesso').textContent = 'Suas preferências de notificação foram salvas às ' + h + '.';
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências salvas às ' + h + '.');
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.getElementById('h-pref').focus();
  });

  // Perfil: valida ao enviar
  var regras = {
    nome: function (v) { return v.trim() ? '' : 'Digite seu nome completo.'; },
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) ? '' : 'Digite um endereço completo com domínio, por exemplo nome@bancohorizonte.com.br.'; },
    telefone: function (v) { return v.replace(/\D/g, '').length === 11 ? '' : 'Digite o DDD e o número de celular com 11 números, por exemplo (11) 91234-5678.'; }
  };

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var erros = [];
    Object.keys(regras).forEach(function (id) {
      var campo = document.getElementById(id);
      var msg = regras[id](campo.value);
      var grupo = campo.closest('.campo');
      var box = document.getElementById('erro-' + id);
      var marca = grupo.querySelector('.marca-erro');
      campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
      grupo.classList.toggle('campo-erro', !!msg);
      if (marca) marca.hidden = !msg;
      box.hidden = !msg;
      box.innerHTML = msg ? '<span class="sr-only">Erro: </span>' + msg : '';
      if (msg) erros.push({ id: id, texto: grupo.querySelector('label').textContent + ': ' + msg });
    });

    var resumo = document.getElementById('resumo-erros');
    var lista = document.getElementById('lista-erros');
    if (erros.length) {
      lista.innerHTML = '';
      erros.forEach(function (x) {
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + x.id;
        a.textContent = x.texto;
        li.appendChild(a);
        lista.appendChild(li);
      });
      document.getElementById('titulo-erros').textContent = erros.length === 1
        ? 'Corrija 1 campo antes de salvar o perfil'
        : 'Corrija ' + erros.length + ' campos antes de salvar o perfil';
      resumo.hidden = false;
      document.title = 'Erro: ' + TITULO;
      resumo.focus();
      return;
    }
    resumo.hidden = true;
    document.title = TITULO;
    anunciar('Perfil salvo às ' + hora() + '.');
  });
})();
@@ FIM

