<script>
var tituloOriginal = document.title;
var anuncio = document.getElementById('live');
var resumo = document.getElementById('resumo-perfil');
var listaErros = document.getElementById('lista-erros');
var ultimoGatilho = null;

function anunciar(texto) {
  anuncio.textContent = '';
  setTimeout(function () { anuncio.textContent = texto; }, 50);
}

document.querySelectorAll('tbody tr').forEach(function (linha) {
  var nome = linha.querySelector('th').textContent.trim();
  linha.querySelectorAll('button').forEach(function (b) {
    b.setAttribute('aria-label', b.textContent.trim() + ': ' + nome);
  });
});

function abrirModal(id, gatilho) {
  var m = document.getElementById(id);
  ultimoGatilho = gatilho;
  if (id === 'fundo-revogar') {
    var app = gatilho.closest('tr').querySelector('th').textContent.trim();
    document.getElementById('dlg-revogar-t').textContent = 'Revogar acesso de ' + app + '?';
  }
  if (id === 'fundo-excluir') {
    document.getElementById('confirma-exclusao').value = '';
    document.getElementById('confirma-exclusao').removeAttribute('aria-invalid');
    document.getElementById('erro-confirma').hidden = true;
  }
  m.hidden = false;
  (m.querySelector('input') || m.querySelector('[data-fechar]')).focus();
}

function fecharModal(m) {
  m.hidden = true;
  if (ultimoGatilho) ultimoGatilho.focus();
}

document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir'), b); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.querySelectorAll('[data-modal]').forEach(function (m) {
  m.addEventListener('keydown', function (e) { if (e.key === 'Escape') fecharModal(m); });
});

document.getElementById('confirmar-revogacao').addEventListener('click', function () {
  fecharModal(document.getElementById('fundo-revogar'));
  anunciar('Acesso revogado.');
});

document.getElementById('confirmar-exclusao').addEventListener('click', function () {
  var campo = document.getElementById('confirma-exclusao');
  var erro = document.getElementById('erro-confirma');
  if (campo.value.trim() !== 'EXCLUIR') {
    campo.setAttribute('aria-invalid', 'true');
    erro.hidden = false;
    campo.focus();
    return;
  }
  campo.removeAttribute('aria-invalid');
  erro.hidden = true;
  // Envio da exclusão: ligar ao endpoint do backend.
});

document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
});

function validarPerfil() {
  var erros = [];
  var nome = document.getElementById('nome');
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  if (nome.value.trim() === '') {
    erros.push({ campo: nome, msg: 'Informe seu nome completo.' });
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())) {
    erros.push({ campo: email, msg: 'Digite um e-mail com @ e domínio, por exemplo nome@dominio.com.br.' });
  }
  var digitos = tel.value.replace(/\D/g, '');
  if (digitos.length !== 10 && digitos.length !== 11) {
    erros.push({ campo: tel, msg: 'Digite o telefone com DDD, por exemplo (11) 91234-5678.' });
  }
  return erros;
}

function limparErros() {
  document.querySelectorAll('#form-perfil .erro').forEach(function (p) {
    p.hidden = true;
    p.textContent = '';
  });
  document.querySelectorAll('#form-perfil [aria-invalid]').forEach(function (c) {
    c.removeAttribute('aria-invalid');
  });
  listaErros.innerHTML = '';
  resumo.hidden = true;
  document.title = tituloOriginal;
}

function mostrarErros(erros) {
  limparErros();
  resumo.hidden = false;
  erros.forEach(function (e) {
    var id = e.campo.id;
    var p = document.getElementById('erro-' + id);
    p.innerHTML = '<span class="sr-only">Erro: </span>' + e.msg;
    p.hidden = false;
    e.campo.setAttribute('aria-invalid', 'true');
    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = '#' + id;
    a.textContent = e.msg;
    li.appendChild(a);
    listaErros.appendChild(li);
  });
  document.title = 'Erro: ' + tituloOriginal;
  document.getElementById('resumo-perfil-t').focus();
}

var formPerfil = document.getElementById('form-perfil');
formPerfil.addEventListener('submit', function (e) {
  var erros = validarPerfil();
  if (erros.length) {
    e.preventDefault();
    mostrarErros(erros);
  } else {
    limparErros();
  }
});
formPerfil.addEventListener('reset', limparErros);
</script>
