<script>
(function(){
  var form=document.querySelector('form');
  var resumo=document.getElementById('resumo-erros');
  var lista=document.getElementById('lista-erros');
  var titulo=document.getElementById('titulo-erros');
  var nomePagina=document.title.replace(/^Erro: /,'');
  var mesmo=document.querySelector('input[name=mesmo]');
  var blocoCor=mesmo.closest('label').nextElementSibling;

  document.querySelectorAll('.grupo').forEach(function(g,i){
    var r=g.querySelector(':scope > .rotulo-grupo');
    if(r){r.id='rg'+i;g.setAttribute('role','group');g.setAttribute('aria-labelledby','rg'+i);}
  });

  var abas=[].slice.call(document.querySelectorAll('[role=tab]'));
  function ativar(t,foco){
    abas.forEach(function(x){
      var on=x===t, p=document.getElementById(x.getAttribute('aria-controls'));
      x.setAttribute('aria-selected',on);
      x.tabIndex=on?0:-1;
      x.classList.toggle('aba-ativa',on);
      p.hidden=!on;
      p.setAttribute('aria-labelledby',x.id);
    });
    if(foco)t.focus();
  }
  abas.forEach(function(t,i){
    t.addEventListener('click',function(){ativar(t,false);});
    t.addEventListener('keydown',function(e){
      var d={ArrowRight:1,ArrowLeft:-1}[e.key];
      if(!d)return;
      e.preventDefault();
      ativar(abas[(i+d+abas.length)%abas.length],true);
    });
  });
  ativar(abas[0],false);

  function sincronizarCor(){blocoCor.hidden=mesmo.checked;}
  mesmo.addEventListener('change',sincronizarCor);
  sincronizarCor();

  var obrigatorios=[].slice.call(document.querySelectorAll('label .obrig')).map(function(o){
    var l=o.closest('label');
    return l.htmlFor?document.getElementById(l.htmlFor):l.querySelector('input');
  });

  function valido(el){
    if(el.type==='checkbox')return el.checked;
    return el.value.trim()!==''&&el.checkValidity();
  }

  function marcarErro(el){
    var id='e-'+el.id, p=document.getElementById(id);
    if(!p){
      p=document.createElement('p');
      p.id=id;p.className='erro';
      var s=document.createElement('span');s.className='sr';s.textContent='Erro: ';
      p.appendChild(s);
      p.appendChild(document.createTextNode(el.title||'Preencha este campo.'));
      var host=el.closest('.campo');
      if(host)host.appendChild(p);else el.closest('label').after(p);
    }
    var d=(el.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
    if(d.indexOf(id)<0)d.push(id);
    el.setAttribute('aria-describedby',d.join(' '));
    el.setAttribute('aria-invalid','true');
    var c=el.closest('.campo');if(c)c.classList.add('tem-erro');
    return p.textContent.replace(/^Erro:\s*/,'').trim();
  }

  function limpar(el){
    var id='e-'+el.id, p=document.getElementById(id);
    if(p)p.remove();
    el.setAttribute('aria-describedby',(el.getAttribute('aria-describedby')||'').split(' ').filter(function(x){return x&&x!==id;}).join(' '));
    el.removeAttribute('aria-invalid');
    var c=el.closest('.campo');if(c)c.classList.remove('tem-erro');
  }

  form.addEventListener('submit',function(e){
    var erros=[];
    obrigatorios.forEach(function(el){
      if(valido(el)){limpar(el);return;}
      var lab=document.querySelector('label[for="'+el.id+'"]')||el.closest('label');
      erros.push({id:el.id,nome:lab.textContent.replace('*','').trim(),texto:marcarErro(el)});
    });
    if(!erros.length){
      resumo.hidden=true;
      document.title=nomePagina;
      return;
    }
    e.preventDefault();
    lista.textContent='';
    erros.forEach(function(x){
      var li=document.createElement('li'),a=document.createElement('a');
      a.href='#'+x.id;
      a.textContent=x.nome+': '+x.texto;
      li.appendChild(a);lista.appendChild(li);
    });
    titulo.textContent='Há '+erros.length+(erros.length===1?' problema nesta etapa':' problemas nesta etapa');
    resumo.hidden=false;
    document.title='Erro: '+nomePagina;
    resumo.focus();
  });
})();
</script>
</body>
