var ultimoFoco = null;
var modalAberto = null;
function abrirModal(id) {
  ultimoFoco = document.activeElement;
  modalAberto = document.getElementById(id);
  modalAberto.hidden = false;
  var seguro = modalAberto.querySelector('.acoes .btn:not(.perigo)');
  (seguro || modalAberto.querySelector('button')).focus();
}
function fecharModal() {
  if (!modalAberto) return;
  modalAberto.hidden = true;
  modalAberto = null;
  if (ultimoFoco) ultimoFoco.focus();
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir')); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', fecharModal);
});
document.querySelectorAll('[data-modal]').forEach(function (f) {
  f.addEventListener('click', function (e) { if (e.target === f) fecharModal(); });
});
document.addEventListener('keydown', function (e) {
  if (!modalAberto) return;
  if (e.key === 'Escape') { fecharModal(); return; }
  if (e.key === 'Tab') {
    var foco = modalAberto.querySelectorAll('button:not([disabled])');
