<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var ultimoFoco = null;

  function alternarGaveta(abrir) {
    gaveta.classList.toggle('aberta', abrir);
    gaveta.setAttribute('aria-hidden', String(!abrir));
    btnAjuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) { gaveta.querySelector('a').focus(); } else { btnAjuda.focus(); }
  }
  btnAjuda.addEventListener('click', function () {
    alternarGaveta(!gaveta.classList.contains('aberta'));
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && gaveta.classList.contains('aberta')) alternarGaveta(false);
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () { b.closest('.banner').remove(); });
  });

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var primeiro = m.querySelector('input, button');
    if (primeiro) primeiro.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  window.abrirModal = abrirModal;

  document.querySelectorAll('.modal').forEach(function (m) {
    m.querySelectorAll('.modal-x, .modal-acoes .btn:not(.btn-prim):not(.btn-perigo)')
      .forEach(function (b) { b.addEventListener('click', function () { fecharModal(m); }); });
    m.addEventListener('keydown', function (e) { if (e.key === 'Escape') fecharModal(m); });
  });

  var conv = document.getElementById('conv-email');
  var erroConv = document.getElementById('conv-erro');
  document.querySelector('#m0 .btn-prim').addEventListener('click', function () {
    var ok = conv.checkValidity();
    erroConv.hidden = ok;
    conv.setAttribute('aria-invalid', String(!ok));
    if (!ok) conv.focus();
  });
})();
</script>
</body>
