(function () {
  var foco = null;
  function abrir(el) {
    foco = document.activeElement;
    el.hidden = false;
    var alvo = el.querySelector('input') || el.querySelector('button');
    if (alvo) alvo.focus();
  }
  function fechar(el) {
    el.hidden = true;
    if (foco) foco.focus();
  }
  document.addEventListener('click', function (e) {
    var botaoFechar = e.target.closest('.modal-x, .modal-acoes .btn:not(.btn-prim):not(.btn-perigo)');
    if (botaoFechar) { fechar(botaoFechar.closest('.modal')); return; }
    var controle = e.target.closest('[aria-controls]');
    if (!controle) return;
    var alvo = document.getElementById(controle.getAttribute('aria-controls'));
    if (!alvo) return;
    if (controle.hasAttribute('aria-expanded')) {
      var estaFechado = alvo.hidden;
      alvo.hidden = !estaFechado;
      controle.setAttribute('aria-expanded', String(estaFechado));
    } else if (alvo.getAttribute('role') === 'dialog') {
      abrir(alvo);
    }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var aberto = document.querySelector('.modal:not([hidden])');
    if (aberto) fechar(aberto);
  });
})();
</script>
</body>
