(function(){
  var form=document.getElementById('form-checkout');
  var tituloBase=document.title;
  var resumo=document.getElementById('resumo-erros');
  var lista=document.getElementById('lista-erros');
  var mesmo=document.getElementById('mesmo-endereco');
  var blocoCob=document.getElementById('bloco-cobranca');
  var blocoOtp=document.getElementById('bloco-otp');
  var cartao=document.getElementById('cartao');

  function ativo(el){ return !el.disabled && !el.closest('[hidden]'); }
  function marcar(container, habilitar){
    container.querySelectorAll('input,select').forEach(function(e){ e.disabled=!habilitar; });
  }
  function alternarCobranca(){
    var mostrar=!mesmo.checked;
    blocoCob.hidden=!mostrar;
    marcar(blocoCob, mostrar);
  }
  function metodo(){ return form.querySelector('input[name="metodo"]:checked').value; }
  function alternarMetodo(){
    var cartaoOn=metodo()==='cartao';
    cartao.hidden=!cartaoOn; marcar(cartao, cartaoOn);
    blocoOtp.hidden=!cartaoOn; marcar(blocoOtp, cartaoOn);
  }
  function rotulo(el){
    var l=form.querySelector('label[for="'+el.id+'"]');
    return l ? l.textContent.trim() : (el.getAttribute('aria-label')||el.name);
  }
  function sugestao(el){
    if(el.validity.valueMissing) return 'preencha este campo';
    if(el.type==='email') return 'use o formato nome@exemplo.com.br';
    if(el.type==='tel') return 'informe DDD e número, por exemplo (11) 91234-5678';
    if(el.id==='cc-exp') return 'use o formato MM/AA';
    if(el.id==='cc-csc') return 'informe 3 ou 4 números';
    return 'verifique o formato';
  }
  function validar(){
    var erros=[];
    form.querySelectorAll('input,select').forEach(function(el){
      if(el.type==='radio'||el.type==='checkbox'||!ativo(el)) return;
      var ok=el.checkValidity();
      el.setAttribute('aria-invalid', ok?'false':'true');
      if(!ok) erros.push(el);
    });
    return erros;
  }
  form.addEventListener('submit', function(e){
    var erros=validar();
    if(!erros.length) return;
    e.preventDefault();
    lista.innerHTML='';
    erros.forEach(function(el){
      var li=document.createElement('li');
      var a=document.createElement('a');
      a.href='#'+el.id;
      a.textContent=rotulo(el)+': '+sugestao(el)+'.';
      a.addEventListener('click', function(ev){
        ev.preventDefault(); el.focus(); el.scrollIntoView({block:'center'});
      });
      li.appendChild(a); lista.appendChild(li);
    });
    resumo.hidden=false;
    document.title='Erro: '+tituloBase;
    resumo.focus();
  });

  document.getElementById('btn-cep').addEventListener('click', function(){
    var cep=document.getElementById('ent-cep');
    var st=document.getElementById('cep-status');
    var d=cep.value.replace(/\D/g,'');
    if(d.length!==8){
      cep.setAttribute('aria-invalid','true');
      st.textContent='CEP inválido. Informe 8 números, por exemplo 50030-230.';
      cep.focus(); return;
    }
    cep.setAttribute('aria-invalid','false');
    cep.value=d.slice(0,5)+'-'+d.slice(5);
    st.textContent='CEP válido. Confira o endereço abaixo.';
  });

  document.getElementById('btn-cupom').addEventListener('click', function(){
    var c=document.getElementById('cupom');
    var msg=document.getElementById('cupom-erro');
    if(!c.value.trim()){ msg.textContent='Digite o código do cupom.'; c.focus(); return; }
    msg.textContent='Não foi possível validar o cupom agora. Tente novamente em instantes.';
  });

  var otps=[1,2,3,4,5,6].map(function(i){ return document.getElementById('otp'+i); });
  otps.forEach(function(inp, idx){
    inp.addEventListener('input', function(){
      inp.value=inp.value.replace(/\D/g,'').slice(-1);
      if(inp.value && otps[idx+1]) otps[idx+1].focus();
    });
    inp.addEventListener('keydown', function(e){
      if(e.key==='Backspace' && !inp.value && otps[idx-1]) otps[idx-1].focus();
    });
    inp.addEventListener('paste', function(e){
      var t=(e.clipboardData||window.clipboardData).getData('text').replace(/\D/g,'').slice(0,6);
      if(!t) return;
      e.preventDefault();
      t.split('').forEach(function(c, k){ otps[k].value=c; });
      (otps[t.length-1]||otps[5]).focus();
    });
  });

  var btnRe=document.getElementById('btn-reenviar');
  var stRe=document.getElementById('reenvio-status');
  btnRe.addEventListener('click', function(){
    var t=30;
    btnRe.disabled=true;
    stRe.textContent='Pedido de novo código registrado. Você poderá pedir outro em 30 segundos.';
    var iv=setInterval(function(){
      t--;
      if(t<=0){
        clearInterval(iv);
        btnRe.disabled=false;
        stRe.textContent='Você já pode pedir um novo código.';
      }
    }, 1000);
  });

  mesmo.addEventListener('change', alternarCobranca);
  form.querySelectorAll('input[name="metodo"]').forEach(function(r){ r.addEventListener('change', alternarMetodo); });
  alternarCobranca();
  alternarMetodo();

  var veu=document.getElementById('veu');
  var dlgP=document.getElementById('dlg-p');
  var dlgCancelar=document.getElementById('dlg-cancelar');
  var dlgConfirmar=document.getElementById('dlg-confirmar');
  var tituloItens=document.getElementById('t-itens');
  var disparo=null, linhaAlvo=null;
  tituloItens.setAttribute('tabindex','-1');

  function abrirDialogo(btn, tr, nome){
    disparo=btn; linhaAlvo=tr;
    dlgP.textContent=nome+' será removido do pedido.';
    veu.hidden=false;
    dlgCancelar.focus();
  }
  function fecharDialogo(){
    veu.hidden=true;
    if(disparo && disparo.isConnected) disparo.focus();
    disparo=null; linhaAlvo=null;
  }
  dlgCancelar.addEventListener('click', fecharDialogo);
  dlgConfirmar.addEventListener('click', function(){
    if(linhaAlvo && linhaAlvo.parentNode) linhaAlvo.parentNode.removeChild(linhaAlvo);
    veu.hidden=true; disparo=null; linhaAlvo=null;
    tituloItens.focus();
  });
  veu.addEventListener('keydown', function(e){
    if(veu.hidden) return;
    if(e.key==='Escape'){ fecharDialogo(); return; }
    if(e.key==='Tab'){
      if(e.shiftKey && document.activeElement===dlgCancelar){ e.preventDefault(); dlgConfirmar.focus(); }
      else if(!e.shiftKey && document.activeElement===dlgConfirmar){ e.preventDefault(); dlgCancelar.focus(); }
    }
  });

  document.querySelectorAll('#itens tbody tr').forEach(function(tr){
    var nome=tr.cells[0].textContent.trim();
    var btn=tr.querySelector('.btn-link');
    btn.removeAttribute('onclick');
    btn.removeAttribute('aria-label');
    btn.textContent='Remover';
    var s=document.createElement('span');
    s.className='sr-only'; s.textContent=' '+nome;
    btn.appendChild(s);
    btn.addEventListener('click', function(){ abrirDialogo(btn, tr, nome); });
  });
})();
@@ FIM

