(function () {
  var live = document.getElementById('live');
  var fundoAtivo = null, gatilhoAtivo = null, linhaAtiva = null;
  var tabelas = document.querySelectorAll('#acessos table');

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }
  function focaveis(el) {
    return Array.prototype.slice.call(el.querySelectorAll('button:not([disabled]), a[href], input, select, textarea'));
  }
  function abrir(id, gatilho) {
    fundoAtivo = document.getElementById(id);
    gatilhoAtivo = gatilho;
    fundoAtivo.hidden = false;
    var alvo = fundoAtivo.querySelector('[data-cancelar]') || focaveis(fundoAtivo)[0];
    alvo.focus();
  }
  function fechar(fallback) {
    if (!fundoAtivo) return;
    fundoAtivo.hidden = true;
    fundoAtivo = null;
    var destino = gatilhoAtivo && document.body.contains(gatilhoAtivo) ? gatilhoAtivo : fallback;
    gatilhoAtivo = null;
    linhaAtiva = null;
    if (destino) destino.focus();
  }
  function atualizarContagem() {
    var n = tabelas[0].querySelectorAll('tbody tr').length;
    document.getElementById('contagem-acessos').textContent =
      n === 0 ? 'Nenhum aplicativo com acesso à sua conta' :
      n === 1 ? '1 aplicativo com acesso à sua conta' :
      n + ' aplicativos com acesso à sua conta';
  }

  document.addEventListener('keydown', function (e) {
    if (!fundoAtivo) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var itens = focaveis(fundoAtivo);
      var primeiro = itens[0], ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.addEventListener('click', function (e) {
    var abrirBtn = e.target.closest('[data-abrir]');
    if (abrirBtn) {
      var id = abrirBtn.getAttribute('data-abrir');
      linhaAtiva = abrirBtn.closest('tr');
      if (id === 'fundo-revogar' && linhaAtiva) {
        var app = linhaAtiva.querySelector('th').textContent;
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
        document.getElementById('dlg-revogar-d').textContent = 'O aplicativo ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(id, abrirBtn);
      return;
    }
    var confirmar = e.target.closest('[data-confirmar]');
    if (confirmar) {
      if (confirmar.getAttribute('data-confirmar') === 'revogar' && linhaAtiva) {
        var nome = linhaAtiva.querySelector('th').textContent;
        linhaAtiva.remove();
        atualizarContagem();
        anunciar('Acesso de ' + nome + ' revogado.');
        fechar(document.getElementById('h-acessos'));
      } else {
        anunciar('Exclusão da conta solicitada.');
        fechar(document.getElementById('zona-perigo'));
      }
      return;
    }
    if (e.target.closest('[data-fechar]')) fechar();
  });

  tabelas[0].querySelectorAll('tbody [data-abrir]').forEach(function (b) {
    b.setAttribute('aria-label', 'Revogar acesso de ' + b.closest('tr').querySelector('th').textContent);
  });

  tabelas[1].querySelectorAll('tbody button').forEach(function (b) {
    var tr = b.closest('tr');
    var dispositivo = tr.querySelector('th').textContent;
    b.setAttribute('aria-label', 'Encerrar sessão em ' + dispositivo);
    b.addEventListener('click', function () {
      tr.remove();
      anunciar('Sessão em ' + dispositivo + ' encerrada.');
      document.getElementById('h-acessos').focus();
    });
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var rotulo = p.getAttribute('aria-label');
    p.removeAttribute('role');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    var t = document.createElement('span');
    t.textContent = rotulo;
    p.parentNode.appendChild(t);
  });

  ['h-acessos', 'h-pref', 'zona-perigo'].forEach(function (id) {
    document.getElementById(id).setAttribute('tabindex', '-1');
  });

  var bio = document.getElementById('bio');
  var contador = document.getElementById('contador-bio');
  function contar() { contador.textContent = bio.value.length + '/' + bio.maxLength + ' caracteres'; }
  bio.addEventListener('input', contar);
  bio.form.addEventListener('reset', function () { setTimeout(contar, 0); });
  contar();

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var resumo = document.getElementById('resumo-erros');
    if (resumo) { resumo.focus(); anunciar('Há campos para corrigir antes de salvar.'); return; }
    anunciar('Perfil salvo.');
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.getElementById('h-pref').focus();
  });
})();
