(function () {
  var live = document.getElementById('live');
  var origem = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }
  function focaveis(el) {
    return Array.prototype.slice.call(el.querySelectorAll('button:not([disabled]), a[href], input:not([disabled]), select, textarea'));
  }
  function abrir(id, gatilho) {
    var m = document.getElementById(id);
    origem = gatilho;
    m.hidden = false;
    var inicial = m.querySelector('.btn:not(.perigo)') || focaveis(m)[0];
    if (inicial) inicial.focus();
  }
  function fechar(m) {
    m.hidden = true;
    if (origem) { origem.focus(); origem = null; }
  }
  function modalAberto() {
    return document.querySelector('[data-modal]:not([hidden])');
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      if (b.classList.contains('perigo')) anunciar('Ação confirmada.');
      fechar(b.closest('[data-modal]'));
    });
  });
  document.addEventListener('keydown', function (e) {
    var m = modalAberto();
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var lista = focaveis(m);
    if (!lista.length) return;
    var primeiro = lista[0], ultimo = lista[lista.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });
