(function(){
  var ajuda=document.querySelector('[aria-controls="gaveta"]');
  var gaveta=document.getElementById('gaveta');
  function gavetaAbrir(abrir){
    gaveta.hidden=!abrir;
    ajuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gaveta.querySelector('a').focus();}
  }
  ajuda.addEventListener('click',function(){gavetaAbrir(gaveta.hidden);});
  document.addEventListener('keydown',function(e){
    if(e.key!=='Escape')return;
    var abertos=document.querySelectorAll('.modal:not([hidden])');
    if(abertos.length){abertos.forEach(function(m){m.hidden=true;});return;}
    if(!gaveta.hidden){gavetaAbrir(false);ajuda.focus();}
  });
  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){b.closest('.banner').remove();});
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.classList.contains('modal-x')||e.target.hasAttribute('data-fecha')){m.hidden=true;}
    });
  });
  var conf=document.getElementById('confirma-exclusao');
  var excluir=document.getElementById('btn-excluir');
