@@ DEPOIS
(function () {
  function $(s) { return document.querySelector(s); }
  function $$(s) { return Array.prototype.slice.call(document.querySelectorAll(s)); }
  function anunciar(t) { var l = $('#live'); l.textContent = ''; setTimeout(function () { l.textContent = t; }, 50); }
  function agora() { return new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); }
  function mostrarBanner(msg, desfazer) {
    $('#banner-msg').textContent = msg;
    $('#btn-desfazer').hidden = !desfazer;
    $('#banner-sucesso').hidden = false;
    anunciar(msg);
  }
  $('#btn-dispensar').addEventListener('click', function () { $('#banner-sucesso').hidden = true; });

  var focoAnterior = null;
  function abrir(id) {
    var f = document.getElementById(id);
    focoAnterior = document.activeElement;
    f.hidden = false;
    f.querySelector('input, button:not([disabled])').focus();
  }
  function fechar(f) { f.hidden = true; if (focoAnterior) focoAnterior.focus(); }
  $$('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir')); });
  });
  $$('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) {
      if (e.target === f || e.target.hasAttribute('data-fechar')) fechar(f);
    });
    f.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(f); return; }
      if (e.key !== 'Tab') return;
      var els = f.querySelectorAll('input, button:not([disabled])');
      var primeiro = els[0], ultimo = els[els.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  var campoConf = $('#confirmar-exclusao'), btnDef = $('#btn-excluir-definitivo');
  campoConf.addEventListener('input', function () { btnDef.disabled = campoConf.value !== 'EXCLUIR'; });
  btnDef.addEventListener('click', function () {
    campoConf.value = ''; btnDef.disabled = true;
    fechar($('#fundo-excluir'));
    anunciar('Pedido de exclusão registrado. Você receberá um e-mail de confirmação.');
  });

  function emailValido(v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()); }
  function telefoneValido(v) { return /^\(?\d{2}\)?\s?\d{4,5}-?\d{4}$/.test(v.trim()); }
  function marcar(id, erroId, valido) {
    var campo = document.getElementById(id), erro = document.getElementById(erroId);
    erro.hidden = valido;
    campo.setAttribute('aria-invalid', valido ? 'false' : 'true');
    return valido;
  }
  $('#form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var okEmail = marcar('email', 'erro-email', emailValido($('#email').value));
    var okTel = marcar('telefone', 'erro-telefone', telefoneValido($('#telefone').value));
    if (!okEmail || !okTel) {
      (okEmail ? $('#telefone') : $('#email')).focus();
      anunciar('Corrija os campos destacados antes de salvar.');
      return;
    }
    anunciar('Perfil salvo às ' + agora() + '.');
  });

  $('#form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    mostrarBanner('Preferências salvas às ' + agora() + '.', false);
  });

  var ultimo = null;
  function atualizarContagem() {
    var n = $('#acessos table').querySelectorAll('tbody tr:not(.revogado)').length;
    $('#contagem-acessos').textContent = n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
  }
  $$('[data-revogar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var linha = b.closest('tr'), situacao = linha.querySelector('.estado');
      ultimo = { linha: linha, botao: b, situacao: situacao.innerHTML };
      situacao.innerHTML = '<span class="ponto exp" aria-hidden="true"></span>Revogado';
      linha.classList.add('revogado');
      b.hidden = true;
      atualizarContagem();
      mostrarBanner('Acesso de ' + b.getAttribute('data-revogar') + ' revogado.', true);
      $('#btn-desfazer').focus();
    });
  });
  $('#btn-desfazer').addEventListener('click', function () {
    if (!ultimo) return;
    ultimo.linha.classList.remove('revogado');
    ultimo.linha.querySelector('.estado').innerHTML = ultimo.situacao;
    ultimo.botao.hidden = false;
    ultimo.botao.focus();
    ultimo = null;
    atualizarContagem();
    mostrarBanner('Acesso restaurado.', false);
  });
})();
@@ FIM

