@@ DEPOIS
(function () {
  var gatilho = null;
  var fundoAberto = null;

  function abrirModal(id, origem) {
    gatilho = origem;
    fundoAberto = document.getElementById(id);
    fundoAberto.hidden = false;
    fundoAberto.querySelector('[data-fechar]').focus();
  }

  function fecharModal() {
    if (!fundoAberto) return;
    fundoAberto.hidden = true;
    fundoAberto = null;
    if (gatilho) gatilho.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fecharModal);
  });
  document.addEventListener('keydown', function (e) {
    if (!fundoAberto) return;
    if (e.key === 'Escape') { fecharModal(); return; }
    if (e.key !== 'Tab') return;
    var botoes = fundoAberto.querySelectorAll('button');
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
