<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.getElementById('btn-ajuda');
  var modalRetorno = null;

  function fecharAjuda() {
    gaveta.hidden = true;
    btnAjuda.setAttribute('aria-expanded', 'false');
    btnAjuda.focus();
  }

  btnAjuda.addEventListener('click', function () {
    if (gaveta.hidden) {
      gaveta.hidden = false;
      btnAjuda.setAttribute('aria-expanded', 'true');
      gaveta.querySelector('a').focus();
    } else {
      fecharAjuda();
    }
  });

  function abrirModal(m) {
    modalRetorno = document.activeElement;
    m.hidden = false;
    var f = m.querySelector('input') || m.querySelector('.btn-prim') || m.querySelector('button');
    if (f) f.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    if (modalRetorno) modalRetorno.focus();
    modalRetorno = null;
  }

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      var t = e.target;
      if (t === m || t.closest('.modal-x') || t.closest('.modal-acoes button:not(.btn-prim):not(.btn-perigo)')) {
        fecharModal(m);
      }
    });
  });

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      var m = document.getElementById(b.getAttribute('aria-controls'));
      if (m) abrirModal(m);
    });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var aberto = document.querySelector('.modal:not([hidden])');
    if (aberto) fecharModal(aberto);
    else if (!gaveta.hidden) fecharAjuda();
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var alvo = document.getElementById(b.getAttribute('data-fechar'));
      if (alvo) alvo.remove();
    });
  });

  var email = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  document.querySelector('#m0 .btn-prim').addEventListener('click', function () {
    if (email.checkValidity()) {
      erro.hidden = true;
      email.removeAttribute('aria-invalid');
    } else {
      erro.hidden = false;
      email.setAttribute('aria-invalid', 'true');
      email.focus();
    }
  });
})();
</script>
</body>
