(function () {
  var ultimoFoco = null;
  function abrir(modal) {
    ultimoFoco = document.activeElement;
    modal.hidden = false;
    var primeiro = modal.querySelector('.btn:not(.perigo)') || modal.querySelector('button');
    primeiro.focus();
  }
  function fechar(modal) {
    modal.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var modal = document.getElementById(b.getAttribute('data-abrir'));
      var linha = b.closest('tr');
      if (linha && modal.id === 'fundo-revogar') {
        var nome = linha.querySelector('th').textContent;
        document.getElementById('dlg-revogar-t').textContent = 'Revogar acesso de ' + nome + '?';
        document.getElementById('dlg-revogar-d').textContent = nome + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(modal);
    });
  });
  document.querySelectorAll('[data-modal]').forEach(function (modal) {
    modal.addEventListener('click', function (e) { if (e.target === modal) fechar(modal); });
    modal.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(modal); return; }
      if (e.key === 'Tab') {
        var botoes = modal.querySelectorAll('button:not([disabled])');
        var primeiro = botoes[0], ultimo = botoes[botoes.length - 1];
        if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
        else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
      }
    });
    modal.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fechar(modal); });
    });
  });
  var formPerfil = document.getElementById('form-perfil');
  var salvarPerfil = formPerfil.querySelector('button[type="submit"]');
  formPerfil.addEventListener('input', function () { salvarPerfil.disabled = false; });
  formPerfil.addEventListener('change', function () { salvarPerfil.disabled = false; });
  formPerfil.addEventListener('reset', function () { setTimeout(function () { salvarPerfil.disabled = true; }, 0); });
  var bio = document.getElementById('bio');
  var contador = document.getElementById('contador-bio');
  function atualizarContador() { contador.textContent = bio.maxLength - bio.value.length; }
  bio.addEventListener('input', atualizarContador);
  atualizarContador();
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
