    gatilhoModal = gatilho;
    m.hidden = false;
    var f = m.querySelector('input,button,a[href]');
    if(f) f.focus();
  }
  function fecharModal(m){
    m.hidden = true;
    if(gatilhoModal){ gatilhoModal.focus(); gatilhoModal = null; }
  }
  document.querySelectorAll('[aria-controls]').forEach(function(b){
    var alvo = document.getElementById(b.getAttribute('aria-controls'));
    if(!alvo) return;
    b.addEventListener('click', function(){
      if(alvo.id === 'gaveta'){
        var abrir = alvo.hidden;
        alvo.hidden = !abrir;
        b.setAttribute('aria-expanded', String(abrir));
      } else if(alvo.classList.contains('modal')){
        abrirModal(alvo, b);
      }
    });
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click', function(e){
      if(e.target === m || e.target.classList.contains('modal-x') || e.target.textContent.trim() === 'Cancelar'){
        fecharModal(m);
      }
    });
  });
  document.addEventListener('keydown', function(e){
    if(e.key !== 'Escape') return;
    document.querySelectorAll('.modal:not([hidden])').forEach(fecharModal);
  });
})();
</script>
