(function () {
  var seletorFocavel = 'button:not([disabled]), a[href], input:not([disabled]), select, textarea, [tabindex]:not([tabindex="-1"])';
  var ultimoGatilho = null;
  var live = document.getElementById('live');

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrirModal(fundo) {
    ultimoGatilho = document.activeElement;
    fundo.hidden = false;
    var dlg = fundo.querySelector('[role="alertdialog"]');
    var inicial = dlg.querySelector('[data-fechar]:not(.perigo)') || dlg.querySelector(seletorFocavel);
    inicial.focus();
  }

  function fecharModal(fundo) {
    fundo.hidden = true;
    if (ultimoGatilho) ultimoGatilho.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abrir')));
    });
  });

  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fecharModal(fundo); });
    });
    fundo.addEventListener('click', function (e) {
      if (e.target === fundo) fecharModal(fundo);
    });
    fundo.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(fundo); return; }
      if (e.key !== 'Tab') return;
      var itens = fundo.querySelectorAll(seletorFocavel);
      var primeiro = itens[0];
      var ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  document.querySelectorAll('#acessos tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
