  function sincronizarCobranca() { $('bloco-cobranca').hidden = mesmo.checked; }
  mesmo.addEventListener('change', sincronizarCobranca);
  sincronizarCobranca();

  var metodos = document.querySelectorAll('input[name="metodo"]');
  function sincronizarMetodo() {
    $('cartao').hidden = form.elements['metodo'].value !== 'cartao';
