      var texto = (e.clipboardData || window.clipboardData).getData('text').replace(/\D/g, '').slice(0, 6);
      if (!texto) return;
      e.preventDefault();
      for (var k = 0; k < texto.length && otp[i + k]; k++) otp[i + k].value = texto[k];
      otp[Math.min(i + texto.length, otp.length - 1)].focus();
