    form.querySelectorAll('input[required], select[required]').forEach(function (el) {
      if (el.closest('.otp') || el.closest('[hidden]')) return;
      var id = el.id + '-erro';
      var antigo = $(id);
      if (antigo) antigo.remove();
      el.removeAttribute('aria-invalid');
      if (el.value.trim()) return;
      var p = document.createElement('p');
      p.className = 'erro-campo';
      p.id = id;
      p.textContent = 'Preencha este campo.';
      el.closest('.campo').appendChild(p);
      el.setAttribute('aria-invalid', 'true');
      var desc = (el.getAttribute('aria-describedby') || '').split(' ').filter(function (x) { return x && x !== id; });
      desc.push(id);
      el.setAttribute('aria-describedby', desc.join(' '));
      if (!primeiroInvalido) primeiroInvalido = el;
    });
    var otpVazio = otp.filter(function (i) { return !i.value; })[0];
    if (!primeiroInvalido && otpVazio) primeiroInvalido = otpVazio;
    if (primeiroInvalido) {
      e.preventDefault();
      primeiroInvalido.focus();
    }
  });
})();
</script>
