<script>
(function () {
  var btnAjuda = document.getElementById('btn-ajuda');
  var gaveta = document.getElementById('gaveta');

  function setAjuda(aberta) {
    gaveta.classList.toggle('aberta', aberta);
    btnAjuda.setAttribute('aria-expanded', String(aberta));
  }

  btnAjuda.addEventListener('click', function () {
    var abrir = !gaveta.classList.contains('aberta');
    setAjuda(abrir);
    if (abrir) gaveta.querySelector('a').focus();
  });

  document.getElementById('fechar-ajuda').addEventListener('click', function () {
    setAjuda(false);
    btnAjuda.focus();
  });

  var ultimoGatilho = null;

  function abrirModal(modal, gatilho) {
    ultimoGatilho = gatilho;
    modal.hidden = false;
    var primeiro = modal.querySelector('input, button');
    if (primeiro) primeiro.focus();
  }

  function fecharModal(modal) {
    modal.hidden = true;
    if (ultimoGatilho) ultimoGatilho.focus();
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (g) {
    g.addEventListener('click', function () {
      abrirModal(document.getElementById(g.getAttribute('aria-controls')), g);
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x') ||
          e.target.closest('.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)')) {
        fecharModal(m);
      }
    });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    if (gaveta.classList.contains('aberta')) {
      setAjuda(false);
      btnAjuda.focus();
      return;
    }
    var aberto = document.querySelector('.modal:not([hidden])');
    if (aberto) fecharModal(aberto);
  });
})();
</script>
</body>
