<script>
(function () {
  var form = document.querySelector('form');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var titulo = document.getElementById('titulo-erros');
  var tentou = false;

  // Obrigatórios: derivados do asterisco visível de cada rótulo
  document.querySelectorAll('label .obrig').forEach(function (o) {
    var ctrl = o.closest('label').control;
    if (ctrl) ctrl.required = true;
  });

  function so(v) { return (v || '').replace(/\D/g, ''); }

  function cpfValido(c) {
    if (!/^\d{11}$/.test(c) || /^(\d)\1{10}$/.test(c)) return false;
    for (var t = 9; t < 11; t++) {
      var soma = 0;
      for (var i = 0; i < t; i++) soma += Number(c[i]) * (t + 1 - i);
      if (((soma * 10) % 11) % 10 !== Number(c[t])) return false;
    }
    return true;
  }

  function dataValida(d, m, a) {
    if (!d || !m || !a) return false;
    var dt = new Date(a, m - 1, d);
    return dt.getFullYear() === a && dt.getMonth() === m - 1 &&
      dt.getDate() === d && a >= 1900 && dt <= new Date();
  }

  function validar() {
    var v = function (id) { return document.getElementById(id).value.trim(); };
    var e = {};
    form.querySelectorAll('[required]').forEach(function (c) {
      var vazio = c.type === 'checkbox' ? !c.checked : !c.value.trim();
      if (vazio) e[c.id] = c.type === 'checkbox' ? 'Marque esta opção para continuar.' : 'Campo obrigatório.';
    });
    var regras = {
      nome: v('nome').split(/\s+/).length >= 2 ? '' : 'Informe nome e sobrenome.',
      cpf: cpfValido(so(v('cpf'))) ? '' : 'Informe um CPF válido com 11 dígitos.',
      email: (!v('email') || document.getElementById('email').validity.valid) ? '' : 'Informe um e-mail completo, como nome@exemplo.com.br.',
      tel: [10, 11].indexOf(so(v('tel')).length) !== -1 ? '' : 'Informe o telefone com DDD, com 10 ou 11 dígitos.',
      dia: dataValida(Number(v('dia')), Number(v('mes')), Number(v('ano'))) ? '' : 'Informe uma data de nascimento válida.',
      'cep-res': so(v('cep-res')).length === 8 ? '' : 'Informe um CEP com 8 dígitos.'
    };
    Object.keys(regras).forEach(function (k) {
      if (regras[k] && !e[k]) e[k] = regras[k];
    });
    return e;
  }

  function marcar(c, msg) {
    var id = 'e-' + c.id;
    var p = document.getElementById(id);
    var campo = c.closest('.campo');
    if (!p && msg) {
      p = document.createElement('p');
      p.className = 'erro';
      p.id = id;
      if (campo) campo.appendChild(p);
      else c.closest('label').insertAdjacentElement('afterend', p);
    }
    if (p) { p.textContent = msg; p.hidden = !msg; }
    if (campo) campo.classList.toggle('tem-erro', !!msg);
    if (msg || c.hasAttribute('aria-invalid')) c.setAttribute('aria-invalid', msg ? 'true' : 'false');
    if (msg) {
      var d = (c.getAttribute('aria-describedby') || '').split(' ').filter(Boolean);
      if (d.indexOf(id) === -1) d.push(id);
      c.setAttribute('aria-describedby', d.join(' '));
    }
  }

  function nomeCampo(c) {
    return c.labels && c.labels[0] ? c.labels[0].textContent.replace(/\*/g, '').trim() : c.id;
  }

  function resumoErros(e) {
    var ids = Object.keys(e);
    lista.innerHTML = '';
    ids.forEach(function (id) {
      var c = document.getElementById(id);
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + id;
      a.textContent = nomeCampo(c) + ': ' + e[id];
      a.addEventListener('click', function (ev) { ev.preventDefault(); c.focus(); });
      li.appendChild(a);
      lista.appendChild(li);
    });
    titulo.textContent = ids.length === 1 ? 'Há 1 problema nesta etapa' : 'Há ' + ids.length + ' problemas nesta etapa';
    resumo.hidden = ids.length === 0;
    if (ids.length) resumo.focus();
  }

  // Valida somente ao tentar continuar; depois, revalida ao sair do campo
  var tentouAntes = false;
  form.addEventListener('submit', function (ev) {
    tentouAntes = true;
    tentou = true;
    var e = validar();
    form.querySelectorAll('input[id],select[id]').forEach(function (c) {
      marcar(c, e[c.id] || '');
    });
    resumoErros(e);
    if (Object.keys(e).length) ev.preventDefault();
  });

  form.addEventListener('change', function (ev) {
    if (!tentou || !ev.target.id) return;
    var e = validar();
    marcar(ev.target, e[ev.target.id] || '');
  });

  // Mesmo endereço: copia o residencial para correspondência
  document.getElementById('mesmo').addEventListener('change', function (ev) {
    if (!ev.target.checked) return;
    ['cep', 'rua', 'num', 'comp', 'bairro', 'cidade', 'uf'].forEach(function (p) {
      document.getElementById(p + '-cor').value = document.getElementById(p + '-res').value;
    });
  });

  // Abas com aria-selected e navegação por setas
  var abas = Array.prototype.slice.call(document.querySelectorAll('[role=tab]'));
  function ativarAba(n) {
    abas.forEach(function (a, i) {
      var sel = i === n;
      var painel = document.getElementById(a.getAttribute('aria-controls'));
      a.setAttribute('aria-selected', String(sel));
      a.tabIndex = sel ? 0 : -1;
      a.classList.toggle('aba-ativa', sel);
      painel.hidden = !sel;
      painel.setAttribute('aria-labelledby', a.id);
    });
  }
  abas.forEach(function (a, i) {
    a.addEventListener('click', function () { ativarAba(i); });
    a.addEventListener('keydown', function (ev) {
      var n = ev.key === 'ArrowRight' ? (i + 1) % abas.length
            : ev.key === 'ArrowLeft' ? (i - 1 + abas.length) % abas.length : -1;
      if (n < 0) return;
      ev.preventDefault();
      abas[n].focus();
      ativarAba(n);
    });
  });
  ativarAba(0);
})();
