(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  function abrir(m, gatilho) {
    m.__gatilho = gatilho;
    m.hidden = false;
    var f = m.querySelector('input, button:not([disabled])');
    if (f) f.focus();
  }
  function fechar(m) {
    if (!m) return;
    m.hidden = true;
    if (m.id === 'fundo-excluir') {
      document.getElementById('confirma-excluir').value = '';
      document.getElementById('btn-confirmar-excluir').disabled = true;
    }
    if (m.__gatilho) m.__gatilho.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var linha = b.closest('tr');
    var nome = linha ? linha.querySelector('th').textContent : '';
    if (nome) b.setAttribute('aria-label', b.textContent.trim() + ': ' + nome);
    b.addEventListener('click', function () {
      if (b.getAttribute('data-abrir') === 'fundo-revogar' && nome) {
        document.getElementById('dlg-revogar-d').textContent = 'O aplicativo ' + nome + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });

  document.querySelectorAll('#acessos tbody button:not([data-abrir])').forEach(function (b) {
    var linha = b.closest('tr');
    if (linha) b.setAttribute('aria-label', b.textContent.trim() + ': ' + linha.querySelector('th').textContent);
  });

  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var t = document.createElement('span');
    t.textContent = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(t);
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
  });
  document.addEventListener('keydown', function (e) {
