<script>
(function () {
  var live = document.getElementById('live');
  var ultimoFoco = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrirModal(id) {
    var fundo = document.getElementById(id);
    ultimoFoco = document.activeElement;
    fundo.hidden = false;
    var inicial = fundo.querySelector('.btn:not(.perigo)') || fundo.querySelector('button');
    if (inicial) inicial.focus();
  }

  function fecharModal(fundo) {
    fundo.hidden = true;
    if (ultimoFoco && document.body.contains(ultimoFoco)) ultimoFoco.focus();
    ultimoFoco = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir')); });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = b.closest('[data-modal]');
      fecharModal(fundo);
      if (b.classList.contains('perigo')) {
        if (fundo.id === 'fundo-revogar') anunciar('Acesso revogado.');
        if (fundo.id === 'fundo-excluir') anunciar('Exclusão de conta solicitada.');
      }
    });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fecharModal(aberto); return; }
    if (e.key === 'Tab') {
      var foc = aberto.querySelectorAll('button:not([disabled])');
      var primeiro = foc[0];
      var ultimo = foc[foc.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault(); ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault(); primeiro.focus();
      }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.querySelector('#form-prefs input').focus();
  });

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('resumo-erros').focus();
    anunciar('Corrija os campos destacados para salvar o perfil.');
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });
})();
</script>
