(function () {
  var ultimoFoco = null;
  var gaveta = document.getElementById('gaveta');
  var botaoAjuda = document.querySelector('[aria-controls="gaveta"]');

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var alvo = m.querySelector('[autofocus]') || m.querySelector('input') || m.querySelector('.modal-acoes .btn-prim');
    if (alvo) alvo.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus();
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('aria-controls')));
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.hasAttribute('data-fechar')) fecharModal(m);
    });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(m); return; }
      if (e.key !== 'Tab') return;
      var f = m.querySelectorAll('button:not([disabled]),input,a[href]');
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  if (botaoAjuda && gaveta) {
    botaoAjuda.addEventListener('click', function () {
      var aberta = botaoAjuda.getAttribute('aria-expanded') === 'true';
      botaoAjuda.setAttribute('aria-expanded', String(!aberta));
      gaveta.hidden = aberta;
      if (!aberta) gaveta.querySelector('a').focus();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && !gaveta.hidden) {
        gaveta.hidden = true;
        botaoAjuda.setAttribute('aria-expanded', 'false');
        botaoAjuda.focus();
      }
    });
  }

  var email = document.getElementById('conv-email');
  var erroEmail = document.getElementById('conv-erro');
  var btnConvite = document.querySelector('#m0 .btn-prim');
  if (btnConvite && email) {
    btnConvite.addEventListener('click', function () {
      if (email.checkValidity()) {
        email.removeAttribute('aria-invalid');
        erroEmail.hidden = true;
      } else {
        email.setAttribute('aria-invalid', 'true');
        erroEmail.hidden = false;
        email.focus();
      }
    });
  }

  var banner = document.querySelector('.banner');
  if (banner) {
    banner.querySelector('.btn-txt').addEventListener('click', function () {
      document.getElementById('conteudo').focus();
      banner.remove();
    });
  }
})();
