var itemPendente = null;
var focoAnterior = null;

function buscarCep(){
  var campo = document.getElementById('ent-cep');
  var status = document.getElementById('cep-status');
  var digitos = campo.value.replace(/\D/g, '');
  if (digitos.length !== 8) {
    campo.setAttribute('aria-invalid', 'true');
    status.textContent = 'Informe um CEP com 8 dígitos.';
    campo.focus();
    return;
  }
  campo.removeAttribute('aria-invalid');
  status.textContent = 'Endereço localizado.';
}

function aplicarCupom(){
  var i = document.getElementById('cupom');
  var erro = document.getElementById('cupom-erro');
  erro.textContent = i.value.trim() ? 'Este cupom expirou em 31/10.' : 'Digite um código de cupom.';
  erro.hidden = false;
  i.setAttribute('aria-invalid', 'true');
  i.focus();
}

function reenviar(){
  var o = document.getElementById('otp');
  o.value = '';
  document.getElementById('otp-status').textContent = 'Novo código enviado por SMS.';
  o.focus();
}

function alternarCobranca(c){
  var b = document.getElementById('bloco-cobranca');
  b.hidden = c.checked;
  b.querySelectorAll('input,select').forEach(function (el) { el.disabled = c.checked; });
}

function alternarMetodo(v){
  var cartao = v === 'cartao';
  var campos = document.getElementById('cartao');
  var otp = document.getElementById('otp').closest('.bloco');
  campos.hidden = !cartao;
  otp.hidden = !cartao;
  campos.querySelectorAll('input,select').forEach(function (el) { el.disabled = !cartao; });
  otp.querySelectorAll('input').forEach(function (el) { el.disabled = !cartao; });
}

function usarOutroCartao(){
  document.querySelector('input[name="metodo"][value="cartao"]').checked = true;
  alternarMetodo('cartao');
  var n = document.getElementById('cc-num');
  n.value = '';
  n.focus();
}

function abrirDialogo(n){
  focoAnterior = document.activeElement;
  itemPendente = n;
  document.getElementById('dlg-p').textContent = '“' + n + '” será removido do pedido.';
  var v = document.getElementById('veu');
  v.hidden = false;
  v.querySelector('.btn-sec').focus();
}

function fecharDialogo(){
  document.getElementById('veu').hidden = true;
  var alvo = (focoAnterior && focoAnterior.isConnected) ? focoAnterior : document.getElementById('t-itens');
  alvo.focus();
}

function confirmarRemocao(){
  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('.col-nome');
    if (nome && nome.textContent === itemPendente) { tr.remove(); }
  });
  fecharDialogo();
}

document.addEventListener('keydown', function (e) {
  var v = document.getElementById('veu');
  if (v.hidden) { return; }
  if (e.key === 'Escape') { fecharDialogo(); return; }
  if (e.key === 'Tab') {
    var botoes = v.querySelectorAll('button');
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});

document.getElementById('form-checkout').addEventListener('submit', function (e) {
  e.preventDefault();
  var conf = document.getElementById('confirmacao');
  conf.hidden = false;
  conf.tabIndex = -1;
  conf.focus();
});

document.getElementById('t-itens').tabIndex = -1;
alternarCobranca(document.querySelector('input[name="cobranca_igual"]'));
alternarMetodo(document.querySelector('input[name="metodo"]:checked').value);
@@ FIM
