(function () {
  var live = document.getElementById('live');
  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  document.querySelectorAll('.ponto[role="img"]').forEach(function (p) {
    var rotulo = p.getAttribute('aria-label');
    p.removeAttribute('role');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', ' ' + rotulo);
  });

  document.querySelectorAll('table tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
    tr.querySelectorAll('td .btn').forEach(function (b) {
      var t = b.textContent.trim();
      if (t === 'Revogar acesso' || t === 'Encerrar sessão') {
        var s = document.createElement('span');
        s.className = 'sr-only';
        s.textContent = ' de ' + nome;
        b.appendChild(s);
      }
    });
  });

  var ultimoFoco = null;

  function abrir(id) {
    ultimoFoco = document.activeElement;
    var fundo = document.getElementById(id);
    if (id === 'fundo-revogar') {
      var app = ultimoFoco.closest('tr').querySelector('th').textContent.trim();
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
    }
    fundo.hidden = false;
    var botoes = fundo.querySelectorAll('[data-fechar]');
    botoes[botoes.length - 1].focus();
  }

  function fechar(fundo) {
    fundo.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
    ultimoFoco = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir')); });
  });

  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fechar(fundo); });
    });
    fundo.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(fundo); return; }
      if (e.key !== 'Tab') return;
      var foc = fundo.querySelectorAll('button:not([disabled])');
      var primeiro = foc[0];
      var ultimo = foc[foc.length - 1];
