:root{
  --bg:#f4f6f8; --surface:#ffffff; --ink:#1d2733; --muted:#4b5968; --brand:#0b5cad; --brand-ink:#ffffff;
  --borda:#c3ccd6; --perigo:#b42318; --perigo-bg:#fdecea; --ok:#14653a; --ok-bg:#e4f4ea;
  --aviso:#7a4d00; --aviso-bg:#fff3d6; --raio:8px; --esp:1rem; --sombra:0 1px 2px rgba(16,24,40,.08);
}
*{box-sizing:border-box}
html{font-size:100%}
body{margin:0;background:var(--bg);color:var(--ink);font-family:"Segoe UI",Roboto,Arial,sans-serif;font-size:1rem;line-height:1.6}
