.pular{position:absolute;left:-999px;top:0;background:#fff;padding:.5rem}
.pular:focus{left:.5rem;top:.5rem;z-index:30}
.topo{background:var(--surface);border-bottom:1px solid var(--borda)}
.topo-in{max-width:1180px;margin:0 auto;padding:.625rem var(--esp);display:flex;flex-wrap:wrap;align-items:center;gap:1rem}
.marca{font-weight:700;font-size:1.125rem;margin:0}
.area-nav{flex:1 1 auto;min-width:0}
.nav-topo{display:flex;gap:.25rem;list-style:none;margin:0 0 0 .5rem;padding:0;overflow-x:auto}
.nav-topo a{display:flex;align-items:center;min-height:44px;padding:0 .625rem;border-radius:6px;text-decoration:none;color:var(--ink);font-size:.9375rem;white-space:nowrap}
.nav-topo a[aria-current="page"]{background:#e3eefa;color:var(--brand);font-weight:600}
.btn-inicio{display:inline-flex;align-items:center;min-height:44px;padding:0 .75rem;border:1px solid var(--borda);border-radius:6px;background:#fff;color:var(--ink);text-decoration:none;font-size:.9375rem}
.usuario-chip{display:flex;align-items:center;gap:.5rem;font-size:.875rem}
.avatar{display:inline-flex;align-items:center;justify-content:center;width:2rem;height:2rem;border-radius:50%;background:var(--brand);color:var(--brand-ink);font-size:.75rem;font-weight:700}
.avatar.grande{width:4rem;height:4rem;font-size:1.25rem}
.btn-icone{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid var(--borda);border-radius:6px;background:#fff;color:var(--ink);cursor:pointer}
.layout{max-width:1180px;margin:0 auto;padding:1.5rem var(--esp);display:grid;grid-template-columns:13.75rem minmax(0,1fr);gap:1.5rem}
.lateral ul{list-style:none;margin:0;padding:0;position:sticky;top:1rem}
.lateral a{display:flex;align-items:center;min-height:44px;padding:.5rem .75rem;border-radius:6px;text-decoration:none;color:var(--ink);font-size:.9375rem}
.lateral a:hover{background:#e8edf2}
.conteudo{min-width:0}
.titulo-pagina{margin-bottom:.25rem}
.lead{color:var(--muted);margin-bottom:1.25rem;max-width:72ch}
.cartao{background:var(--surface);border:1px solid var(--borda);border-radius:var(--raio);box-shadow:var(--sombra);padding:1.5rem;margin-bottom:1.5rem;scroll-margin-top:1rem}
