.banner-t{display:block;font-size:1rem;font-weight:700}
.banner-txt{flex:1;font-size:.9375rem}
.banner .btn-icone{width:44px;height:44px;border:0;background:transparent;color:inherit}
.aviso{display:flex;gap:.625rem;align-items:flex-start;padding:.75rem .875rem;border-radius:var(--raio);background:var(--aviso-bg);border:1px solid #e3b341;color:var(--aviso);margin:0 0 1rem}
.aviso p{margin:0;font-size:.9375rem}
.resumo{border:2px solid var(--perigo);background:var(--perigo-bg);border-radius:var(--raio);padding:.875rem 1.125rem;margin-bottom:1.25rem}
.resumo h2{font-size:1.0625rem;color:var(--perigo)}
.resumo ul{margin:0;padding-left:1.25rem}
.resumo a{color:var(--perigo);font-weight:600}
fieldset{border:1px solid var(--borda);border-radius:6px;margin:1rem 0 0;padding:.75rem 1rem}
legend{font-weight:600;font-size:.9375rem;padding:0 .375rem}
.opcao{display:flex;gap:.625rem;align-items:center;min-height:44px;font-size:.9375rem}
.opcao input{width:20px;height:20px;flex:none;margin:0}
.tab-wrap{overflow-x:auto;margin-top:.75rem;border-radius:6px}
table{width:100%;min-width:36rem;border-collapse:collapse;font-size:.9375rem}
caption{text-align:left;font-weight:600;padding:0 0 .375rem;font-size:1rem}
th{text-align:left;padding:.5rem .625rem;border-bottom:2px solid var(--borda);font-size:.8125rem;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}
td{padding:.625rem;border-bottom:1px solid #e4e9ee;vertical-align:middle}
.chip{display:inline-block;padding:.125rem .5rem;border-radius:999px;background:#eaf0f6;font-size:.8125rem;color:#2b3a49}
.ponto{display:inline-block;width:.75rem;height:.75rem;border-radius:50%;vertical-align:middle;margin-right:.375rem}
.ponto.ok{background:var(--ok)}
.ponto.pausa{background:#a0670a}
.estado{display:inline-flex;align-items:center;font-size:.875rem}
.contagem{font-weight:600;margin:.75rem 0 0;font-size:.9375rem}
.vazio{text-align:center;padding:1.75rem 1rem;border:2px dashed var(--borda);border-radius:var(--raio);margin-top:.75rem;color:var(--muted)}
.vazio h3{color:var(--ink)}
.falha{display:flex;flex-direction:column;gap:.375rem;padding:1rem;border:1px solid var(--perigo);background:var(--perigo-bg);border-radius:var(--raio);margin-top:.75rem;align-items:flex-start}
.falha h3{color:var(--perigo);margin:0}
.texto{max-width:72ch;margin:.75rem 0;color:#26323f}
.zona-perigo{border-color:var(--perigo)}
.zona-perigo h2{color:var(--perigo)}
.rodape{max-width:1180px;margin:0 auto;padding:.5rem var(--esp) 2rem;color:var(--muted);font-size:.8125rem}
.modal-fundo{position:fixed;inset:0;background:rgba(15,23,32,.55);display:flex;align-items:center;justify-content:center;z-index:40;padding:1rem}
.modal{background:#fff;border-radius:var(--raio);padding:1.5rem;max-width:28rem;width:100%;max-height:90vh;overflow:auto}
.modal h2{font-size:1.25rem}
@media (max-width:760px){
  .layout{grid-template-columns:minmax(0,1fr);padding:1rem;gap:1rem}
  .lateral ul{position:static;display:flex;flex-wrap:wrap;gap:.25rem}
  .grade{grid-template-columns:minmax(0,1fr)}
  .cartao{padding:1rem}
}
