<script>
(function () {
  var live = document.getElementById('live');
  var ultimoFoco = null;
  var appAtual = '';
  var inputExcluir = document.getElementById('confirma-excluir');
  var erroExcluir = document.getElementById('erro-confirma-excluir');

  function abrir(id, titulo) {
    var fundo = document.getElementById(id);
    ultimoFoco = document.activeElement;
    if (titulo) { fundo.querySelector('h2').textContent = titulo; }
    if (id === 'fundo-excluir') {
      inputExcluir.value = '';
      erroExcluir.hidden = true;
      inputExcluir.removeAttribute('aria-invalid');
    }
    fundo.hidden = false;
    var primeiro = fundo.querySelector('input') || fundo.querySelector('.btn');
    if (primeiro) { primeiro.focus(); }
  }

  function fechar(fundo) {
    fundo.hidden = true;
    if (ultimoFoco) { ultimoFoco.focus(); }
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      appAtual = b.getAttribute('data-app') || '';
      abrir(b.getAttribute('data-abrir'), appAtual ? 'Revogar o acesso de ' + appAtual + '?' : null);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.getElementById('btn-confirma-revogar').addEventListener('click', function () {
    fechar(document.getElementById('fundo-revogar'));
    live.textContent = 'Acesso de ' + appAtual + ' revogado.';
  });

  document.getElementById('btn-confirma-excluir').addEventListener('click', function () {
    if (inputExcluir.value.trim() !== 'EXCLUIR') {
      erroExcluir.textContent = 'Digite EXCLUIR exatamente como mostrado para confirmar.';
      erroExcluir.hidden = false;
      inputExcluir.setAttribute('aria-invalid', 'true');
      inputExcluir.focus();
      return;
    }
    fechar(document.getElementById('fundo-excluir'));
    live.textContent = 'Pedido de exclusão de conta confirmado.';
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) { return; }
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key !== 'Tab') { return; }
    var focaveis = aberto.querySelectorAll('input, button');
    var primeiro = focaveis[0];
    var ultimo = focaveis[focaveis.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
</script>
