    lista.innerHTML = '';
    if (!invalidos.length) { resumo.hidden = true; return; }
    e.preventDefault();
    invalidos.forEach(function (campo) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + campo.id;
