    if (botoes.length) botoes[botoes.length - 1].focus();
  }

  function fechar(modal) {
    modal.hidden = true;
    if (ultimoFoco && document.body.contains(ultimoFoco)) ultimoFoco.focus();
    ultimoFoco = null;
  }

  function modalAberto() {
    return document.querySelector('[data-modal]:not([hidden])');
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var modal = document.getElementById(b.getAttribute('data-abrir'));
    var linha = b.closest('tr');
    var app = linha ? linha.querySelector('th').textContent.trim() : '';
    if (modal.id === 'fundo-revogar' && app) {
