    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    var m = modalAberto();
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var foco = m.querySelectorAll('button:not([disabled])');
    var primeiro = foco[0];
    var ultimo = foco[foco.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) {
      e.preventDefault();
      ultimo.focus();
