(function () {
  var modais = document.querySelectorAll('.modal');
  var fundo = ['.topo', '.layout', '.rodape'].map(function (s) { return document.querySelector(s); });
  var gaveta = document.getElementById('gaveta');
  var botaoAjuda = document.querySelector('[aria-controls="gaveta"]');
  var focoAnterior = null;

  function atualizarFundo() {
    var aberto = document.querySelector('.modal:not([hidden])');
    fundo.forEach(function (el) { if (el) el.inert = !!aberto; });
  }

  function abrirModal(m, origem) {
    focoAnterior = origem;
    m.hidden = false;
    atualizarFundo();
    var primeiro = m.querySelector('input') || m.querySelector('.modal-acoes .btn');
    if (primeiro) primeiro.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    atualizarFundo();
    if (focoAnterior) focoAnterior.focus();
    focoAnterior = null;
  }

  function fecharGaveta() {
    gaveta.hidden = true;
    botaoAjuda.setAttribute('aria-expanded', 'false');
    botaoAjuda.focus();
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('aria-controls')), b);
    });
  });

  modais.forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m) return fecharModal(m);
      var b = e.target.closest('button');
      if (b && m.contains(b) && (b.classList.contains('modal-x') || b.textContent.trim() === 'Cancelar')) {
        fecharModal(m);
      }
    });
  });

  botaoAjuda.addEventListener('click', function () {
    var abrir = gaveta.hidden;
    gaveta.hidden = !abrir;
    botaoAjuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) gaveta.querySelector('a').focus();
  });
  gaveta.querySelector('.modal-x').addEventListener('click', fecharGaveta);

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (aberto) fecharModal(aberto);
      else if (!gaveta.hidden) fecharGaveta();
      return;
    }
    if (e.key === 'Tab' && aberto) {
      var focaveis = aberto.querySelectorAll('button:not([disabled]), input');
      if (!focaveis.length) return;
      var primeiro = focaveis[0];
      var ultimo = focaveis[focaveis.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        primeiro.focus();
      }
    }
  });

  var banner = document.querySelector('.banner');
  banner.querySelector('.btn-txt').addEventListener('click', function () {
    document.getElementById('conteudo').focus();
    banner.remove();
  });

  var email = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  document.querySelector('#m0 .btn-prim').addEventListener('click', function () {
    if (!email.checkValidity()) {
      erro.hidden = false;
      email.setAttribute('aria-invalid', 'true');
      email.focus();
      return;
    }
    erro.hidden = true;
    email.removeAttribute('aria-invalid');
    fecharModal(document.getElementById('m0'));
  });
})();
</script>
