<script>
(function () {
  var live = document.getElementById('live');
  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  // Rótulos específicos para ações repetidas
  document.querySelectorAll('#acessos tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
    tr.querySelectorAll('button').forEach(function (b) {
      if (b.hasAttribute('data-abrir')) {
        b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
        b.setAttribute('data-app', nome);
      } else if (b.textContent.trim() === 'Encerrar sessão') {
        b.setAttribute('aria-label', 'Encerrar sessão de ' + nome);
      }
    });
  });

  // Indicadores de situação com nome acessível
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) { p.setAttribute('role', 'img'); });

  // Modais com foco gerenciado, Esc e armadilha de foco
  var ultimoFoco = null;
  function abrirModal(fundo, app) {
    ultimoFoco = document.activeElement;
    if (app) document.getElementById('app-revogar').textContent = app;
    fundo.hidden = false;
    var botoes = fundo.querySelectorAll('button');
    botoes[botoes.length - 1].focus();
  }
  function fecharModal(fundo) {
    fundo.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abrir')), b.getAttribute('data-app'));
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });
  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fecharModal(aberto); return; }
    if (e.key !== 'Tab') return;
    var f = aberto.querySelectorAll('button');
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  // Banner de preferências
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });

  // Validação do perfil
  var formPerfil = document.getElementById('form-perfil');
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var erroEmail = document.getElementById('erro-email');
  var erroTel = document.getElementById('erro-telefone');
  function marcar(campo, erro, ok) {
    campo.setAttribute('aria-invalid', ok ? 'false' : 'true');
    campo.closest('.campo').classList.toggle('campo-erro', !ok);
    erro.hidden = ok;
  }
  function validarPerfil() {
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
    var digitos = tel.value.replace(/\D/g, '');
    var telOk = digitos.length === 10 || digitos.length === 11;
    marcar(email, erroEmail, emailOk);
    marcar(tel, erroTel, telOk);
    return emailOk && telOk;
  }
  email.addEventListener('blur', validarPerfil);
  tel.addEventListener('blur', validarPerfil);
  formPerfil.addEventListener('reset', function () { setTimeout(validarPerfil, 0); });
