<script>
(function () {
  var live = document.getElementById('live');
  var ultimoFoco = null;
  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var titulo = document.getElementById('resumo-titulo');
  var avisoErros = document.getElementById('aviso-erros');
  var lista = document.getElementById('lista-erros');
  var campoConfirma = document.getElementById('confirmar-texto');
  var btnConfirma = document.getElementById('confirmar-exclusao');
  var tabelaApps = document.querySelector('#acessos table tbody');
  var contagem = document.getElementById('contagem-acessos');
  var desfazer = document.getElementById('desfazer');
  var txtDesfazer = document.getElementById('desfazer-txt');
  var btnDesfazer = document.getElementById('btn-desfazer');
  var pendente = null;

  function anunciar(t) {
    live.textContent = '';
    setTimeout(function () { live.textContent = t; }, 50);
  }

  function abrir(id) {
    var f = document.getElementById(id);
    ultimoFoco = document.activeElement;
    campoConfirma.value = '';
    btnConfirma.disabled = true;
    f.hidden = false;
    (f.querySelector('input') || f.querySelector('button')).focus();
  }

  function fechar(modal) {
    modal.hidden = true;
    if (ultimoFoco) { ultimoFoco.focus(); ultimoFoco = null; }
  }

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var m = document.querySelector('[data-modal]:not([hidden])');
    if (m) fechar(m);
  });

  campoConfirma.addEventListener('input', function () {
    btnConfirma.disabled = campoConfirma.value.trim() !== 'EXCLUIR';
  });

  function atualizarContagem() {
    var n = tabelaApps.querySelectorAll('tr:not([hidden])').length;
    contagem.textContent = n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
  }

  function revogar(b) {
    var linha = b.closest('tr');
    var nome = linha.querySelector('th').textContent;
    linha.hidden = true;
    pendente = linha;
    atualizarContagem();
    txtDesfazer.textContent = 'Acesso de ' + nome + ' revogado.';
    desfazer.hidden = false;
    anunciar('Acesso de ' + nome + ' revogado.');
    btnDesfazer.focus();
  }

  btnDesfazer.addEventListener('click', function () {
    if (pendente) {
      pendente.hidden = false;
      pendente.querySelector('[data-abrir]').focus();
      pendente = null;
      atualizarContagem();
      anunciar('Revogação desfeita.');
    }
    desfazer.hidden = true;
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var alvo = b.getAttribute('data-abrir');
    if (alvo !== 'fundo-excluir') {
      b.setAttribute('aria-label', 'Revogar acesso de ' + b.closest('tr').querySelector('th').textContent);
    }
    b.addEventListener('click', function () {
      if (alvo === 'fundo-excluir') abrir(alvo); else revogar(b);
    });
  });

  var regras = [
    {
      el: document.getElementById('email'),
      erro: document.getElementById('erro-email'),
      ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
      msg: 'E-mail corporativo: informe um endereço válido, por exemplo nome@bancohorizonte.com.br.'
    },
    {
      el: document.getElementById('telefone'),
      erro: document.getElementById('erro-telefone'),
      ok: function (v) { return /^\(\d{2}\) \d{4,5}-\d{4}$/.test(v.trim()); },
      msg: 'Telefone celular: informe com DDD, no formato (11) 91234-5678.'
    }
  ];

  function invalido(r) {
    var bad = !r.ok(r.el.value);
    r.el.setAttribute('aria-invalid', bad ? 'true' : 'false');
    r.erro.hidden = !bad;
    return bad;
  }

  regras.forEach(function (r) {
    r.el.addEventListener('input', function () {
      if (!r.erro.hidden) invalido(r);
    });
  });

  form.addEventListener('submit', function (e) {
    var falhas = regras.filter(function (r) { return invalido(r); });
    if (falhas.length === 0) { resumo.hidden = true; return; }
    e.preventDefault();
    lista.innerHTML = '';
    falhas.forEach(function (r) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + r.el.id;
      a.textContent = r.msg;
      li.appendChild(a);
      lista.appendChild(li);
    });
    avisoErros.textContent = falhas.length === 1
      ? 'Não foi possível salvar: 1 campo precisa de correção.'
      : 'Não foi possível salvar: ' + falhas.length + ' campos precisam de correção.';
    resumo.hidden = false;
    titulo.focus();
  });

  form.addEventListener('reset', function () {
    resumo.hidden = true;
    regras.forEach(function (r) {
      r.erro.hidden = true;
      r.el.removeAttribute('aria-invalid');
    });
  });
})();
</script>
</body>
@@ FIM

@@ DECISOES
- Botão Salvar deixa de iniciar desabilitado; a validação roda só ao enviar e o erro some ao ser corrigido | regra: FC19
- Erros de e-mail e telefone deixam de aparecer antes da digitação; o telefone incompleto atual é mantido para o usuário corrigir no envio | regra: FC19
- Resumo de erros com título focável, parágrafo interno com role=alert e links para cada campo com erro | regra: FC17
- E-mail usa type=email e autocomplete=email; telefone usa type=tel e autocomplete=tel; nome, empresa e cidade recebem tokens válidos | regra: NENHUMA
- Banner de sucesso fica oculto por padrão, deixando um único banner de aviso visível na página | regra: NE33
- Revogação de acesso passa a ser imediata com botão Desfazer, pois a própria mensagem diz que é reversível | regra: NE41
- Exclusão de conta exige digitar EXCLUIR antes de habilitar a confirmação, com Cancelar como saída segura | regra: FC49
- Modais recebem foco inicial, devolvem o foco ao fechar e fecham com Esc | regra: NENHUMA
- Botões repetidos ganham nome do aplicativo ou da sessão, e os ícones ganham nome acessível | regra: NENHUMA
- Link de salto aponta para #principal com tabindex=-1, para receber foco de fato | regra: AM03
- Região de status #live deixa de ser display:none e passa a ser oculta visualmente, para que leitores de tela anunciem | regra: NENHUMA
- Tamanhos de fonte passam a ser relativos (rem/%), permitindo redimensionar o texto | regra: AM40
- Texto corrido limitado a 75ch e tabelas em contêiner com rolagem horizontal | regra: AM46
- Layout passa a uma coluna em telas pequenas, com alvos de toque de 44px em ponteiro grosso | regra: NENHUMA
- Esqueleto de carregamento fica oculto, pois contradizia a mensagem de falha exibida ao mesmo tempo | regra: NENHUMA
- Sessão atual vira rótulo sem ação e o Início vira link real | regra: NENHUMA
- Título da página passa a ser h1 | regra: NENHUMA
- Gravação real no servidor e revogação definitiva ficam pendentes do backend; a validação do cliente não substitui a do servidor | regra: NENHUMA
@@ FIM

