(function () {
  var live = document.getElementById('live');
  var gatilho = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function modalAberto() {
    return document.querySelector('[data-modal]:not([hidden])');
  }

  function abrir(modal, trigger) {
    gatilho = trigger;
    var alvo = modal.querySelector('[data-app-nome]');
    if (alvo && trigger.closest('tr')) {
      alvo.textContent = trigger.closest('tr').querySelector('th').textContent;
    }
    modal.hidden = false;
    var botoes = modal.querySelectorAll('button');
    botoes[botoes.length - 1].focus();
  }

  function fechar(modal, confirmado) {
    modal.hidden = true;
    if (confirmado === 'revogar' && gatilho) {
      var linha = gatilho.closest('tr');
      var app = linha.querySelector('th').textContent;
      var tbody = linha.parentNode;
      linha.parentNode.removeChild(linha);
      var n = tbody.rows.length;
      document.getElementById('contagem-acessos').textContent =
        n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
      anunciar('Acesso de ' + app + ' revogado.');
      var h = document.getElementById('h-acessos');
      h.tabIndex = -1;
      h.focus();
    } else if (gatilho && gatilho.isConnected) {
      gatilho.focus();
    }
    gatilho = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      fechar(b.closest('[data-modal]'), b.getAttribute('data-confirmar'));
    });
  });

  document.addEventListener('keydown', function (e) {
    var m = modalAberto();
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key === 'Tab') {
      var f = m.querySelectorAll('button:not([disabled])');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    if (this.querySelector('.campo-erro')) {
      e.preventDefault();
      var r = document.getElementById('resumo-erros');
      r.focus();
      anunciar('Corrija os campos destacados para salvar o perfil.');
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.tabIndex = -1;
    h.focus();
  });
})();
