function ordenar(btn){
  var th = btn.parentElement;
  var novo = th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
  th.parentElement.querySelectorAll('th[aria-sort]').forEach(function (o) {
    if (o !== th) { o.setAttribute('aria-sort', 'none'); o.querySelector('.seta').textContent = '⇅'; }
  });
  th.setAttribute('aria-sort', novo);
  btn.querySelector('.seta').textContent = novo === 'ascending' ? '▲' : '▼';
}
document.querySelectorAll('.ord').forEach(function (b) {
  b.addEventListener('click', function () { ordenar(b); });
