<script>
(function(){
  var botao=document.querySelector('[aria-controls="gaveta"]');
  var gaveta=document.getElementById('gaveta');
  var fechar=document.getElementById('gaveta-fechar');
  function alternar(aberto){
    gaveta.classList.toggle('aberta',aberto);
    botao.setAttribute('aria-expanded',String(aberto));
    (aberto?fechar:botao).focus();
  }
  botao.addEventListener('click',function(){alternar(!gaveta.classList.contains('aberta'));});
  fechar.addEventListener('click',function(){alternar(false);});
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'&&gaveta.classList.contains('aberta')){alternar(false);}
  });
  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){b.closest('.banner').remove();});
  });
})();
</script>
</body>
