    modal.hidden = false;
    var primeiroSeguro = modal.querySelector('.acoes .btn:not(.perigo)') || modal.querySelector('.modal .btn');
    if (primeiroSeguro) primeiroSeguro.focus();
  }
  function fechar(modal) {
    modal.hidden = true;
    if (ultimoGatilho) ultimoGatilho.focus();
