<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var btnNovaVaga = document.querySelector('[aria-controls="m0"]');
  var btnDispensar = document.querySelector('.banner .btn-txt');
  var email = document.getElementById('conv-email');
  var erroEmail = document.getElementById('conv-erro');
  var modalAtivo = null;
  var focoAnterior = null;

  function abrirGaveta(abrir) {
    gaveta.classList.toggle('aberta', abrir);
    btnAjuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) gaveta.querySelector('a').focus();
  }

  function abrirModal(modal, origem) {
    focoAnterior = origem || document.activeElement;
    modal.hidden = false;
    modalAtivo = modal;
    var alvo = modal.querySelector('input, .modal-cancelar, button');
    if (alvo) alvo.focus();
  }

  function fecharModal() {
    if (!modalAtivo) return;
    modalAtivo.hidden = true;
    modalAtivo = null;
    if (focoAnterior) focoAnterior.focus();
  }

  function validarEmail() {
    var invalido = !email.checkValidity();
    email.setAttribute('aria-invalid', String(invalido));
    erroEmail.hidden = !invalido;
  }

  btnAjuda.addEventListener('click', function () {
    abrirGaveta(!gaveta.classList.contains('aberta'));
  });

  btnNovaVaga.addEventListener('click', function () {
    abrirModal(document.getElementById('m0'), this);
  });

  btnDispensar.addEventListener('click', function () {
    this.closest('.banner').remove();
    document.getElementById('conteudo').focus();
  });

  email.addEventListener('blur', validarEmail);
  email.addEventListener('input', function () {
    if (email.getAttribute('aria-invalid') === 'true') validarEmail();
  });

  document.addEventListener('click', function (e) {
    if (e.target.closest('.modal-x, .modal-cancelar')) fecharModal();
    else if (e.target.classList && e.target.classList.contains('modal')) fecharModal();
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      if (modalAtivo) {
        fecharModal();
      } else if (gaveta.classList.contains('aberta')) {
        abrirGaveta(false);
        btnAjuda.focus();
      }
      return;
    }
    if (e.key !== 'Tab' || !modalAtivo) return;
    var foc = modalAtivo.querySelectorAll('input, button');
    var primeiro = foc[0];
    var ultimo = foc[foc.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) {
      e.preventDefault();
      ultimo.focus();
    } else if (!e.shiftKey && document.activeElement === ultimo) {
      e.preventDefault();
      primeiro.focus();
    }
  });
})();
</script>
