@@ DEPOIS
(function () {
  var live = document.getElementById('live');
  var gatilho = null;

  function anunciar(msg) {
    live.textContent = '';
    live.textContent = msg;
  }

  function abrirModal(fundo) {
    gatilho = document.activeElement;
    fundo.hidden = false;
    var primeiro = fundo.querySelector('input:not([disabled]), button:not([disabled])');
    if (primeiro) primeiro.focus();
  }

  function fecharModal(fundo) {
    fundo.hidden = true;
    if (gatilho) gatilho.focus();
  }

  document.querySelectorAll('tbody tr').forEach(function (linha) {
    var nome = linha.querySelector('th').textContent;
    linha.querySelectorAll('button').forEach(function (b) {
      var texto = b.textContent.trim();
      if (texto === 'Revogar acesso' || texto === 'Encerrar sessão') {
        var s = document.createElement('span');
        s.className = 'sr-only';
        s.textContent = ' de ' + nome;
        b.appendChild(s);
      }
    });
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var linha = b.closest('tr');
      if (linha && b.getAttribute('data-abrir') === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + linha.querySelector('th').textContent + '?';
      }
      abrirModal(document.getElementById(b.getAttribute('data-abrir')));
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });

  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.addEventListener('click', function (e) { if (e.target === fundo) fecharModal(fundo); });
    fundo.addEventListener('keydown', function (e) { if (e.key === 'Escape') fecharModal(fundo); });
  });

  var confirma = document.getElementById('confirma-exclusao');
  var btnExcluir = document.getElementById('btn-confirmar-exclusao');
  confirma.addEventListener('input', function () {
    btnExcluir.disabled = confirma.value.trim() !== 'EXCLUIR';
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var t = document.createElement('span');
    t.textContent = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(t);
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var formPerfil = document.getElementById('form-perfil');
  var btnSalvar = formPerfil.querySelector('button[type="submit"]');
  formPerfil.addEventListener('input', function () { btnSalvar.disabled = false; });
  formPerfil.addEventListener('reset', function () {
    setTimeout(function () { btnSalvar.disabled = true; }, 0);
  });
  formPerfil.addEventListener('submit', function (e) {
    e.preventDefault();
    btnSalvar.disabled = true;
    anunciar('Perfil salvo.');
  });

  var bio = document.getElementById('bio');
  var dicaBio = document.getElementById('dica-bio');
  bio.addEventListener('input', function () {
    dicaBio.textContent = (200 - bio.value.length) + ' caracteres restantes.';
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var agora = new Date();
    var hora = String(agora.getHours()).padStart(2, '0') + ':' + String(agora.getMinutes()).padStart(2, '0');
    document.getElementById('texto-sucesso').textContent = 'Suas preferências de notificação foram salvas às ' + hora + '.';
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências salvas às ' + hora + '.');
  });
})();
@@ FIM

