<script>
(function () {
  var live = document.getElementById('live');
  var anunciar = function (t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); };
  var gatilho = null;

  var abrir = function (id, origem) {
    var m = document.getElementById(id);
    gatilho = origem || null;
    var nome = origem && origem.getAttribute('data-app');
    if (nome) {
      var s = m.querySelector('[data-app-nome]');
      if (s) s.textContent = nome;
    }
    m.hidden = false;
    var alvo = m.querySelector('[data-fechar]');
    if (alvo) alvo.focus();
  };

  var fechar = function (m) {
    m.hidden = true;
    if (gatilho) { gatilho.focus(); gatilho = null; }
  };

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(m); return; }
      if (e.key !== 'Tab') return;
      var f = m.querySelectorAll('button:not([disabled])');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
    m.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fechar(m); });
    });
    m.querySelectorAll('[data-confirmar]').forEach(function (b) {
      b.addEventListener('click', function () {
        var acao = b.getAttribute('data-confirmar');
        fechar(m);
        anunciar(acao === 'excluir-conta' ? 'Solicitação de exclusão da conta registrada.' : 'Acesso do aplicativo revogado.');
      });
    });
  });

  var banner = document.getElementById('banner-sucesso');
  document.getElementById('btn-dispensar').addEventListener('click', function () { banner.hidden = true; });
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    banner.hidden = false;
    anunciar('Preferências de notificação salvas.');
  });
})();
</script>
