function ordenar(botao){
  var th = botao.closest('th');
  var proximo = th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
  document.querySelectorAll('.tabela thead th[aria-sort]').forEach(function (t) {
    t.setAttribute('aria-sort', 'none');
    t.querySelector('.seta').textContent = '⇅';
  });
  th.setAttribute('aria-sort', proximo);
  botao.querySelector('.seta').textContent = proximo === 'ascending' ? '▲' : '▼';
}
