<script>
(function () {
  var gatilho = null;
  function hora() { return new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); }
  function abrir(f, titulo) {
    gatilho = document.activeElement;
    var h = f.querySelector('h2');
    if (titulo) h.textContent = titulo;
    f.hidden = false;
    h.setAttribute('tabindex', '-1');
    h.focus();
  }
  function fechar(f) {
    f.hidden = true;
    if (gatilho) { gatilho.focus(); gatilho = null; }
  }

  document.querySelectorAll('table tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
    tr.querySelectorAll('button').forEach(function (b) {
      var s = document.createElement('span');
      s.className = 'sr-only';
      s.textContent = ' em ' + nome;
      b.appendChild(s);
    });
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var t = document.createElement('span');
    t.textContent = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(t);
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var f = document.getElementById(b.getAttribute('data-abrir'));
      var titulo = null;
      if (f.id === 'fundo-revogar') {
        titulo = 'Revogar o acesso de ' + b.closest('tr').querySelector('th').textContent.trim() + '?';
      }
      abrir(f, titulo);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    var m = document.querySelector('[data-modal]:not([hidden])');
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var f = m.querySelectorAll('button:not([disabled]), input');
    if (!f.length) return;
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-confirmar-exclusao').addEventListener('click', function () {
    var campo = document.getElementById('confirmar-exclusao');
    var erro = document.getElementById('erro-confirmar');
    if (campo.value.trim() !== 'EXCLUIR') {
      erro.hidden = false;
      campo.setAttribute('aria-invalid', 'true');
      campo.focus();
      return;
    }
    erro.hidden = true;
    campo.removeAttribute('aria-invalid');
    fechar(document.getElementById('fundo-excluir'));
  });

  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var status = document.getElementById('status-perfil');
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var email = document.getElementById('email');
    var tel = document.getElementById('telefone');
    var checks = [
      [email, /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())],
      [tel, [10, 11].indexOf(tel.value.replace(/\D/g, '').length) !== -1]
    ];
    lista.textContent = '';
    var primeiro = null;
    checks.forEach(function (c) {
      var campo = c[0];
      var bloco = campo.closest('.campo');
      var erro = document.getElementById('erro-' + campo.id);
      bloco.classList.toggle('ativo', !c[1]);
      erro.hidden = c[1];
      if (c[1]) { campo.removeAttribute('aria-invalid'); return; }
      campo.setAttribute('aria-invalid', 'true');
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + campo.id;
      a.textContent = campo.labels[0].textContent + ': ' + erro.textContent;
      li.appendChild(a);
      lista.appendChild(li);
      if (!primeiro) primeiro = campo;
    });
    if (primeiro) {
      resumo.hidden = false;
      status.textContent = '';
      resumo.focus();
    } else {
      resumo.hidden = true;
      status.textContent = 'Perfil salvo às ' + hora() + '.';
    }
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('texto-banner').textContent = 'Suas preferências de notificação foram salvas às ' + hora() + '.';
    document.getElementById('banner-sucesso').hidden = false;
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
</script>
@@ FIM

