<script>
(function () {
  'use strict';

  // Telefone: (00) 00000-0000
  function mascaraTel(v) {
    var d = v.replace(/\D/g, '').slice(0, 11);
    if (d.length === 0) return '';
    if (d.length <= 2) return '(' + d;
    if (d.length <= 6) return '(' + d.slice(0, 2) + ') ' + d.slice(2);
    if (d.length <= 10) return '(' + d.slice(0, 2) + ') ' + d.slice(2, 6) + '-' + d.slice(6);
    return '(' + d.slice(0, 2) + ') ' + d.slice(2, 7) + '-' + d.slice(7);
  }
  var tel = document.getElementById('tel');
  if (tel) {
    tel.value = mascaraTel(tel.value);
    tel.addEventListener('input', function () {
      tel.value = mascaraTel(tel.value);
    });
  }

  // Campos somente numéricos
  function somenteDigitos(el, max) {
    if (!el) return;
    el.addEventListener('input', function () {
      el.value = el.value.replace(/\D/g, '').slice(0, max);
    });
  }
  somenteDigitos(document.getElementById('cpf'), 11);
  somenteDigitos(document.getElementById('cep-res'), 8);
  somenteDigitos(document.getElementById('cep-cor'), 8);

  // Abas com navegação por setas (padrão WAI-ARIA)
  var abas = Array.prototype.slice.call(document.querySelectorAll('[role=tab]'));
  function ativarAba(aba, focar) {
    abas.forEach(function (a) {
      var sel = a === aba;
      a.setAttribute('aria-selected', sel ? 'true' : 'false');
      a.tabIndex = sel ? 0 : -1;
      a.classList.toggle('aba-ativa', sel);
      document.getElementById(a.getAttribute('aria-controls')).hidden = !sel;
    });
    if (focar) aba.focus();
  }
  abas.forEach(function (aba, i) {
    aba.addEventListener('click', function () {
      ativarAba(aba, false);
    });
    aba.addEventListener('keydown', function (e) {
      var prox = null;
      if (e.key === 'ArrowRight') prox = abas[(i + 1) % abas.length];
      if (e.key === 'ArrowLeft') prox = abas[(i - 1 + abas.length) % abas.length];
      if (prox) {
        e.preventDefault();
        ativarAba(prox, true);
      }
    });
  });

  // Mesmo endereço para correspondência
  var mesmo = document.getElementById('mesmo');
  var pares = [
    ['cep-res', 'cep-cor'],
    ['rua-res', 'rua-cor'],
    ['num-res', 'num-cor'],
    ['comp-res', 'comp-cor'],
    ['bairro-res', 'bairro-cor'],
    ['cidade-res', 'cidade-cor'],
    ['uf-res', 'uf-cor']
  ];
  function sincronizarEndereco() {
    if (!mesmo) return;
    pares.forEach(function (p) {
      var origem = document.getElementById(p[0]);
      var destino = document.getElementById(p[1]);
      if (mesmo.checked) destino.value = origem.value;
      if (destino.tagName === 'SELECT') {
        destino.disabled = mesmo.checked;
      } else {
        destino.readOnly = mesmo.checked;
      }
    });
  }
  if (mesmo) {
    mesmo.addEventListener('change', sincronizarEndereco);
    pares.forEach(function (p) {
      var origem = document.getElementById(p[0]);
      origem.addEventListener('input', sincronizarEndereco);
      origem.addEventListener('change', sincronizarEndereco);
    });
  }
})();
</script>
