<script>
(function () {
  var live = document.getElementById('live');
  var gatilho = null;
  var modalAtual = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrir(id, origem) {
    var m = document.getElementById(id);
    gatilho = origem;
    modalAtual = m;
    if (origem && origem.hasAttribute('data-app')) {
      var app = origem.getAttribute('data-app');
      m.querySelector('h2').textContent = 'Revogar o acesso de ' + app + '?';
      m.querySelector('p').textContent = 'O aplicativo ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    m.hidden = false;
    var botoes = m.querySelectorAll('button');
    botoes[botoes.length - 1].focus();
  }

  function fechar(m, msg) {
    m.hidden = true;
    modalAtual = null;
    if (gatilho) gatilho.focus();
    gatilho = null;
    if (msg) anunciar(msg);
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var msg = b.getAttribute('data-confirmar');
      if (msg && gatilho && gatilho.hasAttribute('data-app')) {
        msg += ' de ' + gatilho.getAttribute('data-app');
      }
      fechar(b.closest('[data-modal]'), msg);
    });
  });

  document.addEventListener('keydown', function (e) {
    if (!modalAtual) return;
    if (e.key === 'Escape') { fechar(modalAtual); return; }
    if (e.key === 'Tab') {
      var f = modalAtual.querySelectorAll('button');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!this.checkValidity()) { this.reportValidity(); return; }
    anunciar('Perfil salvo.');
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });
})();
</script>
