(function () {
  var live = document.getElementById('live');
  var ultimoFoco = null;
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }
  function abrir(modal) {
    ultimoFoco = document.activeElement;
    modal.hidden = false;
    var primeiro = modal.querySelector('button');
    if (primeiro) primeiro.focus();
  }
  function fechar(modal) {
    modal.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  document.querySelectorAll('#acessos td > button').forEach(function (b) {
    var app = b.closest('tr').querySelector('th');
    var extra = document.createElement('span');
    extra.className = 'sr-only';
    extra.textContent = ' ' + app.textContent;
    b.appendChild(extra);
  });
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var t = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', t);
  });
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var modal = document.getElementById(b.getAttribute('data-abrir'));
      if (modal.id === 'fundo-revogar') {
        var app = b.closest('tr').querySelector('th').textContent;
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
        document.getElementById('dlg-revogar-d').textContent = 'O ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(modal);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key !== 'Tab') return;
    var botoes = aberto.querySelectorAll('button');
    var primeiro = botoes[0], ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });
  var titulo = document.getElementById('h-pref');
  titulo.setAttribute('tabindex', '-1');
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    titulo.focus();
  });
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var d = new Date();
    document.getElementById('hora-salva').textContent = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });
})();
