<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var botaoAjuda=document.querySelector('[aria-controls="gaveta"]');
  var modalAtivo=null;
  var ultimoFoco=null;

  function alternarGaveta(){
    var abrir=gaveta.hidden;
    gaveta.hidden=!abrir;
    botaoAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gaveta.querySelector('a').focus();}else{botaoAjuda.focus();}
  }
  botaoAjuda.addEventListener('click',alternarGaveta);
  gaveta.querySelector('[data-fechar="gaveta"]').addEventListener('click',alternarGaveta);

  function abrirModal(id){
    ultimoFoco=document.activeElement;
    modalAtivo=document.getElementById(id);
    modalAtivo.hidden=false;
    modalAtivo.querySelector('input,button').focus();
  }
  function fecharModal(){
    if(!modalAtivo)return;
    modalAtivo.hidden=true;
    modalAtivo=null;
    if(ultimoFoco)ultimoFoco.focus();
  }
  document.querySelectorAll('[data-modal]').forEach(function(b){
    b.addEventListener('click',function(){abrirModal(b.getAttribute('data-modal'));});
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.closest('.modal-x,.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)'))fecharModal();
    });
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      if(modalAtivo)fecharModal();
      else if(!gaveta.hidden)alternarGaveta();
    }
    if(e.key==='Tab'&&modalAtivo){
      var f=modalAtivo.querySelectorAll('button,input,a[href]');
      var primeiro=f[0],ultimo=f[f.length-1];
      if(e.shiftKey&&document.activeElement===primeiro){e.preventDefault();ultimo.focus();}
      else if(!e.shiftKey&&document.activeElement===ultimo){e.preventDefault();primeiro.focus();}
    }
  });
  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){b.closest('.banner').remove();});
  });
})();
</script>
</body>
