<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var botaoAjuda=document.querySelector('[aria-controls="gaveta"]');
  var modalAberto=null,focoAnterior=null;

  function alternarGaveta(abrir){
    gaveta.classList.toggle('aberta',abrir);
    botaoAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gaveta.querySelector('a').focus();}else{botaoAjuda.focus();}
  }
  botaoAjuda.addEventListener('click',function(){
    alternarGaveta(!gaveta.classList.contains('aberta'));
  });
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click',function(){
    alternarGaveta(false);
  });

  function abrirModal(m){
    focoAnterior=document.activeElement;
    modalAberto=m;
    m.hidden=false;
    (m.querySelector('input,button')||m).focus();
  }
  function fecharModal(){
    if(!modalAberto)return;
    modalAberto.hidden=true;
    modalAberto=null;
    if(focoAnterior)focoAnterior.focus();
  }
  document.querySelectorAll('[data-modal]').forEach(function(b){
    b.addEventListener('click',function(){
      abrirModal(document.getElementById(b.getAttribute('data-modal')));
    });
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.hasAttribute('data-fechar'))fecharModal();
    });
  });

  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      if(modalAberto)fecharModal();
      else if(gaveta.classList.contains('aberta'))alternarGaveta(false);
      return;
    }
    if(e.key==='Tab'&&modalAberto){
      var f=modalAberto.querySelectorAll('button,input,a[href]');
      if(!f.length)return;
      var primeiro=f[0],ultimo=f[f.length-1];
      if(e.shiftKey&&document.activeElement===primeiro){e.preventDefault();ultimo.focus();}
      else if(!e.shiftKey&&document.activeElement===ultimo){e.preventDefault();primeiro.focus();}
    }
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){
      document.getElementById('conteudo').focus();
      b.closest('.banner').remove();
    });
  });
})();
</script>
</body>
