<script>
(function () {
  var $ = function (id) { return document.getElementById(id); };
  var soDigitos = function (v) { return v.replace(/\D/g, ''); };
  var form = document.querySelector('form');

  /* Máscaras */
  var tel = $('tel');
  var mascaraTel = function (v) {
    var d = soDigitos(v).slice(0, 11);
    if (d.length <= 2) return d;
    if (d.length <= 6) return '(' + d.slice(0, 2) + ') ' + d.slice(2);
    if (d.length <= 10) return '(' + d.slice(0, 2) + ') ' + d.slice(2, 6) + '-' + d.slice(6);
    return '(' + d.slice(0, 2) + ') ' + d.slice(2, 7) + '-' + d.slice(7);
  };
  var mascaraCep = function (v) {
    var d = soDigitos(v).slice(0, 8);
    return d.length > 5 ? d.slice(0, 5) + '-' + d.slice(5) : d;
  };
  tel.value = mascaraTel(tel.value);
  tel.addEventListener('input', function () { tel.value = mascaraTel(tel.value); });
  ['cep-res', 'cep-cor'].forEach(function (id) {
    var el = $(id);
    el.addEventListener('input', function () { el.value = mascaraCep(el.value); });
  });

  /* Abas do documento */
  var abas = Array.prototype.slice.call(document.querySelectorAll('[role=tab]'));
  var mostraAba = function (aba, focar) {
    abas.forEach(function (a) {
      var ativa = a === aba;
      a.setAttribute('aria-selected', String(ativa));
      a.tabIndex = ativa ? 0 : -1;
      a.classList.toggle('aba-ativa', ativa);
      $(a.getAttribute('aria-controls')).hidden = !ativa;
    });
    if (focar) aba.focus();
  };
  abas.forEach(function (a, i) {
    $(a.getAttribute('aria-controls')).setAttribute('aria-labelledby', a.id);
    a.addEventListener('click', function () { mostraAba(a, false); });
    a.addEventListener('keydown', function (e) {
      var prox = null;
      if (e.key === 'ArrowRight') prox = abas[(i + 1) % abas.length];
      if (e.key === 'ArrowLeft') prox = abas[(i - 1 + abas.length) % abas.length];
      if (prox) { e.preventDefault(); mostraAba(prox, true); }
    });
  });
  mostraAba(abas[0], false);

  /* Mesmo endereço para correspondência */
  var mesmo = document.querySelector('input[name="mesmo"]');
  var blocoCor = $('cep-cor').closest('.bloco-end');
  var nomes = ['cep', 'rua', 'num', 'comp', 'bairro', 'cidade', 'uf'];
  var copiaEndereco = function () {
    blocoCor.hidden = mesmo.checked;
    if (mesmo.checked) {
      nomes.forEach(function (n) { $(n + '-cor').value = $(n + '-res').value; });
    }
  };
  mesmo.addEventListener('change', copiaEndereco);
  nomes.forEach(function (n) {
    ['input', 'change'].forEach(function (ev) {
      $(n + '-res').addEventListener(ev, copiaEndereco);
    });
  });
  copiaEndereco();

  /* Validação */
  var regras = [
    { id: 'cpf', ok: function (v) { return soDigitos(v).length === 11; } },
    { id: 'tel', ok: function (v) { var n = soDigitos(v).length; return n === 10 || n === 11; } },
    { id: 'cep-res', ok: function (v) { return soDigitos(v).length === 8; } }
  ];
  var resumo = $('resumo-erros'), lista = $('lista-erros'), titulo = $('titulo-erros');
  var nomeCampo = function (id) { return $(id).labels[0].textContent.replace(/\*/g, '').trim(); };
  var valida = function () {
    var falhas = [];
    regras.forEach(function (r) {
      var el = $(r.id), ok = r.ok(el.value);
      el.setAttribute('aria-invalid', String(!ok));
      el.closest('.campo').classList.toggle('tem-erro', !ok);
      $('e-' + r.id).hidden = ok;
      if (!ok) falhas.push(r.id);
    });
    resumo.hidden = falhas.length === 0;
    titulo.textContent = 'Há ' + falhas.length + (falhas.length === 1 ? ' problema' : ' problemas') + ' nesta etapa';
    lista.innerHTML = falhas.map(function (id) {
      return '<li><a href="#' + id + '">' + nomeCampo(id) + '</a></li>';
    }).join('');
    return falhas;
  };
  regras.forEach(function (r) {
    $(r.id).addEventListener('input', function () {
      if ($(r.id).getAttribute('aria-invalid') === 'true') valida();
    });
  });
  valida();

  form.addEventListener('submit', function (e) {
    var falhas = valida();
    if (falhas.length) { e.preventDefault(); resumo.focus(); return; }
    if (!form.checkValidity()) { e.preventDefault(); form.reportValidity(); }
  });
})();
