var fundoAtivo = null, focoAnterior = null;
function abrirModal(fundo, titulo) {
  focoAnterior = document.activeElement;
  if (titulo) fundo.querySelector('h2').textContent = titulo;
  fundo.hidden = false;
  fundoAtivo = fundo;
  var botoes = fundo.querySelectorAll('button');
  botoes[botoes.length - 1].focus();
}
function fecharModal() {
  if (!fundoAtivo) return;
  fundoAtivo.hidden = true;
  fundoAtivo = null;
  if (focoAnterior) focoAnterior.focus();
}
document.addEventListener('keydown', function (e) {
  if (!fundoAtivo) return;
  if (e.key === 'Escape') { fecharModal(); return; }
  if (e.key !== 'Tab') return;
  var botoes = fundoAtivo.querySelectorAll('button');
  var primeiro = botoes[0], ultimo = botoes[botoes.length - 1];
  if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
  else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
});
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  var fundo = document.getElementById(b.getAttribute('data-abrir'));
  var linha = b.closest('tr');
  var app = linha ? linha.querySelector('th').textContent : null;
  if (app) b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  b.addEventListener('click', function () {
    if (app) {
      document.getElementById('dlg-revogar-d').textContent = app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      abrirModal(fundo, 'Revogar acesso de ' + app + '?');
    } else {
      abrirModal(fundo, null);
    }
  });
});
