(function () {
  var live = document.getElementById('live');
  var ultimoGatilho = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrirModal(id, gatilho) {
    var fundo = document.getElementById(id);
    ultimoGatilho = gatilho;
    fundo.hidden = false;
    var primeiro = fundo.querySelector('.modal .btn:not(.perigo)');
    (primeiro || fundo.querySelector('.modal button')).focus();
  }

  function fecharModal(fundo) {
    fundo.hidden = true;
    if (ultimoGatilho) ultimoGatilho.focus();
    ultimoGatilho = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        var app = b.closest('tr').querySelector('th').textContent;
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
      }
      abrirModal(id, b);
    });
  });

  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.addEventListener('click', function (e) { if (e.target === fundo) fecharModal(fundo); });
    fundo.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(fundo); return; }
      if (e.key !== 'Tab') return;
      var foc = fundo.querySelectorAll('button:not([disabled])');
      var primeiro = foc[0], ultimo = foc[foc.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });

  var banner = document.getElementById('banner-sucesso');
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    banner.hidden = true;
    document.querySelector('#form-prefs input').focus();
  });

  var formPerfil = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  formPerfil.addEventListener('submit', function (e) {
    e.preventDefault();
    var invalidos = Array.prototype.filter.call(
      formPerfil.querySelectorAll('input,select,textarea'),
      function (c) { return c.getAttribute('aria-invalid') === 'true' || !c.checkValidity(); }
    );
    if (invalidos.length) {
      resumo.querySelector('h2').textContent = 'Corrija ' + invalidos.length + (invalidos.length === 1 ? ' campo' : ' campos') + ' para salvar o perfil';
      resumo.hidden = false;
      resumo.focus();
      anunciar('Não foi possível salvar o perfil. Corrija os campos destacados.');
      return;
    }
    resumo.hidden = true;
    anunciar('Perfil salvo.');
  });
})();
