var ultimoGatilho = null;
var modalAtivo = null;
function abrirModal(id, gatilho) {
  var fundo = document.getElementById(id);
  var linha = gatilho.closest('tr');
  if (id === 'fundo-revogar' && linha) {
    document.getElementById('dlg-revogar-d').textContent = 'O aplicativo "' + linha.querySelector('th').textContent + '" deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
  }
  ultimoGatilho = gatilho;
  modalAtivo = fundo;
  fundo.hidden = false;
  var botoes = fundo.querySelectorAll('[data-fechar]');
  botoes[botoes.length - 1].focus();
}
function fecharModal(fundo) {
  fundo.hidden = true;
  modalAtivo = null;
  if (ultimoGatilho) ultimoGatilho.focus();
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir'), b); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.querySelectorAll('[data-modal]').forEach(function (f) {
  f.addEventListener('click', function (e) { if (e.target === f) fecharModal(f); });
});
document.addEventListener('keydown', function (e) {
  if (!modalAtivo) return;
  if (e.key === 'Escape') { fecharModal(modalAtivo); return; }
  if (e.key === 'Tab') {
    var foc = modalAtivo.querySelectorAll('button:not([disabled])');
    var primeiro = foc[0];
    var ultimo = foc[foc.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});
document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
});
@@ FIM

