function ordenar(th){
  var proximo = th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
  th.parentElement.querySelectorAll('th[aria-sort]').forEach(function (c) {
    c.setAttribute('aria-sort', 'none');
    var s = c.querySelector('.seta'); if (s) s.textContent = '⇅';
  });
  th.setAttribute('aria-sort', proximo);
  var seta = th.querySelector('.seta'); if (seta) seta.textContent = proximo === 'ascending' ? '▲' : '▼';
}
document.querySelectorAll('.tabela thead .ord').forEach(function (b) {
  b.addEventListener('click', function () { ordenar(b.closest('th')); });
});
