(function () {
  var live = document.getElementById('live');
  var ultimoFoco = null;
  var seletorFoco = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';

  function anunciar(texto) {
    live.textContent = '';
    setTimeout(function () { live.textContent = texto; }, 50);
  }

  function abrirModal(id, origem) {
    var fundo = document.getElementById(id);
    ultimoFoco = origem || document.activeElement;
    fundo.hidden = false;
    var caixa = fundo.querySelector('[role="dialog"]');
    var seguro = caixa.querySelector('[data-fechar]:not(.perigo)');
    (seguro || caixa).focus();
  }

  function fecharModal(fundo) {
    fundo.hidden = true;
    if (ultimoFoco && document.body.contains(ultimoFoco)) { ultimoFoco.focus(); }
    ultimoFoco = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      var linha = b.closest('tr');
      if (id === 'fundo-revogar' && linha) {
        var app = linha.querySelector('th').textContent;
        document.getElementById('dlg-revogar-d').textContent =
          'O aplicativo ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrirModal(id, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) { return; }
    if (e.key === 'Escape') { fecharModal(aberto); return; }
    if (e.key === 'Tab') {
      var focaveis = aberto.querySelectorAll(seletorFoco);
      var primeiro = focaveis[0];
      var ultimo = focaveis[focaveis.length - 1];
      if (e.shiftKey && (document.activeElement === primeiro || !aberto.contains(document.activeElement))) {
        e.preventDefault(); ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault(); primeiro.focus();
      }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var titulo = document.getElementById('h-pref');
    titulo.setAttribute('tabindex', '-1');
    document.getElementById('banner-sucesso').hidden = true;
    titulo.focus();
  });

  var bio = document.getElementById('bio');
  var contador = document.getElementById('contador-bio');
  function atualizarContador() { contador.textContent = 200 - bio.value.length; }
  bio.addEventListener('input', atualizarContador);
  atualizarContador();

  var formPerfil = document.getElementById('form-perfil');
