<script>
(function () {
  var modal = null, gatilho = null;
  var resumo = document.getElementById('resumo-perfil');
  var live = document.getElementById('live');
  var form = document.getElementById('form-perfil');
  var banner = document.getElementById('banner-sucesso');

  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  function abrir(id, origem) {
    modal = document.getElementById(id);
    gatilho = origem;
    if (origem && origem.closest('tr')) {
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + origem.closest('tr').querySelector('th').textContent + '?';
    }
    modal.hidden = false;
    (modal.querySelector('[data-inicial]') || modal.querySelector('button')).focus();
  }

  function fechar() {
    if (!modal) return;
    modal.hidden = true;
    var o = gatilho;
    modal = null; gatilho = null;
    if (o) o.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fechar);
  });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(); });
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') fechar(); });

  document.querySelectorAll('tbody td button').forEach(function (b) {
    var nome = b.closest('tr').querySelector('th').textContent;
    b.setAttribute('aria-label', b.textContent.trim() + ' – ' + nome);
  });

  document.querySelectorAll('.estado').forEach(function (e) {
    var p = e.querySelector('.ponto');
    e.appendChild(document.createTextNode(p.getAttribute('aria-label')));
    p.setAttribute('aria-hidden', 'true');
    p.removeAttribute('aria-label');
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () { banner.hidden = true; });

  var regras = [
    { id: 'email', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()); },
      msg: 'Falta o domínio depois do @. Exemplo: lucas.moreira@translog.com.br.' },
    { id: 'telefone', ok: function (v) { var n = v.replace(/\D/g, '').length; return n === 10 || n === 11; },
      msg: 'Telefone incompleto. Informe o DDD e o número completo, com 10 ou 11 dígitos.' }
  ];

  function checar() {
    var falhas = [];
    regras.forEach(function (r) {
      var input = document.getElementById(r.id);
      var erro = document.getElementById('erro-' + r.id);
      var valido = r.ok(input.value);
      input.setAttribute('aria-invalid', valido ? 'false' : 'true');
      input.closest('.campo').classList.toggle('campo-erro', !valido);
      erro.textContent = r.msg;
      erro.hidden = valido;
      if (!valido) falhas.push(r.id);
    });
    resumo.querySelectorAll('li').forEach(function (li) {
      li.hidden = falhas.indexOf(li.getAttribute('data-campo')) < 0;
    });
    var n = falhas.length;
    resumo.querySelector('h2').textContent = 'Corrija ' + (n === 1 ? '1 campo' : n + ' campos') + ' para salvar o perfil';
    resumo.hidden = n === 0;
    return falhas;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault(); // Trocar pelo envio real (fetch) quando o endpoint existir.
    var falhas = checar();
    if (falhas.length) { resumo.focus(); return; }
    anunciar('Perfil salvo.');
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault(); // Trocar pelo envio real (fetch) quando o endpoint existir.
    banner.hidden = false;
    anunciar('Preferências salvas.');
  });

  checar();
})();
</script>
