@@ DEPOIS
(function () {
  var ultimoFoco = null;

  function abrir(id, nomeApp) {
    var m = document.getElementById(id);
    ultimoFoco = document.activeElement;
    if (id === 'fundo-revogar' && nomeApp) {
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nomeApp + '?';
      document.getElementById('dlg-revogar-d').textContent = 'O aplicativo ' + nomeApp + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    m.hidden = false;
    var botoes = m.querySelectorAll('[data-fechar]');
    botoes[botoes.length - 1].focus();
  }

  function fechar(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var tr = b.closest('tr');
      var nome = tr ? tr.querySelector('th').textContent.trim() : '';
      abrir(b.getAttribute('data-abrir'), nome);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (aberto) fechar(aberto);
  });

  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
    tr.querySelectorAll('button').forEach(function (b) {
      var t = b.textContent.trim();
      if (t === 'Revogar acesso' || t === 'Encerrar sessão') {
        b.setAttribute('aria-label', t + ' de ' + nome);
      }
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var regras = {
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v); },
    telefone: function (v) { return /^\(\d{2}\) \d{4,5}-\d{4}$/.test(v); }
  };
  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');

  form.addEventListener('submit', function (e) {
    var itens = [];
    Object.keys(regras).forEach(function (id) {
      var input = document.getElementById(id);
      var erro = document.getElementById('erro-' + id);
      var falhou = !regras[id](input.value.trim());
      input.closest('.campo').classList.toggle('erro-ativo', falhou);
      input.setAttribute('aria-invalid', String(falhou));
      input.setAttribute('aria-describedby', falhou ? 'dica-' + id + ' erro-' + id : 'dica-' + id);
      erro.hidden = !falhou;
      if (falhou) {
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + id;
        a.textContent = erro.textContent;
        li.appendChild(a);
        itens.push(li);
      }
    });
    if (itens.length) {
      e.preventDefault();
      lista.textContent = '';
      itens.forEach(function (li) { lista.appendChild(li); });
      resumo.hidden = false;
      resumo.focus();
    } else {
      resumo.hidden = true;
    }
  });
})();
@@ FIM

