<script>
(function () {
  var ajuda = document.querySelector('[aria-controls="gaveta"]');
  var gaveta = document.getElementById('gaveta');
  var principal = document.getElementById('conteudo');

  if (ajuda && gaveta) {
    ajuda.addEventListener('click', function () {
      var abrir = gaveta.hidden;
      gaveta.hidden = !abrir;
      ajuda.setAttribute('aria-expanded', String(abrir));
      if (abrir) { gaveta.querySelector('a').focus(); }
    });
  }

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () {
      b.closest('.banner').remove();
      if (principal) { principal.focus(); }
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('[data-fechar-modal], .modal-x')) { m.hidden = true; }
    });
  });

  var convite = document.querySelector('[data-enviar-convite]');
  if (convite) {
    convite.addEventListener('click', function () {
      var email = document.getElementById('conv-email');
      var erro = document.getElementById('conv-erro');
      if (email.checkValidity()) {
        erro.hidden = true;
        email.removeAttribute('aria-invalid');
        return;
      }
      erro.hidden = false;
      email.setAttribute('aria-invalid', 'true');
      email.focus();
    });
  }

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') { return; }
    document.querySelectorAll('.modal:not([hidden])').forEach(function (m) { m.hidden = true; });
    if (gaveta && !gaveta.hidden) {
      gaveta.hidden = true;
      ajuda.setAttribute('aria-expanded', 'false');
      ajuda.focus();
    }
  });
})();
</script>
</body>
