(function () {
  var live = document.getElementById('live');
  var modalAberto = null;
  var ultimoFoco = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrirModal(id) {
    var f = document.getElementById(id);
    ultimoFoco = document.activeElement;
    modalAberto = f;
    f.hidden = false;
    f.querySelector('[data-inicial]').focus();
  }

  function fecharModal() {
    if (!modalAberto) return;
    modalAberto.hidden = true;
    modalAberto = null;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir="fundo-excluir"]').forEach(function (b) {
    b.addEventListener('click', function () { abrirModal('fundo-excluir'); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fecharModal);
  });
  document.querySelectorAll('.modal-fundo').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fecharModal(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!modalAberto) return;
    if (e.key === 'Escape') { fecharModal(); return; }
    if (e.key !== 'Tab') return;
    var botoes = modalAberto.querySelectorAll('button');
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.querySelectorAll('#acessos .estado').forEach(function (e) {
    var p = e.querySelector('.ponto');
    var t = document.createElement('span');
    t.className = 'estado-txt';
    t.textContent = p.getAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.removeAttribute('aria-label');
    e.appendChild(t);
  });

  var tabelaApps = document.querySelectorAll('#acessos table')[0];
  function contarAtivos() {
    var n = tabelaApps.querySelectorAll('.ponto.ok').length;
    document.getElementById('contagem-acessos').textContent = n + (n === 1 ? ' aplicativo ativo' : ' aplicativos ativos');
  }

  tabelaApps.querySelectorAll('.btn.perigo-suave').forEach(function (b) {
    var linha = b.closest('tr');
    var nome = linha.querySelector('th').textContent;
    var ponto = linha.querySelector('.ponto');
    var txt = linha.querySelector('.estado-txt');
    var classeOriginal = ponto.className;
    var textoOriginal = txt.textContent;
    b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
    b.addEventListener('click', function () {
      var revogar = b.getAttribute('data-revogado') !== 'sim';
      b.setAttribute('data-revogado', revogar ? 'sim' : 'nao');
      b.textContent = revogar ? 'Desfazer' : 'Revogar acesso';
      b.setAttribute('aria-label', (revogar ? 'Desfazer revogação de ' : 'Revogar acesso de ') + nome);
      ponto.className = revogar ? 'ponto exp' : classeOriginal;
      txt.textContent = revogar ? 'Revogado' : textoOriginal;
      anunciar(revogar ? 'Acesso de ' + nome + ' revogado. Você pode desfazer.' : 'Acesso de ' + nome + ' restaurado.');
      contarAtivos();
    });
  });
  contarAtivos();

  document.querySelectorAll('#acessos table')[1].querySelectorAll('tbody button').forEach(function (b) {
    var linha = b.closest('tr');
    var dispositivo = linha.querySelector('th').textContent;
    b.setAttribute('aria-label', 'Encerrar sessão em ' + dispositivo);
    b.addEventListener('click', function () {
      linha.remove();
      anunciar('Sessão encerrada em ' + dispositivo + '.');
    });
  });

  function marcarErro(campo, msg, invalido) {
    msg.hidden = !invalido;
    campo.setAttribute('aria-invalid', String(invalido));
    campo.closest('.campo').classList.toggle('campo-erro', invalido);
  }

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var email = document.getElementById('email');
    var tel = document.getElementById('telefone');
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim());
    var digitos = tel.value.replace(/\D/g, '');
    var telOk = digitos.length === 10 || digitos.length === 11;
    marcarErro(email, document.getElementById('erro-email'), !emailOk);
    marcarErro(tel, document.getElementById('erro-telefone'), !telOk);
    if (!emailOk) { email.focus(); return; }
    if (!telOk) { tel.focus(); return; }
    anunciar('Perfil salvo.');
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
