<script>
(function(){
  var ajuda=document.querySelector('[aria-controls="gaveta"]');
  var gaveta=document.getElementById('gaveta');
  var gatilho=null;

  function abrirModal(el,origem){
    gatilho=origem||null;
    el.hidden=false;
    var alvo=el.querySelector('input')||el.querySelector('[data-fechar]')||el.querySelector('button');
    if(alvo)alvo.focus();
  }
  function fecharModal(el){
    el.hidden=true;
    if(gatilho){gatilho.focus();gatilho=null;}
  }
  function abrirGaveta(){
    gaveta.hidden=false;
    ajuda.setAttribute('aria-expanded','true');
    gaveta.querySelector('a').focus();
  }
  function fecharGaveta(){
    gaveta.hidden=true;
    ajuda.setAttribute('aria-expanded','false');
    ajuda.focus();
  }
  function modalAberto(){return document.querySelector('.modal:not([hidden])');}

  ajuda.addEventListener('click',function(){
    if(gaveta.hidden)abrirGaveta();else fecharGaveta();
  });

  document.querySelectorAll('[data-abre]').forEach(function(b){
    b.addEventListener('click',function(){
      abrirModal(document.getElementById(b.getAttribute('data-abre')),b);
    });
  });

  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.closest('[data-fechar],.modal-x'))fecharModal(m);
    });
  });

  var email=document.getElementById('conv-email');
  if(email){
    email.closest('.modal').querySelector('.btn-prim').addEventListener('click',function(){
      var ok=email.checkValidity();
      email.setAttribute('aria-invalid',ok?'false':'true');
      document.getElementById('conv-erro').hidden=ok;
      if(!ok)email.focus();
    });
  }

  document.querySelectorAll('[data-dispensar]').forEach(function(b){
    b.addEventListener('click',function(){
      var banner=b.closest('.banner');
      document.getElementById('conteudo').focus();
      banner.remove();
    });
  });

  document.addEventListener('keydown',function(e){
    var m=modalAberto();
    if(m&&e.key==='Escape'){fecharModal(m);return;}
    if(m&&e.key==='Tab'){
      var f=[].slice.call(m.querySelectorAll('button,input,a[href]'));
      var p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){u.focus();e.preventDefault();}
      else if(!e.shiftKey&&document.activeElement===u){p.focus();e.preventDefault();}
      return;
    }
    if(e.key==='Escape'&&!gaveta.hidden)fecharGaveta();
  });

  var corpo=document.querySelector('table').tBodies[0];
  function valor(td){
    var t=td.querySelector('time');
    return t?t.getAttribute('datetime'):td.textContent.trim().toLowerCase();
  }
  document.querySelectorAll('[data-ordenar]').forEach(function(b){
    b.addEventListener('click',function(){
      var th=b.closest('th');
      var col=Number(b.getAttribute('data-ordenar'));
      var asc=th.getAttribute('aria-sort')!=='ascending';
      document.querySelectorAll('th[aria-sort]').forEach(function(x){
        x.setAttribute('aria-sort','none');
        x.querySelector('.seta').textContent='';
      });
      th.setAttribute('aria-sort',asc?'ascending':'descending');
      th.querySelector('.seta').textContent=asc?' ▲':' ▼';
      [].slice.call(corpo.rows).sort(function(l1,l2){
        var x1=valor(l1.cells[col]),x2=valor(l2.cells[col]);
        return (x1<x2?-1:x1>x2?1:0)*(asc?1:-1);
      }).forEach(function(l){corpo.appendChild(l);});
    });
  });
})();
</script>
</body>
