var ultimoFoco = null;
function abrirModal(id, titulo) {
  ultimoFoco = document.activeElement;
  var fundo = document.getElementById(id);
  if (titulo) { fundo.querySelector('h2').textContent = titulo; }
  fundo.hidden = false;
  var primeiro = fundo.querySelector('input, [data-fechar]');
  (primeiro || fundo.querySelector('button')).focus();
}
function fecharModal(fundo) {
  fundo.hidden = true;
  if (ultimoFoco) { ultimoFoco.focus(); }
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  var linha = b.closest('tr');
  var app = linha ? linha.querySelector('th').textContent : '';
  if (app) { b.setAttribute('aria-label', 'Revogar acesso de ' + app); }
  b.addEventListener('click', function () {
    var id = b.getAttribute('data-abrir');
    abrirModal(id, id === 'fundo-revogar' ? 'Revogar acesso de ' + app + '?' : null);
  });
});
@@ FIM

