document.getElementById('form-perfil').addEventListener('submit', function (e) {
  var lista = document.getElementById('lista-erros');
  var resumo = document.getElementById('resumo-erros');
  var checagens = {
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); },
    telefone: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }
  };
  lista.innerHTML = '';
  Object.keys(checagens).forEach(function (id) {
    var campo = document.getElementById(id);
    var erro = document.getElementById('erro-' + id);
    var falhou = !checagens[id](campo.value.trim());
    campo.setAttribute('aria-invalid', String(falhou));
    campo.parentNode.classList.toggle('campo-erro', falhou);
    erro.hidden = !falhou;
    if (falhou) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + id;
      a.textContent = campo.labels[0].textContent + ': ' + erro.textContent.replace(/^Erro:\s*/, '');
      li.appendChild(a);
      lista.appendChild(li);
    }
  });
  resumo.hidden = lista.children.length === 0;
  if (lista.children.length > 0) {
    e.preventDefault();
    document.getElementById('titulo-erros').focus();
  }
});
