<script>
(function () {
  var ajuda = document.getElementById('btn-ajuda');
  var gaveta = document.getElementById('gaveta');

  function alternarGaveta(abrir) {
    gaveta.hidden = !abrir;
    ajuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) { gaveta.querySelector('a').focus(); } else { ajuda.focus(); }
  }
  ajuda.addEventListener('click', function () {
    alternarGaveta(gaveta.hidden);
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (botao) {
    botao.addEventListener('click', function () {
      botao.closest('.banner').remove();
    });
  });

  function fecharModal(modal) {
    modal.hidden = true;
  }
  document.querySelectorAll('.modal').forEach(function (modal) {
    modal.addEventListener('click', function (e) {
      var alvo = e.target;
      var fecha = alvo === modal ||
        alvo.classList.contains('modal-x') ||
        (alvo.closest('.modal-acoes') && alvo.tagName === 'BUTTON' && !alvo.matches('.btn-prim, .btn-perigo'));
      if (fecha) { fecharModal(modal); }
    });
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') { return; }
    var aberto = document.querySelector('.modal:not([hidden])');
    if (aberto) { fecharModal(aberto); }
    else if (!gaveta.hidden) { alternarGaveta(false); }
  });
})();
</script>
</body>
