function anunciar(texto) {
  var live = document.getElementById('live');
  live.textContent = '';
  setTimeout(function () { live.textContent = texto; }, 50);
}
function fecharModal(m) {
  m.hidden = true;
  if (m.gatilho) m.gatilho.focus();
}
function mostrarErro(campo, aviso, temErro) {
  aviso.hidden = !temErro;
  campo.setAttribute('aria-invalid', temErro ? 'true' : 'false');
}
document.querySelectorAll('[data-abrir]:not([data-abrir="fundo-revogar"])').forEach(function (b) {
  b.addEventListener('click', function () {
    var m = document.getElementById(b.getAttribute('data-abrir'));
    m.gatilho = b;
    m.hidden = false;
    m.querySelector('[data-padrao]').focus();
  });
});
document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
  var app = b.closest('tr').querySelector('th').textContent;
  b.setAttribute('aria-label', 'Revogar acesso: ' + app);
  b.addEventListener('click', function () {
    var revogado = b.getAttribute('data-revogado') === '1';
    b.setAttribute('data-revogado', revogado ? '0' : '1');
    b.textContent = revogado ? 'Revogar acesso' : 'Desfazer';
    b.setAttribute('aria-label', (revogado ? 'Revogar acesso: ' : 'Desfazer revogação: ') + app);
    anunciar(revogado ? 'Acesso de ' + app + ' restaurado.' : 'Acesso de ' + app + ' revogado. Você pode desfazer.');
  });
});
document.querySelectorAll('tbody td .btn:not([data-abrir])').forEach(function (b) {
  var app = b.closest('tr').querySelector('th').textContent;
  b.setAttribute('aria-label', b.textContent.trim() + ': ' + app);
});
document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
  p.insertAdjacentText('afterend', ' ' + p.getAttribute('aria-label'));
  p.removeAttribute('aria-label');
  p.setAttribute('aria-hidden', 'true');
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.addEventListener('keydown', function (e) {
  if (e.key !== 'Escape') return;
  document.querySelectorAll('[data-modal]:not([hidden])').forEach(function (m) { fecharModal(m); });
});
document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
});
document.getElementById('form-perfil').addEventListener('submit', function (e) {
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
  var digitos = tel.value.replace(/\D/g, '');
  var telOk = digitos.length === 10 || digitos.length === 11;
  mostrarErro(email, document.getElementById('erro-email'), !emailOk);
  mostrarErro(tel, document.getElementById('erro-telefone'), !telOk);
  var faltas = [];
  if (!emailOk) faltas.push(['email', 'E-mail: informe um endereço válido, como nome@escola.com.br.']);
  if (!telOk) faltas.push(['telefone', 'Telefone: informe o número com DDD.']);
  var resumo = document.getElementById('resumo-erros');
  resumo.hidden = faltas.length === 0;
  if (faltas.length === 0) return;
  e.preventDefault();
  var lista = document.getElementById('lista-erros');
  lista.textContent = '';
  faltas.forEach(function (f) {
    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = '#' + f[0];
    a.textContent = f[1];
    li.appendChild(a);
    lista.appendChild(li);
  });
  resumo.focus();
});
@@ FIM

