var live = document.getElementById('live');
var gatilhoAtivo = null;

function abrirModal(modal, gatilho) {
  gatilhoAtivo = gatilho;
  modal.hidden = false;
  var foco = modal.querySelector('[data-foco-inicial]') || modal.querySelector('button');
  foco.focus();
}

function fecharModal(modal) {
  modal.hidden = true;
  if (gatilhoAtivo) gatilhoAtivo.focus();
  gatilhoAtivo = null;
}

document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    abrirModal(document.getElementById(b.getAttribute('data-abrir')), b);
  });
});

document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});

document.querySelectorAll('[data-modal]').forEach(function (modal) {
  modal.addEventListener('keydown', function (e) {
    if (modal.hidden) return;
    if (e.key === 'Escape') { fecharModal(modal); return; }
    if (e.key === 'Tab') {
      var botoes = modal.querySelectorAll('button');
      var primeiro = botoes[0];
      var ultimo = botoes[botoes.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });
});

var banner = document.getElementById('banner-sucesso');
document.getElementById('btn-dispensar').addEventListener('click', function () {
  banner.hidden = true;
  var titulo = document.getElementById('h-pref');
  titulo.setAttribute('tabindex', '-1');
  titulo.focus();
  live.textContent = 'Mensagem de confirmação dispensada.';
});
@@ FIM

