var live = document.getElementById('live');
var ultimoGatilho = null;
function abrirModal(m, gatilho) {
  ultimoGatilho = gatilho;
  m.hidden = false;
  var cancelar = m.querySelector('.btn:not(.perigo)');
  (cancelar || m.querySelector('button')).focus();
}
function fecharModal(m) {
  m.hidden = true;
  if (ultimoGatilho) ultimoGatilho.focus();
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  var m = document.getElementById(b.getAttribute('data-abrir'));
  var linha = b.closest('tr');
  var app = linha ? linha.querySelector('th').textContent : '';
  if (linha) b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  b.addEventListener('click', function () {
    if (linha) m.querySelector('#dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
    abrirModal(m, b);
  });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.addEventListener('keydown', function (e) {
  if (e.key !== 'Escape') return;
  document.querySelectorAll('[data-modal]').forEach(function (m) { if (!m.hidden) fecharModal(m); });
});
var form = document.getElementById('form-perfil');
var emailEl = document.getElementById('email');
var telEl = document.getElementById('telefone');
function marcarErro(input, erroId, msg) {
  var erro = document.getElementById(erroId);
  erro.textContent = msg;
  erro.hidden = false;
  input.closest('.campo').classList.add('campo-erro');
  input.setAttribute('aria-invalid', 'true');
}
function limparErro(input, erroId) {
  document.getElementById(erroId).hidden = true;
  input.closest('.campo').classList.remove('campo-erro');
  input.removeAttribute('aria-invalid');
}
form.addEventListener('submit', function (e) {
  var primeiro = null;
  if (/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(emailEl.value.trim())) {
    limparErro(emailEl, 'erro-email');
  } else {
    marcarErro(emailEl, 'erro-email', 'Informe um e-mail válido, por exemplo nome@empresa.com.br.');
    primeiro = emailEl;
  }
  var digitos = telEl.value.replace(/\D/g, '');
  if (digitos.length === 10 || digitos.length === 11) {
    limparErro(telEl, 'erro-telefone');
  } else {
    marcarErro(telEl, 'erro-telefone', 'Telefone incompleto. Informe o DDD e os 10 ou 11 dígitos.');
    primeiro = primeiro || telEl;
  }
  if (primeiro) {
    e.preventDefault();
    primeiro.focus();
    live.textContent = 'Corrija os campos destacados para salvar.';
  }
});
@@ FIM

