@@ DEPOIS
(function () {
  var live = document.getElementById('live');
  var ultimoFoco = null;
  var appSelecionado = '';

  function anunciar(texto) {
    live.textContent = '';
    setTimeout(function () { live.textContent = texto; }, 50);
  }

  // Rótulos únicos para botões repetidos e texto visível para o estado (não só cor)
  document.querySelectorAll('#acessos tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
    var botao = tr.querySelector('button');
    if (botao) botao.setAttribute('aria-label', botao.textContent.trim() + ' de ' + nome);
  });
  document.querySelectorAll('.estado').forEach(function (e) {
    var ponto = e.querySelector('.ponto');
    if (!ponto) return;
    var texto = document.createElement('span');
    texto.textContent = ponto.getAttribute('aria-label');
    ponto.setAttribute('aria-hidden', 'true');
    e.appendChild(texto);
  });

  function abrir(id, botao) {
    ultimoFoco = botao;
    var fundo = document.getElementById(id);
    if (id === 'fundo-revogar') {
      appSelecionado = botao.closest('tr').querySelector('th').textContent.trim();
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + appSelecionado + '?';
      document.getElementById('dlg-revogar-d').textContent = 'O aplicativo ' + appSelecionado + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    fundo.hidden = false;
    var botoes = fundo.querySelectorAll('[data-fechar]');
    botoes[botoes.length - 1].focus();
  }

  function fechar(fundo) {
    fundo.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (aberto) fechar(aberto);
  });

  // Validação do perfil antes de enviar
  var form = document.getElementById('form-perfil');
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var emailOk = true, telOk = true;

  function marcar(campo, erroId, ok) {
    campo.setAttribute('aria-invalid', ok ? 'false' : 'true');
    campo.closest('.campo').classList.toggle('campo-erro', !ok);
    document.getElementById(erroId).hidden = ok;
  }

  function validar() {
    emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim());
    telOk = /^\(\d{2}\) 9\d{4}-\d{4}$/.test(tel.value.trim());
    marcar(email, 'erro-email', emailOk);
    marcar(tel, 'erro-telefone', telOk);
  }

  form.addEventListener('submit', function (e) {
    validar();
    if (emailOk && telOk) return;
    e.preventDefault();
    (emailOk ? tel : email).focus();
    anunciar('Corrija os campos destacados antes de salvar.');
  });
  email.addEventListener('blur', validar);
  tel.addEventListener('blur', validar);

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
@@ FIM

