<script>
(function () {
  var foco = null;
  var gaveta = document.getElementById('gaveta');
  var ajuda = document.querySelector('[aria-controls="gaveta"]');
  var btnFecharGaveta = document.getElementById('fechar-gaveta');

  function abrirModal(m) {
    foco = document.activeElement;
    m.hidden = false;
    var alvo = m.querySelector('input') || m.querySelector('.btn-prim') || m.querySelector('button');
    if (alvo) alvo.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (foco) foco.focus();
  }
  function fecharGaveta() {
    gaveta.hidden = true;
    ajuda.setAttribute('aria-expanded', 'false');
    ajuda.focus();
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('aria-controls')));
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x') || e.target.closest('.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)')) {
        fecharModal(m);
      }
    });
  });

  if (ajuda && gaveta) {
    ajuda.addEventListener('click', function () {
      var abrir = gaveta.hidden;
      gaveta.hidden = !abrir;
      ajuda.setAttribute('aria-expanded', String(abrir));
      if (abrir) gaveta.querySelector('a').focus();
    });
  }
  if (btnFecharGaveta) btnFecharGaveta.addEventListener('click', fecharGaveta);

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () {
      var banner = b.closest('.banner');
      document.getElementById('conteudo').focus();
      banner.remove();
    });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (aberto) fecharModal(aberto);
      else if (gaveta && !gaveta.hidden) fecharGaveta();
      return;
    }
    if (e.key === 'Tab' && aberto) {
      var f = aberto.querySelectorAll('button, input');
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        primeiro.focus();
      }
    }
  });
})();
</script>
</body>
