(function () {
  var ultimoFoco = null;
  var regras = [
    { campo: 'email', rotulo: 'E-mail corporativo', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
    { campo: 'telefone', rotulo: 'Telefone celular', ok: function (v) { var n = v.replace(/\D/g, '').length; return n >= 10 && n <= 11; } },
    { campo: 'bio', rotulo: 'Sobre você', ok: function (v) { return v.length <= 200; } }
  ];

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var c = m.querySelector('.acoes .btn:not(.perigo)');
    if (c) c.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco && ultimoFoco.focus) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var m = document.getElementById(b.getAttribute('data-abrir'));
      if (m.id === 'fundo-revogar') {
        var nome = b.closest('tr').querySelector('th').textContent;
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nome + '?';
      }
      abrirModal(m);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    document.querySelectorAll('[data-modal]').forEach(function (m) { if (!m.hidden) fecharModal(m); });
  });

  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent;
    tr.querySelectorAll('td button').forEach(function (b) {
      var t = b.textContent.trim();
      if (t === 'Revogar acesso' || t === 'Encerrar sessão') {
        var s = document.createElement('span');
        s.className = 'sr-only';
        s.textContent = ' de ' + nome;
        b.appendChild(s);
      }
    });
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var t = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', t);
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  form.addEventListener('submit', function (e) {
    var falhas = [];
    regras.forEach(function (r) {
      var input = document.getElementById(r.campo);
      var erro = document.getElementById('erro-' + r.campo);
      var invalido = !r.ok(input.value);
      input.setAttribute('aria-invalid', invalido ? 'true' : 'false');
      erro.hidden = !invalido;
      input.closest('.campo').classList.toggle('campo-erro', invalido);
      if (invalido) falhas.push(r);
    });
    if (!falhas.length) { resumo.hidden = true; return; }
    e.preventDefault();
    lista.innerHTML = '';
    falhas.forEach(function (r) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + r.campo;
      a.textContent = r.rotulo;
      li.appendChild(a);
      lista.appendChild(li);
    });
    resumo.hidden = false;
    resumo.focus();
  });
})();
