(function () {
  var live = document.getElementById('live');
  var disparo = null;
  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }
  function focaveis(el) {
    return el.querySelectorAll('button:not([disabled]), a[href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
  }
  function abrir(id, origem) {
    var fundo = document.getElementById(id);
    disparo = origem || document.activeElement;
    fundo.hidden = false;
    var lista = focaveis(fundo);
    (lista[lista.length - 1] || fundo).focus();
  }
  function fechar(fundo) {
    fundo.hidden = true;
    if (disparo) disparo.focus();
    disparo = null;
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.addEventListener('click', function (e) { if (e.target === fundo) fechar(fundo); });
    fundo.addEventListener('keydown', function (e) {
      if (fundo.hidden) return;
      if (e.key === 'Escape') { e.preventDefault(); fechar(fundo); return; }
      if (e.key === 'Tab') {
        var lista = focaveis(fundo);
        var primeiro = lista[0];
        var ultimo = lista[lista.length - 1];
        if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
        else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
      }
    });
  });
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var resumo = document.getElementById('resumo-erros');
    resumo.focus();
    anunciar('Corrija os campos destacados para salvar o perfil.');
  });
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var titulo = document.getElementById('h-pref');
    titulo.setAttribute('tabindex', '-1');
    titulo.focus();
  });
})();
@@ FIM

