<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var botaoAjuda=document.querySelector('[aria-controls="gaveta"]');
  var modalAtual=null, disparador=null;

  function focaveis(el){
    return el.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])');
  }
  function abrirGaveta(){
    gaveta.classList.add('aberta');
    botaoAjuda.setAttribute('aria-expanded','true');
    var primeiro=focaveis(gaveta)[0];
    if(primeiro) primeiro.focus();
  }
  function fecharGaveta(){
    gaveta.classList.remove('aberta');
    botaoAjuda.setAttribute('aria-expanded','false');
    botaoAjuda.focus();
  }
  function abrirModal(m,origem){
    disparador=origem||document.activeElement;
    m.hidden=false;
    modalAtual=m;
    var primeiro=focaveis(m)[0];
    if(primeiro) primeiro.focus();
  }
  function fecharModal(){
    if(!modalAtual) return;
    modalAtual.hidden=true;
    modalAtual=null;
    if(disparador) disparador.focus();
  }

  botaoAjuda.addEventListener('click',function(){
    gaveta.classList.contains('aberta')?fecharGaveta():abrirGaveta();
  });
  gaveta.querySelector('.modal-x').addEventListener('click',fecharGaveta);

  document.querySelectorAll('[data-modal]').forEach(function(b){
    b.addEventListener('click',function(){abrirModal(document.getElementById(b.dataset.modal),b);});
  });
  document.querySelectorAll('.modal .modal-x,.modal [data-fechar]').forEach(function(b){
    b.addEventListener('click',fecharModal);
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){ if(e.target===m) fecharModal(); });
  });

  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      if(modalAtual) fecharModal();
      else if(gaveta.classList.contains('aberta')) fecharGaveta();
      return;
    }
    if(e.key==='Tab' && modalAtual){
      var f=focaveis(modalAtual);
      if(!f.length) return;
      var primeiro=f[0], ultimo=f[f.length-1];
      if(e.shiftKey && document.activeElement===primeiro){ e.preventDefault(); ultimo.focus(); }
      else if(!e.shiftKey && document.activeElement===ultimo){ e.preventDefault(); primeiro.focus(); }
    }
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){ b.closest('.banner').remove(); });
  });
})();
</script>
</body>
