<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var email = document.getElementById('conv-email');
  var erroEmail = document.getElementById('conv-erro');

  function focaveis(el) {
    return Array.prototype.slice.call(el.querySelectorAll('a[href], button:not([disabled]), input:not([disabled])'));
  }
  function abrirModal(m) {
    m._retorno = document.activeElement;
    m.hidden = false;
    var f = focaveis(m.querySelector('.modal-caixa'))[0];
    if (f) f.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (m._retorno) m._retorno.focus();
  }
  function setGaveta(aberta) {
    gaveta.hidden = !aberta;
    btnAjuda.setAttribute('aria-expanded', String(aberta));
    if (aberta) focaveis(gaveta)[0].focus();
    else btnAjuda.focus();
  }

  window.abrirModal = abrirModal;

  btnAjuda.addEventListener('click', function () { setGaveta(gaveta.hidden); });
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click', function () { setGaveta(false); });

  document.querySelectorAll('.modal [data-fechar], .modal .modal-x').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('.modal')); });
  });

  document.getElementById('btn-enviar-convite').addEventListener('click', function () {
    if (email.checkValidity()) {
      erroEmail.hidden = true;
      email.removeAttribute('aria-invalid');
      return;
    }
    erroEmail.hidden = false;
    email.setAttribute('aria-invalid', 'true');
    email.focus();
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (aberto) fecharModal(aberto);
      else if (!gaveta.hidden) setGaveta(false);
      return;
    }
    if (e.key !== 'Tab' || !aberto) return;
    var f = focaveis(aberto.querySelector('.modal-caixa'));
    if (!f.length) return;
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });
})();
</script>
