<script>
function ordenar(btn){
  var th = btn.closest('th');
  var prox = th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
  th.parentElement.querySelectorAll('th[aria-sort]').forEach(function (t) {
    if (t !== th) { t.setAttribute('aria-sort', 'none'); t.querySelector('.seta').textContent = '⇅'; }
  });
  th.setAttribute('aria-sort', prox);
  th.querySelector('.seta').textContent = prox === 'ascending' ? '▲' : '▼';
}
document.querySelectorAll('[data-ordenar]').forEach(function (b) {
  b.addEventListener('click', function () { ordenar(b); });
});
document.querySelectorAll('.ac-b').forEach(function (b) {
