    b.setAttribute('aria-expanded', String(!aberto));
    var p = document.getElementById(b.getAttribute('aria-controls'));
    if (p) p.hidden = aberto;
  });
});
var btnFiltros = document.querySelector('.btn-filtros');
var asideFiltros = document.getElementById('filtros');
var mobile = window.matchMedia('(max-width:820px)');
function sincronizarFiltros() {
  asideFiltros.hidden = mobile.matches && btnFiltros.getAttribute('aria-expanded') !== 'true';
}
btnFiltros.addEventListener('click', function () {
  var aberto = btnFiltros.getAttribute('aria-expanded') === 'true';
  btnFiltros.setAttribute('aria-expanded', String(!aberto));
  btnFiltros.textContent = aberto ? 'Mostrar filtros' : 'Ocultar filtros';
  sincronizarFiltros();
});
mobile.addEventListener('change', sincronizarFiltros);
sincronizarFiltros();
document.querySelectorAll('.sw').forEach(function (s) {
