<script>
var $ = function (id) { return document.getElementById(id); };

var live = document.createElement('div');
live.className = 'sr-only';
live.setAttribute('role', 'status');
document.body.appendChild(live);
function anunciar(t) { live.textContent = t; }

function num(s) { return parseFloat(s.replace(/[^\d,]/g, '').replace(',', '.')); }
function fmt(v) {
  var p = v.toFixed(2).split('.');
  return 'R$ ' + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + p[1];
}

function totais() {
  var linhas = document.querySelectorAll('#itens tbody tr');
  var qtd = 0, sub = 0;
  linhas.forEach(function (tr) {
    qtd += parseInt(tr.cells[2].textContent, 10);
    sub += num(tr.cells[4].textContent);
  });
  var radio = document.querySelector('input[name=frete]:checked');
  var frete = radio ? num(radio.closest('label').querySelector('.preco').textContent) : 0;
  var desc = Math.round(sub * 10) / 100;
  var total = sub - desc + frete;
  var n = linhas.length;
  function set(sel, txt) {
    var el = document.querySelector('[data-r="' + sel + '"]');
    if (el) el.textContent = txt;
  }
  set('itens-tabela', n + ' produtos, ' + qtd + ' unidades');
  set('subtotal-itens', fmt(sub));
  set('qtd-resumo', 'Subtotal (' + qtd + ' un.)');
  set('subtotal', fmt(sub));
  set('desconto', '- ' + fmt(desc));
  set('total', fmt(total));
  set('pagar', 'Pagar ' + fmt(total));
  set('itens-rev', qtd + ' unidades em ' + n + ' produtos');
  var sel = $('parcelas');
  if (sel) {
    var atual = sel.value || '1';
    sel.innerHTML = '';
    for (var i = 1; i <= 10; i++) {
      var o = document.createElement('option');
      o.value = i;
      o.textContent = i + 'x de ' + fmt(total / i) + (i === 1 ? ' sem juros' : '');
      sel.appendChild(o);
    }
    sel.value = atual;
  }
}

var gatilho = null, alvo = null;
var dlg = $('dlg');
var tItens = $('t-itens');
tItens.setAttribute('tabindex', '-1');

function abrirDialogo(nome) {
  var ev = window.event;
  gatilho = (ev && ev.currentTarget) || document.activeElement;
  alvo = gatilho && gatilho.closest ? gatilho.closest('tr') : null;
  $('dlg-p').textContent = nome + ' será removido do pedido.';
  dlg.showModal();
}
function fecharDialogo() { dlg.close(); }
function confirmarRemocao() {
  if (alvo) alvo.remove();
  gatilho = null;
  alvo = null;
  totais();
  dlg.close();
  anunciar('Item removido do pedido. Resumo atualizado.');
}
dlg.addEventListener('close', function () {
  var destino = gatilho && document.body.contains(gatilho) ? gatilho : tItens;
  gatilho = null;
  destino.focus();
});

function buscarCep() {
  var campo = $('ent-cep'), s = $('cep-status');
  var cep = campo.value.replace(/\D/g, '');
  if (cep.length !== 8) {
    campo.setAttribute('aria-invalid', 'true');
    s.textContent = 'Informe um CEP com 8 dígitos.';
    campo.focus();
    return;
  }
  campo.removeAttribute('aria-invalid');
  s.textContent = 'Buscando endereço...';
  fetch('https://viacep.com.br/ws/' + cep + '/json/')
    .then(function (r) { if (!r.ok) throw new Error('http'); return r.json(); })
    .then(function (d) {
      if (d.erro) throw new Error('cep');
      if (!$('ent-rua').value) $('ent-rua').value = d.logradouro || '';
      $('ent-cidade').value = d.localidade || '';
      $('ent-uf').value = d.uf || '';
      s.textContent = 'Endereço localizado. Confira e informe o número.';
    })
    .catch(function () {
      s.textContent = 'Não foi possível localizar este CEP. Preencha o endereço manualmente.';
    });
}

function aplicarCupom() {
  var i = $('cupom'), e = $('cupom-erro');
  e.hidden = false;
  e.textContent = i.value.trim() ? 'Cupom inválido ou expirado.' : 'Informe o código do cupom.';
  i.setAttribute('aria-invalid', 'true');
  i.focus();
}

function alternarCobranca(c) {
  var b = $('bloco-cobranca');
  b.hidden = c.checked;
  b.querySelectorAll('input, select').forEach(function (el) { el.disabled = c.checked; });
}

function metodoMudou() {
  var m = document.querySelector('input[name=metodo]:checked').value;
  var cartao = m === 'cartao';
  var cf = $('cartao');
  cf.hidden = !cartao;
  cf.disabled = !cartao;
  var otp = $('otp');
  otp.closest('.bloco').hidden = !cartao;
  otp.disabled = !cartao;
}

function novoCartao() {
  $('alerta-pag').hidden = true;
  var n = $('cc-num');
  n.value = '';
  n.focus();
}

var timerReenvio = null;
function contarReenvio(seg) {
  var b = $('btn-reenviar'), info = $('reenvio-info');
  var restante = seg;
  b.disabled = true;
  info.textContent = 'Você poderá pedir um novo código em ' + restante + ' segundos.';
  clearInterval(timerReenvio);
  timerReenvio = setInterval(function () {
    restante--;
    if (restante <= 0) {
      clearInterval(timerReenvio);
      b.disabled = false;
      info.textContent = 'Você já pode pedir um novo código.';
      return;
    }
    info.textContent = 'Você poderá pedir um novo código em ' + restante + ' segundos.';
  }, 1000);
}
function reenviar() { contarReenvio(30); $('otp').focus(); }

var form = $('form-checkout');
form.addEventListener('submit', function (ev) {
  if (!form.reportValidity()) ev.preventDefault();
});

document.querySelectorAll('input[name=metodo]').forEach(function (r) {
  r.addEventListener('change', metodoMudou);
});
alternarCobranca(document.querySelector('input[name=cobranca_igual]'));
metodoMudou();
totais();
contarReenvio(30);
</script>
