        m.hidden = true;
      }
    });
  });

  var campo = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  document.querySelector('#m0 .btn-prim').addEventListener('click', function () {
    var valido = campo.checkValidity();
    erro.hidden = valido;
    campo.setAttribute('aria-invalid', String(!valido));
    if (!valido) { campo.focus(); }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') { return; }
    document.querySelectorAll('.modal:not([hidden])').forEach(function (m) { m.hidden = true; });
    definirAjuda(false);
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
