document.getElementById('btn-dispensar').addEventListener('click', function () { document.getElementById('banner-sucesso').hidden = true; });
(function () {
  var gatilho = null;
  function fechar(f) { f.hidden = true; if (gatilho) { gatilho.focus(); gatilho = null; } }

  document.querySelectorAll('#acessos table button').forEach(function (b) {
    var item = b.closest('tr').querySelector('th').textContent;
    b.setAttribute('aria-label', b.textContent.trim() + ' de ' + item);
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      gatilho = b;
      var f = document.getElementById(b.getAttribute('data-abrir'));
      if (f.id === 'fundo-revogar') {
        document.getElementById('dlg-revogar-d').textContent = 'O acesso de ' + b.closest('tr').querySelector('th').textContent + ' será revogado imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      f.querySelector('[autofocus]').focus();
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { if (gatilho) { gatilho.focus(); gatilho = null; } });
  });

  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(f); });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key === 'Tab') {
      var els = aberto.querySelectorAll('button');
      var primeiro = els[0], ultimo = els[els.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var email = document.getElementById('email'), tel = document.getElementById('telefone');
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
    var telOk = /^\(\d{2}\) \d{5}-\d{4}$/.test(tel.value.trim());
    document.getElementById('erro-email').hidden = emailOk;
    document.getElementById('erro-telefone').hidden = telOk;
    email.setAttribute('aria-invalid', String(!emailOk));
    tel.setAttribute('aria-invalid', String(!telOk));
    var invalido = !emailOk ? email : (!telOk ? tel : null);
    if (invalido) { invalido.focus(); return; }
    // TODO: enviar ao servidor e anunciar o resultado em #live somente após confirmação.
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    // TODO: enviar ao servidor; exibir #banner-sucesso somente após confirmação.
  });
})();
