function abrirDialogo(n){
  ultimoFoco=document.activeElement;
  var rem=document.getElementById('btn-remover');
  rem.dataset.item=n;
  document.getElementById('dlg-p').textContent=n+' será removido do pedido.';
  document.getElementById('veu').hidden=false;
  fundo(true);
  rem.focus();
}
function fecharDialogo(){
  document.getElementById('veu').hidden=true;
  fundo(false);
  if(ultimoFoco&&document.body.contains(ultimoFoco)){ultimoFoco.focus();}
  else{var t=document.getElementById('t-itens');t.tabIndex=-1;t.focus();}
}
document.addEventListener('keydown',function(e){
  var v=document.getElementById('veu');
  if(v.hidden)return;
  if(e.key==='Escape'){fecharDialogo();return;}
  if(e.key==='Tab'){
    var f=v.querySelectorAll('button'),a=f[0],b=f[f.length-1];
    if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}
    else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}
  }
});
document.getElementById('btn-cancelar').addEventListener('click',fecharDialogo);
document.getElementById('btn-remover').addEventListener('click',function(){
