<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var ultimoFoco = null;

  function abrirGaveta() {
    gaveta.hidden = false;
    btnAjuda.setAttribute('aria-expanded', 'true');
    gaveta.querySelector('a').focus();
  }
  function fecharGaveta() {
    if (gaveta.hidden) return;
    gaveta.hidden = true;
    btnAjuda.setAttribute('aria-expanded', 'false');
    btnAjuda.focus();
  }
  btnAjuda.addEventListener('click', function () {
    if (gaveta.hidden) abrirGaveta(); else fecharGaveta();
  });
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click', fecharGaveta);

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var primeiro = m.querySelector('input, button');
    if (primeiro) primeiro.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x, [data-fechar]')) fecharModal(m);
    });
  });
  document.querySelectorAll('[data-abrir-modal]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abrir-modal')));
    });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (aberto) fecharModal(aberto);
      else if (!gaveta.hidden) fecharGaveta();
      return;
    }
    if (e.key === 'Tab' && aberto) {
      var f = aberto.querySelectorAll('input, button, a[href]');
      if (!f.length) return;
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault(); ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault(); primeiro.focus();
      }
    }
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () {
      b.closest('.banner').remove();
      document.getElementById('conteudo').focus();
    });
  });
})();
</script>
</body>
