<script>
var TITULO = document.title;
var form = document.getElementById('form-checkout');
var veu = document.getElementById('veu');
var cartao = document.getElementById('cartao');
var otpBloco = document.getElementById('bloco-otp');
var mesmo = document.getElementById('mesmo-endereco');
var cobranca = document.getElementById('bloco-cobranca');
var gatilhoDialogo = null;
var SUBTOTAL = 7987.90;
var FRETES = {
  eco: { valor: 20.90, nome: 'Econômica', prazo: 'Econômica, 6 a 8 dias úteis' },
  pad: { valor: 34.40, nome: 'Padrão', prazo: 'Padrão, 3 a 5 dias úteis' },
  exp: { valor: 61.90, nome: 'Expressa', prazo: 'Expressa, 1 a 2 dias úteis' }
};

function moeda(v){
  var p = v.toFixed(2).split('.');
  return 'R$ ' + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + p[1];
}

function atualizarTotais(){
  var r = form.querySelector('input[name="frete"]:checked');
  if (!r) return;
  var f = FRETES[r.value];
  var total = SUBTOTAL + f.valor;
  document.getElementById('frete-nome').textContent = 'Frete (' + f.nome + ')';
  document.getElementById('frete-valor').textContent = moeda(f.valor);
  document.getElementById('total-valor').textContent = moeda(total);
  document.getElementById('btn-valor').textContent = moeda(total);
  document.getElementById('revisao-frete').textContent = f.prazo + ' (' + moeda(f.valor) + ')';
}

function atualizarMetodo(){
  var m = form.querySelector('input[name="metodo"]:checked');
  var ehCartao = !m || m.value === 'cartao';
  cartao.hidden = !ehCartao;
  cartao.disabled = !ehCartao;
  otpBloco.hidden = !ehCartao;
  otpBloco.querySelectorAll('input').forEach(function(i){ i.disabled = !ehCartao; });
}

function atualizarCobranca(){
  cobranca.hidden = mesmo.checked;
  cobranca.querySelectorAll('input,select').forEach(function(c){ c.disabled = mesmo.checked; });
}

function buscarCep(){
  document.getElementById('cep-status').textContent = 'Endereço localizado.';
}

function aplicarCupom(){
  var i = document.getElementById('cupom');
  var e = document.getElementById('cupom-erro');
  if (!i.value.trim()) {
    e.textContent = 'Digite o código do cupom.';
  } else {
    e.textContent = 'Este cupom expirou em 31/10. Confira o código ou siga sem cupom.';
    i.setAttribute('aria-invalid', 'true');
  }
  e.hidden = false;
  i.focus();
}

function reenviar(){
  document.getElementById('reenviar-status').textContent = 'Novo código solicitado. Aguarde a mensagem por SMS.';
  document.querySelector('#bloco-otp input').focus();
}

function abrirDialogo(n){
  gatilhoDialogo = (window.event && window.event.currentTarget) || document.activeElement;
  document.getElementById('dlg-p').textContent = 'Confirme a remoção de "' + n + '" do pedido.';
  veu.hidden = false;
  veu.querySelector('.btn-sec').focus();
}

function fecharDialogo(){
  veu.hidden = true;
  if (gatilhoDialogo) gatilhoDialogo.focus();
}

document.addEventListener('keydown', function(e){
  if (veu.hidden) return;
  if (e.key === 'Escape') { fecharDialogo(); return; }
  if (e.key === 'Tab') {
    var b = veu.querySelectorAll('button');
    var primeiro = b[0], ultimo = b[b.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});

function nomeCampo(el){
  var l = el.id && document.querySelector('label[for="' + el.id + '"]');
  return l ? l.textContent.trim() : (el.getAttribute('aria-label') || el.name);
}

function mensagemErro(el){
  var nome = nomeCampo(el);
  if (el.validity.valueMissing) return nome + ': preencha este campo.';
  if (el.validity.typeMismatch) return nome + ': informe um e-mail válido, como nome@exemplo.com.br.';
  if (el.validity.patternMismatch) return nome + ': ' + (el.title || 'verifique o formato') + '.';
  return nome + ': verifique o valor informado.';
}

function mostrarErros(box, lista){
  box.textContent = '';
  var h = document.createElement('h2');
  h.textContent = 'Corrija ' + (lista.length > 1 ? lista.length + ' campos' : '1 campo') + ' para continuar';
  var ul = document.createElement('ul');
  lista.forEach(function(el){
    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = '#' + el.id;
    a.textContent = mensagemErro(el);
    li.appendChild(a);
    ul.appendChild(li);
  });
  box.appendChild(h);
  box.appendChild(ul);
  box.hidden = false;
  document.title = 'Erro: ' + TITULO;
  box.focus();
}

function enviar(e){
  e.preventDefault();
  var box = document.getElementById('resumo-erros');
  var invalidos = [];
  form.querySelectorAll('input[required]:not(:disabled), select[required]:not(:disabled)').forEach(function(el){
    if (!el.checkValidity()) invalidos.push(el);
  });
  if (invalidos.length) { mostrarErros(box, invalidos); return; }
  box.hidden = true;
  document.title = TITULO;
  var conf = document.getElementById('confirmacao');
  conf.hidden = false;
  conf.setAttribute('tabindex', '-1');
  conf.focus();
}

var otps = document.querySelectorAll('#bloco-otp .otp input');
otps.forEach(function(inp, i){
  inp.addEventListener('input', function(){
    inp.value = inp.value.replace(/\D/g, '').slice(0, 1);
    if (inp.value && otps[i + 1]) otps[i + 1].focus();
  });
  inp.addEventListener('keydown', function(e){
    if (e.key === 'Backspace' && !inp.value && otps[i - 1]) otps[i - 1].focus();
  });
  inp.addEventListener('paste', function(e){
    var t = (e.clipboardData || window.clipboardData).getData('text').replace(/\D/g, '');
    if (!t) return;
    e.preventDefault();
    for (var k = i; k < otps.length; k++) otps[k].value = t.charAt(k - i);
    otps[Math.min(i + t.length, otps.length - 1)].focus();
  });
});

document.querySelectorAll('td.col-acao button').forEach(function(b){
  b.setAttribute('aria-label', 'Remover ' + b.closest('tr').querySelector('.col-nome').textContent.trim() + ' do pedido');
});

form.querySelectorAll('input[name="frete"]').forEach(function(r){ r.addEventListener('change', atualizarTotais); });
form.querySelectorAll('input[name="metodo"]').forEach(function(r){ r.addEventListener('change', atualizarMetodo); });
mesmo.addEventListener('change', atualizarCobranca);
form.addEventListener('submit', enviar);

atualizarMetodo();
atualizarCobranca();
atualizarTotais();
</script>
@@ FIM
