<script>
function valor(celula, tipo){
  var t = (celula.querySelector('.nm-t > span') || celula).textContent.trim();
  if (tipo === 'numero') return parseFloat(t);
  if (tipo === 'moeda') return parseFloat(t.replace(/[R$\s.]/g, '').replace(',', '.'));
  if (tipo === 'data') { var p = t.split('/'); return p[2] + p[1] + p[0]; }
  return t.toLowerCase();
}
function aplicarOrdem(th, asc){
  var tabela = th.closest('table'), idx = th.cellIndex, tipo = th.dataset.tipo;
  tabela.querySelectorAll('thead th[data-tipo]').forEach(function (x) {
    x.removeAttribute('aria-sort');
    x.querySelector('.seta').textContent = '⇅';
  });
  th.setAttribute('aria-sort', asc ? 'ascending' : 'descending');
  th.querySelector('.seta').textContent = asc ? '▲' : '▼';
  tabela.querySelectorAll('tbody').forEach(function (tb) {
    var linhas = Array.from(tb.rows).filter(function (r) { return !r.classList.contains('grupo'); });
    linhas.sort(function (a, b) {
      var va = valor(a.cells[idx], tipo), vb = valor(b.cells[idx], tipo);
      var r = va < vb ? -1 : (va > vb ? 1 : 0);
      return asc ? r : -r;
    });
    linhas.forEach(function (r) { tb.appendChild(r); });
  });
}
document.querySelectorAll('.tabela thead .ord').forEach(function (b) {
  b.addEventListener('click', function () {
    var th = b.closest('th');
    aplicarOrdem(th, th.getAttribute('aria-sort') !== 'ascending');
  });
});
var inicial = document.querySelector('.tabela thead th[aria-sort]');
if (inicial) aplicarOrdem(inicial, inicial.getAttribute('aria-sort') === 'ascending');

document.querySelectorAll('.ac-b').forEach(function (b) {
  b.addEventListener('click', function () {
    var aberto = b.getAttribute('aria-expanded') === 'true';
    b.setAttribute('aria-expanded', String(!aberto));
    b.closest('.faceta').querySelector('.ac-p').hidden = aberto;
  });
});
document.querySelectorAll('.sw').forEach(function (s) {
  s.addEventListener('click', function () {
    s.setAttribute('aria-checked', String(s.getAttribute('aria-checked') !== 'true'));
  });
});
document.querySelector('.filtros .btn-sec').addEventListener('click', function () {
  document.querySelectorAll('.filtros input').forEach(function (i) { i.checked = false; });
  document.querySelectorAll('.sw').forEach(function (s) { s.setAttribute('aria-checked', 'false'); });
});
</script>
