<script>
(function () {
  var tituloOriginal = document.title;
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var formExcluir = document.getElementById('form-excluir');
  var confirmacao = document.getElementById('conf-excluir');
  var erroExcluir = document.getElementById('erro-excluir');
  var ultimoFoco = null;

  function focaveis(el) {
    return Array.prototype.slice.call(el.querySelectorAll('a[href],button:not([disabled]),input:not([disabled])'))
      .filter(function (n) { return !n.closest('[hidden]'); });
  }
  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var f = focaveis(m);
    if (f.length) f[0].focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
    ultimoFoco = null;
  }
  function fecharGaveta() {
    gaveta.hidden = true;
    btnAjuda.setAttribute('aria-expanded', 'false');
    btnAjuda.focus();
  }

  btnAjuda.addEventListener('click', function () {
    if (gaveta.hidden) {
      gaveta.hidden = false;
      btnAjuda.setAttribute('aria-expanded', 'true');
      var f = focaveis(gaveta);
      if (f.length) f[0].focus();
    } else {
      fecharGaveta();
    }
  });

  document.addEventListener('click', function (e) {
    var abre = e.target.closest('[data-abre]');
    if (abre) { abrirModal(document.getElementById(abre.getAttribute('data-abre'))); return; }
    var fecha = e.target.closest('[data-fechar], .modal-x');
    if (fecha && fecha.closest('.modal')) { fecharModal(fecha.closest('.modal')); }
  });

  document.addEventListener('keydown', function (e) {
    var modal = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (modal) fecharModal(modal);
      else if (!gaveta.hidden) fecharGaveta();
      return;
    }
    if (e.key === 'Tab' && modal) {
      var f = focaveis(modal);
      if (!f.length) return;
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () {
      b.closest('.banner').remove();
      document.getElementById('conteudo').focus();
    });
  });

  if (formExcluir) {
    formExcluir.addEventListener('submit', function (e) {
      if (confirmacao.value.trim() !== 'EXCLUIR') {
        e.preventDefault();
        confirmacao.setAttribute('aria-invalid', 'true');
        erroExcluir.hidden = false;
        document.title = 'Erro: ' + tituloOriginal;
        confirmacao.focus();
      }
    });
  }
})();
</script>
