<script>
(function(){
  var retorno = null;
  function abrir(m){
    retorno = document.activeElement;
    m.hidden = false;
    var f = m.querySelector('input, button');
    if (f) f.focus();
  }
  function fechar(m){
    m.hidden = true;
    if (retorno) retorno.focus();
  }
  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click', function(){
      abrir(document.getElementById(b.getAttribute('aria-controls')));
    });
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click', function(e){
      if (e.target === m || e.target.closest('.modal-x, [data-fechar]')) fechar(m);
    });
  });
  document.addEventListener('keydown', function(e){
    if (e.key !== 'Escape') return;
    document.querySelectorAll('.modal:not([hidden])').forEach(function(m){ fechar(m); });
  });
  var ajuda = document.querySelector('[aria-controls="gaveta"]');
  var gaveta = document.getElementById('gaveta');
  ajuda.addEventListener('click', function(){
    gaveta.hidden = !gaveta.hidden;
    ajuda.setAttribute('aria-expanded', String(!gaveta.hidden));
  });
  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click', function(){ b.closest('.banner').remove(); });
  });
  var conv = document.getElementById('conv-email');
  document.querySelector('#m0 .btn-prim').addEventListener('click', function(){
    var invalido = !conv.checkValidity();
    conv.setAttribute('aria-invalid', String(invalido));
    document.getElementById('conv-erro').hidden = !invalido;
    if (invalido) conv.focus();
  });
})();
</script>
</body>
