<script>
(function(){
  const form=document.querySelector('form');
  const resumo=document.getElementById('resumo-erros');
  const lista=document.getElementById('lista-erros');
  const mesmo=document.getElementById('mesmo');
  const corBloco=form.querySelectorAll('.bloco-end')[1];
  const pares=[['cep-res','cep-cor'],['rua-res','rua-cor'],['num-res','num-cor'],['comp-res','comp-cor'],['bairro-res','bairro-cor'],['cidade-res','cidade-cor'],['uf-res','uf-cor']];
  const tel=document.getElementById('tel');
  const arq=document.getElementById('arquivo');
  const LIMITE=10*1024*1024;

  function fmtTel(v){
    const d=v.replace(/\D/g,'').slice(0,11);
    if(d.length<=2) return d;
    if(d.length<=6) return '('+d.slice(0,2)+') '+d.slice(2);
    if(d.length<=10) return '('+d.slice(0,2)+') '+d.slice(2,6)+'-'+d.slice(6);
    return '('+d.slice(0,2)+') '+d.slice(2,7)+'-'+d.slice(7);
  }
  function cpfValido(s){
    s=s.replace(/\D/g,'');
    if(s.length!==11||/^(\d)\1{10}$/.test(s)) return false;
    for(let t=9;t<11;t++){
      let soma=0;
      for(let i=0;i<t;i++) soma+=Number(s[i])*(t+1-i);
      if(((soma*10)%11)%10!==Number(s[t])) return false;
    }
    return true;
  }
  function valido(c){
    const v=c.value.trim(), n=Number(v);
    if(c.type==='checkbox') return c.checked;
    if(c.id==='cpf') return cpfValido(v);
    if(c.id==='cep-res') return v.replace(/\D/g,'').length===8;
    if(c.id==='dia') return /^\d{1,2}$/.test(v)&&n>=1&&n<=31;
    if(c.id==='mes') return /^\d{1,2}$/.test(v)&&n>=1&&n<=12;
    if(c.id==='ano') return /^\d{4}$/.test(v);
    if(c.type==='email') return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
    return v!=='';
  }
  function msgDe(c){
    if(c.type==='checkbox') return 'Marque esta opção para continuar.';
    if(c.type==='email') return 'Informe um e-mail válido, como nome@dominio.com.br.';
    if(c.id==='cpf') return 'Confira o CPF: são 11 dígitos válidos.';
    if(c.id==='cep-res') return 'Informe o CEP com 8 dígitos.';
    if(c.id==='ano') return 'Informe o ano de nascimento com 4 dígitos.';
    if(c.id==='dia') return 'Informe um dia entre 1 e 31.';
    if(c.id==='mes') return 'Informe um mês entre 1 e 12.';
    return 'Preencha este campo.';
  }
  function marcar(c,ok){
    const host=c.closest('.campo');
    let p=document.getElementById('e-'+c.id);
    if(ok){
      if(p) p.hidden=true;
      if(host) host.classList.remove('tem-erro');
      c.setAttribute('aria-invalid','false');
      return;
    }
    if(!p){
      p=document.createElement('p');
      p.className='erro'; p.id='e-'+c.id;
      if(host) host.appendChild(p); else c.closest('label').after(p);
      c.setAttribute('aria-describedby',((c.getAttribute('aria-describedby')||'')+' '+p.id).trim());
    }
    p.textContent=msgDe(c); p.hidden=false;
    if(host) host.classList.add('tem-erro');
    c.setAttribute('aria-invalid','true');
  }
  function sincronizar(){
    corBloco.hidden=mesmo.checked;
    if(mesmo.checked) pares.forEach(([a,b])=>{ document.getElementById(b).value=document.getElementById(a).value; });
  }

  tel.value=fmtTel(tel.value);
  tel.addEventListener('blur',()=>{ tel.value=fmtTel(tel.value); });
  mesmo.addEventListener('change',sincronizar);

  form.addEventListener('submit',function(e){
    const falhas=[...form.querySelectorAll('[required]')].filter(c=>{ const ok=valido(c); marcar(c,ok); return !ok; });
    if(!falhas.length){ resumo.hidden=true; return; }
    e.preventDefault();
    lista.innerHTML='';
    falhas.forEach(c=>{
      const li=document.createElement('li'), a=document.createElement('a');
      a.href='#'+c.id;
      a.textContent=c.labels[0].textContent.replace('*','').trim();
      li.appendChild(a); lista.appendChild(li);
    });
    resumo.querySelector('.resumo-titulo').textContent=falhas.length===1?'Há 1 problema nesta etapa':'Há '+falhas.length+' problemas nesta etapa';
    resumo.hidden=false;
    resumo.focus();
  });

  form.addEventListener('input',function(e){
    const c=e.target;
    if(c.getAttribute('aria-invalid')==='true') marcar(c,valido(c));
    if(mesmo.checked) sincronizar();
  });

  const abas=[...document.querySelectorAll('[role=tab]')];
  function ativar(i,focar){
    abas.forEach((a,j)=>{
      const sel=j===i;
      a.setAttribute('aria-selected',String(sel));
      a.tabIndex=sel?0:-1;
      a.classList.toggle('aba-ativa',sel);
      document.getElementById(a.getAttribute('aria-controls')).hidden=!sel;
    });
    if(focar) abas[i].focus();
  }
  abas.forEach((a,i)=>{
    a.addEventListener('click',()=>ativar(i,false));
    a.addEventListener('keydown',e=>{
      if(e.key!=='ArrowRight'&&e.key!=='ArrowLeft') return;
      e.preventDefault();
      ativar((i+(e.key==='ArrowRight'?1:abas.length-1))%abas.length,true);
    });
  });
  ativar(0,false);

  arq.addEventListener('change',function(){
    const f=arq.files[0], d=document.getElementById('d-arquivo');
    const grande=!!f&&f.size>LIMITE;
    d.className=grande?'erro':'dica';
    d.textContent=grande?'Arquivo maior que 10 MB. Escolha outro arquivo.':'Tamanho máximo de 10 MB.';
    if(grande) arq.value='';
  });
})();
</script>
</body>
