/* Validação do perfil ao tentar salvar */
var formPerfil = document.getElementById('form-perfil');
var resumo = document.getElementById('resumo-perfil');
var listaErros = document.getElementById('lista-perfil');
var msgErros = document.getElementById('msg-perfil');

function marcar(campo, idErro, invalido) {
  if (!campo.dataset.base) campo.dataset.base = campo.getAttribute('aria-describedby') || '';
  campo.setAttribute('aria-describedby', invalido ? (campo.dataset.base + ' ' + idErro).trim() : campo.dataset.base);
  campo.setAttribute('aria-invalid', invalido ? 'true' : 'false');
  campo.closest('.campo').classList.toggle('com-erro', invalido);
  document.getElementById(idErro).hidden = !invalido;
  return invalido;
}

formPerfil.addEventListener('submit', function (e) {
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var invalidos = [];
  if (marcar(email, 'erro-email', !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim()))) invalidos.push(email);
  if (marcar(tel, 'erro-telefone', tel.value.replace(/\D/g, '').length !== 11)) invalidos.push(tel);

  if (!invalidos.length) { resumo.hidden = true; return; }

  e.preventDefault();
  listaErros.textContent = '';
  invalidos.forEach(function (campo) {
    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = '#' + campo.id;
    a.textContent = campo.labels[0].textContent + ': ' + campo.closest('.campo').querySelector('.erro').textContent;
    li.appendChild(a);
    listaErros.appendChild(li);
  });
  msgErros.textContent = invalidos.length === 1
    ? 'Corrija 1 campo antes de salvar.'
    : 'Corrija ' + invalidos.length + ' campos antes de salvar.';
  resumo.hidden = false;
  invalidos[0].focus();
});

formPerfil.addEventListener('reset', function () {
  resumo.hidden = true;
  formPerfil.querySelectorAll('.campo').forEach(function (c) { c.classList.remove('com-erro'); });
  formPerfil.querySelectorAll('.erro').forEach(function (p) { p.hidden = true; });
  formPerfil.querySelectorAll('[aria-invalid]').forEach(function (i) { i.setAttribute('aria-invalid', 'false'); });
  setTimeout(atualizarContador, 0);
});
