var ultimoFoco = null;
var live = document.getElementById('live');
function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }
function abrirModal(id) {
  var f = document.getElementById(id);
  ultimoFoco = document.activeElement;
  f.hidden = false;
  var alvo = f.querySelector('input') || f.querySelectorAll('button')[1];
  alvo.focus();
}
function fecharModal(f) {
  f.hidden = true;
  if (ultimoFoco) ultimoFoco.focus();
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir')); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.querySelectorAll('[data-modal]').forEach(function (f) {
  f.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { fecharModal(f); return; }
    if (e.key !== 'Tab') return;
    var els = f.querySelectorAll('input, button');
    var primeiro = els[0], ultimo = els[els.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });
});
document.getElementById('btn-confirmar-excluir').addEventListener('click', function () {
