  erro.querySelector('.txt-erro').textContent = 'Digite EXCLUIR exatamente como aparece para confirmar.';
  if (!ok) { input.focus(); return; }
  fecharModal(document.getElementById('fundo-excluir'));
  anunciar('Exclusão agendada. Seus dados serão apagados em 30 dias.');
});
