<script>
(function () {
  var layout = document.querySelector('.layout');
  var topo = document.getElementById('topo');
  var rodape = document.querySelector('.rodape');
  var live = document.getElementById('live');
  var gatilho = null;
  var linhaAtual = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function focarTitulo(id) {
    var el = document.getElementById(id);
    el.setAttribute('tabindex', '-1');
    el.focus();
  }

  function atualizarContagem() {
    var n = document.querySelector('#acessos table tbody').rows.length;
    document.getElementById('contagem-acessos').textContent =
      n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
  }

  function estaAberto() {
    return document.querySelector('[data-modal]:not([hidden])');
  }

  function abrirModal(modal, origem) {
    gatilho = origem;
    modal.hidden = false;
    [layout, topo, rodape].forEach(function (el) { if (el) el.inert = true; });
    modal.querySelector('.btn:not(.perigo)').focus();
  }

  function fecharModal(modal) {
    modal.hidden = true;
    [layout, topo, rodape].forEach(function (el) { if (el) el.inert = false; });
    if (gatilho && document.body.contains(gatilho)) {
      gatilho.focus();
    } else {
      focarTitulo('h-acessos');
    }
    gatilho = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var linha = b.closest('tr');
    var app = linha ? linha.querySelector('th').textContent.trim() : '';
    if (app) b.setAttribute('aria-label', 'Revogar acesso de ' + app);
    b.addEventListener('click', function () {
      if (app) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
      }
      linhaAtual = linha;
      abrirModal(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });

  document.querySelectorAll('[data-modal]').forEach(function (modal) {
    modal.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fecharModal(modal); });
    });
    modal.querySelector('.btn.perigo').addEventListener('click', function () {
      if (modal.id === 'fundo-revogar' && linhaAtual) {
        var nome = linhaAtual.querySelector('th').textContent.trim();
        linhaAtual.remove();
        atualizarContagem();
        anunciar('Acesso de ' + nome + ' revogado.');
      } else if (modal.id === 'fundo-excluir') {
        anunciar('Solicitação de exclusão registrada. Sua conta será apagada em 30 dias.');
      }
      linhaAtual = null;
      fecharModal(modal);
    });
  });

  document.addEventListener('keydown', function (e) {
    var modal = estaAberto();
    if (!modal) return;
    if (e.key === 'Escape') { fecharModal(modal); return; }
    if (e.key !== 'Tab') return;
    var botoes = modal.querySelectorAll('button');
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) {
      e.preventDefault(); ultimo.focus();
    } else if (!e.shiftKey && document.activeElement === ultimo) {
      e.preventDefault(); primeiro.focus();
    }
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var texto = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    var s = document.createElement('span');
    s.textContent = texto;
    p.parentNode.appendChild(s);
  });

  document.querySelectorAll('button').forEach(function (b) {
    if (b.textContent.trim() !== 'Encerrar sessão') return;
    var linha = b.closest('tr');
    var nome = linha.querySelector('th').textContent.trim();
    b.setAttribute('aria-label', 'Encerrar sessão de ' + nome);
    b.addEventListener('click', function () {
      linha.remove();
      anunciar('Sessão de ' + nome + ' encerrada.');
      focarTitulo('h-acessos');
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    focarTitulo('h-pref');
  });

  function marcarCampo(input, valido) {
    var base = 'dica-' + input.id;
    var erro = document.getElementById('erro-' + input.id);
    input.setAttribute('aria-invalid', String(!valido));
    input.closest('.campo').classList.toggle('campo-erro', !valido);
    if (erro) erro.hidden = valido;
    input.setAttribute('aria-describedby', valido ? base : base + ' erro-' + input.id);
  }

  var email = document.getElementById('email');
  var telefone = document.getElementById('telefone');

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim());
    var digitos = telefone.value.replace(/\D/g, '');
    var telOk = digitos.length >= 10 && digitos.length <= 11;
    marcarCampo(email, emailOk);
    marcarCampo(telefone, telOk);
    var primeiroErro = !emailOk ? email : (!telOk ? telefone : null);
    if (primeiroErro) {
      primeiroErro.focus();
      anunciar('Corrija os campos destacados antes de salvar.');
      return;
    }
    anunciar('Perfil salvo.');
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    anunciar('Preferências de notificação salvas.');
  });
})();
</script>
