<script>
(function () {
  var ultimoFoco = null;
  var gaveta = document.getElementById('gaveta');
  var botaoAjuda = document.querySelector('[aria-controls="gaveta"]');
  var emailConvite = document.getElementById('conv-email');
  var erroConvite = document.getElementById('conv-erro');

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var alvo = m.querySelector('input') || m.querySelector('.btn-prim') || m.querySelector('button');
    if (alvo) alvo.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  function abrirGaveta() {
    gaveta.classList.add('aberta');
    botaoAjuda.setAttribute('aria-expanded', 'true');
    gaveta.querySelector('h2').focus();
  }
  function fecharGaveta() {
    if (!gaveta.classList.contains('aberta')) return;
    gaveta.classList.remove('aberta');
    botaoAjuda.setAttribute('aria-expanded', 'false');
    botaoAjuda.focus();
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('aria-controls')));
    });
  });
  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('[data-fechar]')) fecharModal(m);
    });
  });
  document.querySelectorAll('[data-dispensar]').forEach(function (b) {
    b.addEventListener('click', function () { b.closest('.banner').remove(); });
  });
  botaoAjuda.addEventListener('click', function () {
    if (gaveta.classList.contains('aberta')) fecharGaveta(); else abrirGaveta();
  });
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click', fecharGaveta);
  document.querySelector('[data-enviar-convite]').addEventListener('click', function () {
    var valido = emailConvite.checkValidity();
    emailConvite.setAttribute('aria-invalid', String(!valido));
    erroConvite.hidden = valido;
    if (!valido) { emailConvite.focus(); return; }
    /* chamar o endpoint de convite aqui */
  });
  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (aberto) fecharModal(aberto); else fecharGaveta();
      return;
    }
    if (e.key === 'Tab' && aberto) {
      var f = aberto.querySelectorAll('input,button');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
