(function () {
  var TITULO_PADRAO = 'Configurações da conta - Mercado Bom Preço';
  var opener = null;

  function nomeDaLinha(b) {
    return b.closest('tr').querySelector('th').textContent.trim();
  }

  document.querySelectorAll('#acessos td:last-child button').forEach(function (b) {
    var s = document.createElement('span');
    s.className = 'sr-only';
    s.textContent = ' de ' + nomeDaLinha(b);
    b.appendChild(s);
  });

  function abrir(fundo, origem) {
    opener = origem;
    fundo.hidden = false;
    fundo.querySelector('.modal .btn:not(.perigo)').focus();
  }

  function fechar(fundo) {
    fundo.hidden = true;
    if (opener) { opener.focus(); opener = null; }
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = document.getElementById(b.getAttribute('data-abrir'));
      if (fundo.id === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nomeDaLinha(b) + '?';
      }
      abrir(fundo, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key !== 'Tab') return;
    var botoes = aberto.querySelectorAll('button');
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.getElementById('h-pref').focus();
  });

  var regras = [
    {
      campo: 'email',
      erro: 'erro-email',
      valido: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
      msg: 'Digite um e-mail completo, como nome@empresa.com.br.'
    },
    {
      campo: 'telefone',
      erro: 'erro-telefone',
      valido: function (v) { var d = v.replace(/\D/g, ''); return v.trim() === '' || d.length === 10 || d.length === 11; },
      msg: 'Digite o DDD e o número completo, com 10 ou 11 números. Exemplo: (11) 91234-5678.'
    }
  ];

  var formPerfil = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var tituloErros = document.getElementById('titulo-erros');

  formPerfil.addEventListener('submit', function (e) {
    var falhas = [];
    regras.forEach(function (r) {
      var input = document.getElementById(r.campo);
      var erroEl = document.getElementById(r.erro);
      var ok = r.valido(input.value);
      input.setAttribute('aria-invalid', ok ? 'false' : 'true');
      input.closest('.campo').classList.toggle('campo-erro', !ok);
      erroEl.textContent = ok ? '' : 'Erro: ' + r.msg;
      erroEl.hidden = ok;
      if (!ok) falhas.push(r);
    });
    if (!falhas.length) {
      resumo.hidden = true;
      lista.innerHTML = '';
      document.title = TITULO_PADRAO;
      return;
    }
    e.preventDefault();
    lista.innerHTML = '';
    falhas.forEach(function (r) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + r.campo;
      a.textContent = document.querySelector('label[for="' + r.campo + '"]').textContent + ': ' + r.msg;
      li.appendChild(a);
      lista.appendChild(li);
    });
    resumo.hidden = false;
    document.title = 'Erro: ' + TITULO_PADRAO;
    tituloErros.focus();
  });
})();
@@ FIM

