(function () {
  var live = document.getElementById('live');
  var tituloBase = document.title;
  var ultimoGatilho = null;

  function anunciar(t) {
    live.textContent = '';
    setTimeout(function () { live.textContent = t; }, 50);
  }

  ['h-pref', 'contagem-acessos', 'resumo-erros', 'dlg-excluir', 'dlg-revogar'].forEach(function (id) {
    document.getElementById(id).tabIndex = -1;
  });

  document.querySelectorAll('table').forEach(function (tab) {
    tab.querySelectorAll('tbody tr').forEach(function (tr) {
      var nome = tr.querySelector('th[scope="row"]');
      var botao = tr.querySelector('button');
      if (nome && botao) {
        botao.setAttribute('aria-label', botao.textContent.trim() + ': ' + nome.textContent.trim());
      }
    });
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var t = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(document.createTextNode(' ' + t));
  });

  function abrir(id, gatilho) {
    var m = document.getElementById(id);
    ultimoGatilho = gatilho;
    if (id === 'fundo-revogar' && gatilho.closest('tr')) {
      var app = gatilho.closest('tr').querySelector('th').textContent.trim();
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
    }
    var c = document.getElementById('confirma-excluir');
    if (c) {
      c.value = '';
      c.removeAttribute('aria-invalid');
      document.getElementById('erro-confirma').hidden = true;
    }
    m.hidden = false;
    m.querySelector('.modal').focus();
  }

  function fechar(m) {
    m.hidden = true;
    var alvo = ultimoGatilho && ultimoGatilho.isConnected ? ultimoGatilho : document.getElementById('contagem-acessos');
    alvo.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    var m = document.querySelector('[data-modal]:not([hidden])');
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var f = m.querySelectorAll('button, input, a[href]');
    var primeiro = f[0];
    var ultimo = f[f.length - 1];
    var atual = document.activeElement;
    if (e.shiftKey && (atual === primeiro || atual === m.querySelector('.modal'))) {
      e.preventDefault();
      ultimo.focus();
    } else if (!e.shiftKey && atual === ultimo) {
      e.preventDefault();
      primeiro.focus();
    }
  });

  document.querySelector('#fundo-revogar .btn.perigo').addEventListener('click', function () {
    var app = ultimoGatilho.closest('tr').querySelector('th').textContent.trim();
    ultimoGatilho.closest('td').innerHTML = '<span class="chip">Revogado</span>';
    fechar(document.getElementById('fundo-revogar'));
    anunciar('Acesso de ' + app + ' revogado.');
  });

  document.querySelector('#fundo-excluir .btn.perigo').addEventListener('click', function () {
    var c = document.getElementById('confirma-excluir');
    if (c.value.trim() !== 'EXCLUIR') {
      c.setAttribute('aria-invalid', 'true');
      document.getElementById('erro-confirma').hidden = false;
      c.focus();
      return;
    }
    fechar(document.getElementById('fundo-excluir'));
    anunciar('Solicitação de exclusão registrada. A conta será apagada em 30 dias.');
  });

  document.querySelectorAll('#acessos button.pequeno:not([data-abrir])').forEach(function (b) {
    b.addEventListener('click', function () {
      var app = b.closest('tr').querySelector('th').textContent.trim();
      b.closest('td').innerHTML = '<span class="chip">Encerrada</span>';
      anunciar('Sessão de ' + app + ' encerrada.');
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.getElementById('h-pref').focus();
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var d = new Date();
    var hora = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
    document.getElementById('hora-salva').textContent = hora;
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas às ' + hora + '.');
  });

  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var regras = [
    { id: 'nome', ok: function (v) { return v.trim().length >= 3; }, msg: 'informe seu nome completo.' },
    { id: 'email', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()); }, msg: 'informe um e-mail válido, como nome@empresa.com.br.' },
    { id: 'telefone', ok: function (v) { return /^\(\d{2}\) 9?\d{4}-\d{4}$/.test(v.trim()); }, msg: 'use o formato (11) 91234-5678.' }
  ];

  function marcar(id, msg) {
    var el = document.getElementById(id);
    var erro = document.getElementById('erro-' + id);
    var campo = el.closest('.campo');
    erro.textContent = '';
    if (msg) {
      var pre = document.createElement('span');
      pre.className = 'sr-only';
      pre.textContent = 'Erro: ';
      erro.appendChild(pre);
      erro.appendChild(document.createTextNode(msg));
      erro.hidden = false;
      el.setAttribute('aria-invalid', 'true');
      campo.classList.add('campo-erro');
    } else {
      erro.hidden = true;
      el.removeAttribute('aria-invalid');
      campo.classList.remove('campo-erro');
    }
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var erros = [];
    regras.forEach(function (r) {
      var ok = r.ok(document.getElementById(r.id).value);
      marcar(r.id, ok ? '' : r.msg);
      if (!ok) erros.push(r);
    });
    lista.textContent = '';
    if (erros.length) {
      erros.forEach(function (r) {
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + r.id;
        a.textContent = document.querySelector('label[for="' + r.id + '"]').textContent + ': ' + r.msg;
        a.addEventListener('click', function (ev) {
          ev.preventDefault();
          document.getElementById(r.id).focus();
        });
        li.appendChild(a);
        lista.appendChild(li);
      });
      resumo.hidden = false;
      document.title = 'Erro: ' + tituloBase;
      resumo.focus();
      return;
    }
    resumo.hidden = true;
    document.title = tituloBase;
    anunciar('Perfil salvo.');
  });

  form.addEventListener('reset', function () {
    setTimeout(function () {
      resumo.hidden = true;
      document.title = tituloBase;
      regras.forEach(function (r) { marcar(r.id, ''); });
    }, 0);
  });
})();
@@ FIM
