(function () {
  var gatilhoAtual = null;
  var modalAtual = null;

  function botoesDo(modal) {
    return modal.querySelectorAll('button:not([disabled])');
  }
  function abrirModal(modal, gatilho) {
    gatilhoAtual = gatilho;
    modalAtual = modal;
    modal.hidden = false;
    var botoes = botoesDo(modal);
    botoes[botoes.length - 1].focus();
  }
  function fecharModal() {
    if (!modalAtual) return;
    modalAtual.hidden = true;
    modalAtual = null;
    if (gatilhoAtual) gatilhoAtual.focus();
    gatilhoAtual = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fecharModal);
  });
  document.addEventListener('keydown', function (e) {
    if (!modalAtual) return;
    if (e.key === 'Escape') { e.preventDefault(); fecharModal(); return; }
    if (e.key !== 'Tab') return;
    var botoes = botoesDo(modalAtual);
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  var formPerfil = document.getElementById('form-perfil');
  formPerfil.addEventListener('submit', function (e) {
    e.preventDefault();
    if (!formPerfil.checkValidity()) {
      document.getElementById('resumo-erros').focus();
      return;
    }
    document.getElementById('live').textContent = 'Perfil salvo.';
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var titulo = document.getElementById('h-pref');
    titulo.setAttribute('tabindex', '-1');
    document.getElementById('banner-sucesso').hidden = true;
    titulo.focus();
  });
})();
@@ FIM

