<script>
(function () {
  var ultimoFoco = null;
  var aberto = null;

  function focaveis(el) {
    return Array.prototype.slice.call(el.querySelectorAll('button:not([disabled]), a[href], input:not([disabled]), select, textarea'));
  }

  function abrir(fundo) {
    var dlg = fundo.querySelector('[role="alertdialog"]');
    ultimoFoco = document.activeElement;
    aberto = fundo;
    fundo.hidden = false;
    var alvo = dlg.querySelector('.btn:not(.perigo)') || focaveis(dlg)[0];
    if (alvo) alvo.focus();
  }

  function fechar() {
    if (!aberto) return;
    aberto.hidden = true;
    aberto = null;
    if (ultimoFoco && document.body.contains(ultimoFoco)) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var linha = b.closest('tr');
    var nome = linha ? linha.querySelector('th') : null;
    if (nome) b.setAttribute('aria-label', b.textContent.trim() + ': ' + nome.textContent.trim());
    b.addEventListener('click', function () {
      abrir(document.getElementById(b.getAttribute('data-abrir')));
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fechar);
  });

  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key === 'Tab') {
      var itens = focaveis(aberto.querySelector('[role="alertdialog"]'));
      var primeiro = itens[0];
      var ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var h = document.getElementById('h-pref');
    document.getElementById('banner-sucesso').hidden = true;
    h.setAttribute('tabindex', '-1');
    h.focus();
  });
})();
</script>
