<script>
(function(){
  var form=document.getElementById('form-checkout');
  var resumo=document.getElementById('resumo-erros');
  var lista=document.getElementById('lista-erros');
  var erroPag=document.getElementById('erro-pagamento');
  var statusPag=document.getElementById('status-pag');
  var btnPagar=document.getElementById('btn-pagar');
  var cartao=document.getElementById('cartao');
  var otp=document.getElementById('bloco-otp');
  var cobranca=document.getElementById('bloco-cobranca');
  var mesmoEnd=document.getElementById('mesmo-endereco');
  var veu=document.getElementById('veu');
  var tituloPagina=document.title;
  var focoAnterior=null;

  function rotulo(c){
    var l=document.querySelector('label[for="'+c.id+'"]');
    return l?l.textContent.trim().toLowerCase():c.name;
  }
  function mensagem(c){
    var r=rotulo(c);
    if(c.validity.valueMissing) return 'Preencha '+r+'.';
    if(c.validity.patternMismatch) return c.title+'.';
    return 'Confira '+r+'.';
  }
  function limpar(){
    form.querySelectorAll('[data-erro]').forEach(function(p){p.parentNode.removeChild(p);});
    form.querySelectorAll('[aria-invalid]').forEach(function(c){
      c.removeAttribute('aria-invalid');
      c.setAttribute('aria-describedby',(c.getAttribute('aria-describedby')||'').split(/\s+/).filter(function(x){return x&&x.slice(-5)!=='-erro';}).join(' '));
    });
  }
  function marcarErro(c){
    var p=document.createElement('p');
    p.id=c.id+'-erro';
    p.className='erro-campo';
    p.setAttribute('data-erro','');
    p.innerHTML='<span class="sr-only">Erro: </span>';
    p.appendChild(document.createTextNode(mensagem(c)));
    var alvo=c.parentNode.classList.contains('com-botao')?c.parentNode:c;
    alvo.insertAdjacentElement('afterend',p);
    c.setAttribute('aria-invalid','true');
    c.setAttribute('aria-describedby',((c.getAttribute('aria-describedby')||'')+' '+p.id).trim());
  }

  form.addEventListener('submit',function(e){
    e.preventDefault();
    limpar();
    var erros=[].filter.call(form.querySelectorAll('input,select'),function(c){
      return c.willValidate&&!c.checkValidity();
    });
    if(erros.length){
      erros.forEach(marcarErro);
      lista.innerHTML='';
      erros.forEach(function(c){
        var li=document.createElement('li');
        var a=document.createElement('a');
        a.href='#'+c.id;
        a.textContent=mensagem(c);
        li.appendChild(a);
        lista.appendChild(li);
      });
      resumo.hidden=false;
      if(erroPag)erroPag.hidden=true;
      document.title='Erro: '+tituloPagina;
      document.getElementById('resumo-titulo').focus();
      return;
    }
    resumo.hidden=true;
    document.title=tituloPagina;
    btnPagar.textContent='Processando pagamento...';
    statusPag.textContent='Processando pagamento, aguarde.';
    form.submit();
  });

  function atualizarPagamento(){
    var m=form.querySelector('input[name="metodo"]:checked');
    var ehCartao=!m||m.value==='cartao';
    cartao.hidden=!ehCartao;
    cartao.disabled=!ehCartao;
    otp.hidden=!ehCartao;
    otp.querySelectorAll('input').forEach(function(c){c.disabled=!ehCartao;});
  }
  function atualizarCobranca(){
    cobranca.hidden=mesmoEnd.checked;
    cobranca.querySelectorAll('input,select').forEach(function(c){c.disabled=mesmoEnd.checked;});
  }
  form.querySelectorAll('input[name="metodo"]').forEach(function(r){r.addEventListener('change',atualizarPagamento);});
  mesmoEnd.addEventListener('change',atualizarCobranca);
  atualizarPagamento();
  atualizarCobranca();

  function abrirDialogo(n){
    focoAnterior=document.activeElement;
    document.getElementById('dlg-t').textContent='Remover "'+n+'" do pedido?';
    veu.hidden=false;
    veu.querySelector('.btn-sec').focus();
  }
  function fecharDialogo(){
    veu.hidden=true;
    if(focoAnterior)focoAnterior.focus();
  }
  function confirmarRemocao(){fecharDialogo();}
  veu.addEventListener('keydown',function(e){if(e.key==='Escape')fecharDialogo();});

  function aplicarCupom(){
    var v=document.getElementById('cupom').value.trim();
    document.getElementById('cupom-status').textContent=v?'Não foi possível validar o cupom agora. Tente novamente.':'Digite o código do cupom.';
  }
  function reenviar(){
    document.getElementById('otp-status').textContent='Novo código enviado para o telefone (50) ****-2580.';
  }

  window.abrirDialogo=abrirDialogo;
  window.fecharDialogo=fecharDialogo;
  window.confirmarRemocao=confirmarRemocao;
  window.aplicarCupom=aplicarCupom;
  window.reenviar=reenviar;
})();
</script>
