var ultimoFoco = null, modalAtivo = null;
function abrirModal(id, origem) {
  ultimoFoco = origem;
  modalAtivo = document.getElementById(id);
  modalAtivo.hidden = false;
  modalAtivo.querySelector('[data-cancelar]').focus();
}
function fecharModal() {
  if (!modalAtivo) return;
  modalAtivo.hidden = true;
  modalAtivo = null;
  if (ultimoFoco) ultimoFoco.focus();
}
document.addEventListener('keydown', function (e) { if (e.key === 'Escape') fecharModal(); });
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  var linha = b.closest('tr');
  var nome = linha ? linha.querySelector('th').textContent : '';
  if (b.getAttribute('data-abrir') === 'fundo-revogar') {
    b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
  }
  b.addEventListener('click', function () {
    if (b.getAttribute('data-abrir') === 'fundo-revogar') {
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nome + '?';
      document.getElementById('dlg-revogar-d').textContent = nome + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    abrirModal(b.getAttribute('data-abrir'), b);
  });
});
document.querySelectorAll('.ponto').forEach(function (p) {
  var t = document.createElement('span');
  t.textContent = p.getAttribute('aria-label');
  p.removeAttribute('aria-label');
  p.setAttribute('aria-hidden', 'true');
  p.insertAdjacentElement('afterend', t);
});
document.querySelectorAll('#acessos tbody button').forEach(function (b) {
  if (b.textContent.trim() === 'Encerrar sessão') {
    b.setAttribute('aria-label', 'Encerrar sessão em ' + b.closest('tr').querySelector('th').textContent);
  }
});
