document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fecharModal); });
function mostrarErro(campo, msg) {
  var id = 'erro-' + campo.id;
  var p = document.getElementById(id);
  if (!p) {
    p = document.createElement('p');
    p.className = 'erro';
    p.id = id;
    campo.closest('.campo').appendChild(p);
  }
  p.textContent = msg;
  campo.setAttribute('aria-invalid', 'true');
  campo.setAttribute('aria-describedby', (campo.getAttribute('aria-describedby') || '').split(' ').filter(function (x) { return x && x !== id; }).concat(id).join(' '));
}
function limparErro(campo) {
  var id = 'erro-' + campo.id;
  var p = document.getElementById(id);
  if (p) p.parentNode.removeChild(p);
  campo.removeAttribute('aria-invalid');
  campo.setAttribute('aria-describedby', (campo.getAttribute('aria-describedby') || '').split(' ').filter(function (x) { return x && x !== id; }).join(' '));
}
document.getElementById('form-perfil').addEventListener('submit', function (e) {
  e.preventDefault();
  var nome = document.getElementById('nome');
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var erros = [];
  [nome, email, tel].forEach(limparErro);
  if (nome.value.trim() === '') erros.push([nome, 'Digite seu nome.']);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim())) erros.push([email, 'Digite um e-mail completo, como nome@colegio.com.br.']);
  if ([10, 11].indexOf(tel.value.replace(/\D/g, '').length) === -1) erros.push([tel, 'Digite o DDD e o número, como (11) 91234-5678.']);
  lista.textContent = '';
  erros.forEach(function (item) {
    mostrarErro(item[0], item[1]);
    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = '#' + item[0].id;
    a.textContent = document.querySelector('label[for="' + item[0].id + '"]').textContent;
    li.appendChild(a);
    li.appendChild(document.createTextNode(': ' + item[1]));
    lista.appendChild(li);
  });
  if (erros.length) {
    resumo.hidden = false;
    resumo.focus();
  } else {
    resumo.hidden = true;
    document.getElementById('live').textContent = 'Perfil salvo.';
  }
});
