@@ DEPOIS
(function () {
  var live = document.getElementById('live');
  var gatilho = null;
  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }
  function abrir(fundo) {
    gatilho = document.activeElement;
    fundo.hidden = false;
    var foco = fundo.querySelector('[data-foco-inicial]') || fundo.querySelector('button');
    foco.focus();
  }
  function fechar(fundo, msg) {
    fundo.hidden = true;
    if (msg) anunciar(msg);
    if (gatilho && document.body.contains(gatilho)) gatilho.focus();
    gatilho = null;
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = document.getElementById(b.getAttribute('data-abrir'));
      var linha = b.closest('tr');
      if (fundo.id === 'fundo-revogar' && linha) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + linha.querySelector('th').textContent.trim() + '?';
      }
      abrir(fundo);
    });
  });
  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.addEventListener('click', function (e) { if (e.target === fundo) fechar(fundo); });
    fundo.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(fundo); return; }
      if (e.key !== 'Tab') return;
      var botoes = fundo.querySelectorAll('button:not([disabled])');
      var primeiro = botoes[0];
      var ultimo = botoes[botoes.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });
@@ FIM

