/* Validação ao enviar o perfil */
var form = document.getElementById('form-perfil');
var email = document.getElementById('email');
var tel = document.getElementById('telefone');
var resumo = document.getElementById('resumo-erros');
var listaErros = document.getElementById('lista-erros');
function marcar(campo, erro, valido) {
  campo.setAttribute('aria-invalid', valido ? 'false' : 'true');
  erro.hidden = valido;
}
form.addEventListener('submit', function (e) {
  e.preventDefault();
  var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
  var telOk = tel.value.replace(/\D/g, '').length >= 10;
  marcar(email, document.getElementById('erro-email'), emailOk);
  marcar(tel, document.getElementById('erro-telefone'), telOk);
  listaErros.textContent = '';
  var falhas = [];
  if (!emailOk) falhas.push({ campo: 'email', texto: 'E-mail inválido.' });
  if (!telOk) falhas.push({ campo: 'telefone', texto: 'Informe um celular com DDD.' });
  if (falhas.length) {
    falhas.forEach(function (f) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + f.campo;
      a.textContent = f.texto;
      li.appendChild(a);
      listaErros.appendChild(li);
    });
    resumo.hidden = false;
    resumo.focus();
    anunciar(falhas.length + (falhas.length === 1 ? ' campo precisa' : ' campos precisam') + ' de correção.');
  } else {
    resumo.hidden = true;
    anunciar('Alterações salvas.');
  }
});

