@@ DEPOIS
(function () {
  var live = document.getElementById('live');
  var ultimoGatilho = null;
  var modalAberto = null;
  function anunciar(msg) { live.textContent = ''; setTimeout(function () { live.textContent = msg; }, 50); }
  function focaveis(m) {
    return Array.prototype.slice.call(m.querySelectorAll('button:not([disabled]), a[href], input, select, textarea')).filter(function (el) { return !el.hidden; });
  }
  function abrir(m, gatilho) {
    ultimoGatilho = gatilho;
    modalAberto = m;
    m.hidden = false;
    var alvo = m.querySelector('.btn:not(.perigo)') || focaveis(m)[0];
    alvo.focus();
  }
  function fechar(m) {
    m.hidden = true;
    modalAberto = null;
    if (ultimoGatilho) ultimoGatilho.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var m = document.getElementById(b.getAttribute('data-abrir'));
      var app = b.getAttribute('data-app');
      if (app) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
        document.getElementById('dlg-revogar-d').textContent = 'O aplicativo ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(m, b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      fechar(b.closest('[data-modal]'));
      anunciar(b.getAttribute('data-confirmar') === 'excluir-conta' ? 'Solicitação de exclusão registrada.' : 'Acesso revogado.');
    });
  });
  document.addEventListener('keydown', function (e) {
    if (!modalAberto) return;
    if (e.key === 'Escape') { fechar(modalAberto); return; }
    if (e.key === 'Tab') {
      var f = focaveis(modalAberto);
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    document.getElementById('banner-sucesso').hidden = true;
    h.focus();
  });
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    if (this.checkValidity()) {
      anunciar('Perfil salvo.');
    } else {
      document.getElementById('resumo-erros').focus();
      anunciar('Corrija os campos destacados para salvar o perfil.');
    }
  });
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var agora = new Date();
    var hora = String(agora.getHours()).padStart(2, '0') + ':' + String(agora.getMinutes()).padStart(2, '0');
    var banner = document.getElementById('banner-sucesso');
    banner.querySelector('.banner-txt span').textContent = 'Suas preferências de notificação foram salvas às ' + hora + '.';
    banner.hidden = false;
    anunciar('Preferências salvas.');
  });
})();
@@ FIM

