<script>
(function () {
  var main = document.getElementById('conteudo');
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var ultimoFoco = null;

  function abreGaveta() {
    gaveta.hidden = false;
    btnAjuda.setAttribute('aria-expanded', 'true');
    gaveta.querySelector('a').focus();
  }
  function fechaGaveta() {
    gaveta.hidden = true;
    btnAjuda.setAttribute('aria-expanded', 'false');
    btnAjuda.focus();
  }
  btnAjuda.addEventListener('click', function () {
    if (gaveta.hidden) abreGaveta(); else fechaGaveta();
  });

  function abreModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var primeiro = m.querySelector('input, button');
    (primeiro || m).focus();
  }
  function fechaModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  window.abreModal = abreModal;

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x, [data-fechar]')) fechaModal(m);
    });
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var aberto = document.querySelector('.modal:not([hidden])');
    if (aberto) fechaModal(aberto);
    else if (!gaveta.hidden) fechaGaveta();
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () {
      b.closest('.banner').remove();
      main.focus();
    });
  });

  var campo = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  function validaConvite() {
    if (campo.checkValidity()) {
      campo.removeAttribute('aria-invalid');
      erro.hidden = true;
      return true;
    }
    campo.setAttribute('aria-invalid', 'true');
    erro.hidden = false;
    return false;
  }
  document.querySelector('[data-enviar-convite]').addEventListener('click', function () {
    if (!validaConvite()) campo.focus();
  });
  campo.addEventListener('input', function () {
    if (campo.getAttribute('aria-invalid') === 'true') validaConvite();
  });
})();
</script>
</body>
