<script>
(function () {
  var ultimoFoco = null;

  function abrir(id, gatilho) {
    var m = document.getElementById(id);
    ultimoFoco = gatilho || null;
    m.hidden = false;
    var alvo = m.querySelector('[data-foco-inicial]') || m.querySelector('input,button');
    if (alvo) alvo.focus();
  }

  function fechar(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
    ultimoFoco = null;
  }

  function modalAberto() {
    return document.querySelector('[data-modal]:not([hidden])');
  }

  document.addEventListener('keydown', function (e) {
    var m = modalAberto();
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var f = m.querySelectorAll('input:not([disabled]), button:not([disabled])');
    if (!f.length) return;
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  var tabelaAcessos = document.getElementById('acessos');
  var textoRevogar = document.getElementById('dlg-revogar-d');
  var tituloRevogar = document.getElementById('dlg-revogar-t');

  tabelaAcessos.querySelectorAll('[data-abrir]').forEach(function (b) {
    var nome = b.closest('tr').querySelector('th').textContent.trim();
    b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
    b.addEventListener('click', function () {
      tituloRevogar.textContent = 'Revogar o acesso de ' + nome + '?';
      textoRevogar.textContent = nome + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      abrir('fundo-revogar', b);
    });
  });

  tabelaAcessos.querySelectorAll('tbody .btn.pequeno:not([data-abrir])').forEach(function (b) {
    var nome = b.closest('tr').querySelector('th').textContent.trim();
    b.setAttribute('aria-label', 'Encerrar sessão de ' + nome);
  });

  var campoExcluir = document.getElementById('confirmar-exclusao');
  var btnExcluir = document.getElementById('btn-confirmar-exclusao');
  campoExcluir.addEventListener('input', function () {
    btnExcluir.disabled = campoExcluir.value.trim() !== 'EXCLUIR';
  });
  document.querySelectorAll('[data-abrir="fundo-excluir"]').forEach(function (b) {
    b.addEventListener('click', function () {
      campoExcluir.value = '';
      btnExcluir.disabled = true;
      abrir('fundo-excluir', b);
    });
  });

  var form = document.getElementById('form-perfil');
  var btnSalvar = form.querySelector('button[type="submit"]');
  var email = document.getElementById('email');
  var erroEmail = document.getElementById('erro-email');
  var tel = document.getElementById('telefone');
  var erroTel = document.getElementById('erro-telefone');

  function validarEmail() {
    var ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
    email.setCustomValidity(ok ? '' : 'E-mail inválido');
    email.setAttribute('aria-invalid', String(!ok));
    erroEmail.hidden = ok;
    email.closest('.campo').classList.toggle('campo-erro', !ok);
  }

  function validarTel() {
    var n = tel.value.replace(/\D/g, '').length;
    var ok = n === 10 || n === 11;
    tel.setCustomValidity(ok ? '' : 'Telefone incompleto');
    tel.setAttribute('aria-invalid', String(!ok));
    erroTel.hidden = ok;
    tel.closest('.campo').classList.toggle('campo-erro', !ok);
  }

  validarEmail();
  validarTel();
  btnSalvar.disabled = true;

  form.addEventListener('input', function (e) {
    if (e.target === email) validarEmail();
    if (e.target === tel) validarTel();
    btnSalvar.disabled = false;
  });

  form.addEventListener('reset', function () {
    setTimeout(function () {
      validarEmail();
      validarTel();
      btnSalvar.disabled = true;
    }, 0);
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
</script>
@@ FIM

