function desabilitarCampos(container, desabilitar){
  container.querySelectorAll('input,select').forEach(function(el){ el.disabled = desabilitar; });
}

function aplicarCobranca(){
  var igual = cobrancaIgual.checked;
  blocoCobranca.hidden = igual;
  desabilitarCampos(blocoCobranca, igual);
}

function aplicarPagamento(){
  var metodo = document.querySelector('input[name="metodo"]:checked').value;
  var cartaoAtivo = metodo === 'cartao';
  cartao.hidden = !cartaoAtivo;
  desabilitarCampos(cartao, !cartaoAtivo);
  blocoOtp.hidden = !cartaoAtivo;
  desabilitarCampos(blocoOtp, !cartaoAtivo);
}

function iniciarContagem(){
  var restantes = 30;
  btnReenviar.disabled = true;
  reenviarStatus.textContent = 'Você poderá pedir um novo código em ' + restantes + ' segundos.';
  clearInterval(contagem);
  contagem = setInterval(function(){
    restantes--;
    if (restantes <= 0){
      clearInterval(contagem);
      btnReenviar.disabled = false;
      reenviarStatus.textContent = 'Você já pode pedir um novo código.';
    } else {
      reenviarStatus.textContent = 'Você poderá pedir um novo código em ' + restantes + ' segundos.';
    }
  }, 1000);
}

function reenviar(){
  iniciarContagem();
  document.getElementById('otp').focus();
}

function buscarCep(){
  var input = document.getElementById('ent-cep');
  var s = document.getElementById('cep-status');
  var valido = input.value.replace(/\D/g, '').length === 8;
  if (valido){
    input.removeAttribute('aria-invalid');
    s.textContent = 'CEP válido. Confira o endereço preenchido.';
  } else {
    input.setAttribute('aria-invalid', 'true');
    s.textContent = 'Informe um CEP com 8 dígitos.';
  }
}

