<script>
(function () {
  var modalAtivo = null;
  var retorno = null;
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var banner = document.querySelector('.banner');
  var main = document.getElementById('conteudo');
  var form = document.getElementById('form-convite');
  var email = document.getElementById('conv-email');
  var erroEmail = document.getElementById('conv-erro');

  function abrirModal(m, origem) {
    retorno = origem || document.activeElement;
    modalAtivo = m;
    m.hidden = false;
    var foco = m.querySelector('input, button');
    if (foco) foco.focus();
  }

  function fecharModal() {
    if (!modalAtivo) return;
    modalAtivo.hidden = true;
    modalAtivo = null;
    if (retorno) retorno.focus();
  }

  function alternarGaveta(abrir) {
    gaveta.hidden = !abrir;
    btnAjuda.setAttribute('aria-expanded', String(abrir));
    (abrir ? gaveta.querySelector('a') : btnAjuda).focus();
  }

  btnAjuda.addEventListener('click', function () {
    alternarGaveta(gaveta.hidden);
  });

  document.body.addEventListener('click', function (e) {
    var abrir = e.target.closest('[data-abrir]');
    if (abrir) {
      abrirModal(document.getElementById(abrir.getAttribute('data-abrir')), abrir);
      return;
    }
    if (e.target.closest('[data-fechar="gaveta"]')) {
      alternarGaveta(false);
      return;
    }
    if (e.target.closest('[data-fechar]')) {
      fecharModal();
      return;
    }
    if (e.target.closest('[data-dispensar]')) {
      banner.hidden = true;
      main.focus();
    }
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m) fecharModal();
    });
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (email.checkValidity()) {
      erroEmail.hidden = true;
      email.removeAttribute('aria-invalid');
      fecharModal();
    } else {
      erroEmail.hidden = false;
      email.setAttribute('aria-invalid', 'true');
      email.focus();
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      if (modalAtivo) fecharModal();
      else if (!gaveta.hidden) alternarGaveta(false);
      return;
    }
    if (e.key === 'Tab' && modalAtivo) {
      var f = modalAtivo.querySelectorAll('input, button');
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        primeiro.focus();
      }
    }
  });
})();
</script>
</body>
