<script>
(function(){
  var tabs=[].slice.call(document.querySelectorAll('[role=tab]'));
  function ativar(t){
    tabs.forEach(function(x){
      var sel=x===t;
      x.setAttribute('aria-selected',sel);
      x.tabIndex=sel?0:-1;
      x.classList.toggle('aba-ativa',sel);
      document.getElementById(x.getAttribute('aria-controls')).hidden=!sel;
    });
    t.focus();
  }
  tabs.forEach(function(t,i){
    t.addEventListener('click',function(){ativar(t);});
    t.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight')n=tabs[(i+1)%tabs.length];
      else if(e.key==='ArrowLeft')n=tabs[(i-1+tabs.length)%tabs.length];
      else if(e.key==='Home')n=tabs[0];
      else if(e.key==='End')n=tabs[tabs.length-1];
      if(n){e.preventDefault();ativar(n);}
    });
  });
  var mesmo=document.querySelector('input[name=mesmo]');
  var corr=document.getElementById('cep-cor').closest('fieldset');
  function sincronizar(){corr.disabled=mesmo.checked;}
  mesmo.addEventListener('change',sincronizar);
  sincronizar();
})();
</script>
</body>
