var tituloBase = document.title;
var ultimoFoco = null;

function $(id){ return document.getElementById(id); }

function buscarCep(){
  var s = $('cep-status');
  if (s) { s.textContent = 'Endereço localizado.'; }
}

function aplicarCupom(){
  var c = $('cupom');
  $('cupom-erro').textContent = c.value.trim() ? 'Cupom não encontrado ou expirado. Confira o código e tente novamente.' : 'Digite o código do cupom.';
  c.focus();
}

function reenviar(){
  var s = $('reenv-status');
  if (s) { s.textContent = 'Novo código enviado por SMS.'; }
  document.querySelector('input[name="otp1"]').focus();
}

function abrirDialogo(n){
  ultimoFoco = document.activeElement;
  $('dlg-p').textContent = n + ' será removido do pedido.';
  $('veu').hidden = false;
  $('dlg-remover').focus();
}

function fecharDialogo(){
  $('veu').hidden = true;
  if (ultimoFoco) { ultimoFoco.focus(); }
}

function alternarCobranca(c){ $('bloco-cobranca').hidden = c.checked; }

function mostrarCartao(){
  var metodo = document.querySelector('input[name="metodo"]:checked').value;
  $('cartao').hidden = metodo !== 'cartao';
}

function nomeCampo(el){
  if (el.name.indexOf('otp') === 0) { return 'Código de verificação'; }
  var l = document.querySelector('label[for="' + el.id + '"]');
  return el.getAttribute('aria-label') || (l ? l.textContent.trim() : el.name);
}

function erroDe(el){
  var v = el.value.trim();
  if (!v) { return 'Preencha este campo para continuar.'; }
  if (el.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) { return 'Digite um e-mail válido, como nome@exemplo.com.br.'; }
  if ((el.id === 'ent-rua' || el.id === 'cob-rua') && !/\d/.test(v)) { return 'Inclua o número do endereço, por exemplo: Rua das Flores, 120.'; }
  if (el.id === 'cc-num' && !/^\d{13,19}$/.test(v.replace(/[\s-]/g, ''))) { return 'Digite os 13 a 19 números do cartão.'; }
  if (el.id === 'cc-exp' && !/^(0[1-9]|1[0-2])\/\d{2}$/.test(v)) { return 'Use o formato MM/AA, por exemplo 08/29.'; }
  if (el.id === 'cc-csc' && !/^\d{3,4}$/.test(v)) { return 'Digite os 3 dígitos do verso do cartão (4 em cartões Amex).'; }
  return '';
}

var form = $('form-checkout');
form.addEventListener('submit', function(e){
  e.preventDefault();
  var erros = [];
  form.querySelectorAll('input[required], select[required]').forEach(function(el){
    if (el.closest('[hidden]') || el.name.indexOf('otp') === 0) { return; }
    var msg = erroDe(el);
    var m = $(el.id + '-erro');
    if (!m) { m = document.createElement('small'); m.id = el.id + '-erro'; m.className = 'erro-campo'; el.parentNode.appendChild(m); }
    m.textContent = msg;
    if (msg) {
      var desc = (el.getAttribute('aria-describedby') || '').split(' ').filter(Boolean);
      if (desc.indexOf(m.id) < 0) { desc.push(m.id); }
      el.setAttribute('aria-describedby', desc.join(' '));
      el.setAttribute('aria-invalid', 'true');
      erros.push({ el: el, msg: msg });
    } else {
      el.removeAttribute('aria-invalid');
    }
  });
  var codigo = Array.prototype.map.call(form.querySelectorAll('input[name^="otp"]'), function(i){ return i.value.trim(); }).join('');
  if (!/^\d{6}$/.test(codigo)) {
    erros.push({ el: $('otp1'), msg: 'Digite os 6 dígitos do código enviado por SMS.' });
  }

  var resumo = $('resumo-erros');
  if (erros.length) {
    var lista = $('lista-erros');
    lista.innerHTML = '';
    erros.forEach(function(er){
      var li = document.createElement('li');
      var pre = document.createElement('span');
      pre.className = 'sr-only';
      pre.textContent = 'Erro: ';
      var a = document.createElement('a');
      a.href = '#' + er.el.id;
      a.textContent = nomeCampo(er.el) + ': ' + er.msg;
      li.appendChild(pre);
      li.appendChild(a);
      lista.appendChild(li);
    });
    $('resumo-msg').textContent = 'Revise os ' + erros.length + (erros.length === 1 ? ' campo destacado.' : ' campos destacados.');
    resumo.hidden = false;
    document.title = 'Erro: ' + tituloBase;
    resumo.focus();
    return;
  }
  resumo.hidden = true;
  document.title = tituloBase;
  var conf = $('confirmacao');
  conf.hidden = false;
  conf.focus();
});

