  var regras={
    'nome':function(v){return /^[\p{L}'\- ]+\s+[\p{L}'\- ]+$/u.test(v)?'':'Informe nome e sobrenome.';},
    'cpf':function(v){return v.replace(/\D/g,'').length===11?'':'Informe o CPF com 11 dígitos.';},
    'ano':function(v){return /^\d{4}$/.test(v)?'':'Informe o ano de nascimento com 4 dígitos.';},
    'cep-res':function(v){return v.replace(/\D/g,'').length===8?'':'Informe o CEP com 8 dígitos.';},
    'email':function(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)?'':'Informe um e-mail válido.';},
    'tel':function(v){var n=v.replace(/\D/g,'').length;return (n===10||n===11)?'':'Informe o telefone com DDD.';}
  };
  function fmtTel(v){
    var d=v.replace(/\D/g,'').slice(0,11);
    if(d.length<=2) return d.length?'('+d:'';
    if(d.length<=6) return '('+d.slice(0,2)+') '+d.slice(2);
    if(d.length<=10) return '('+d.slice(0,2)+') '+d.slice(2,6)+'-'+d.slice(6);
    return '('+d.slice(0,2)+') '+d.slice(2,7)+'-'+d.slice(7);
  }
  if(tel){
    tel.value=fmtTel(tel.value);
    tel.addEventListener('input',function(){tel.value=fmtTel(tel.value);});
  }
  function marcar(campo,input,msg){
    var p=campo.querySelector('.erro');
    if(!msg){
      campo.classList.remove('tem-erro');
      input.removeAttribute('aria-invalid');
      if(p) p.parentNode.removeChild(p);
      return true;
    }
    campo.classList.add('tem-erro');
    input.setAttribute('aria-invalid','true');
    if(!p){
      p=document.createElement('p');
      p.className='erro';
      p.id=input.id+'-erro';
      campo.appendChild(p);
    }
    p.textContent=msg;
    var ids=(input.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
    if(ids.indexOf(p.id)<0){ids.push(p.id);input.setAttribute('aria-describedby',ids.join(' '));}
    return false;
  }
  function checarCampo(c){
    var input=c.querySelector('input,select');
    var v=input.value.trim();
    var msg='';
    if(!v) msg='Campo obrigatório.';
    else if(regras[input.id]) msg=regras[input.id](v);
    return marcar(c,input,msg);
  }
  function validar(){
    var erros=[];
    form.querySelectorAll('.campo').forEach(function(c){
      if(!c.querySelector('.obrig')) return;
      if(!checarCampo(c)) erros.push(c.querySelector('input,select'));
    });
    return erros;
  }
  form.addEventListener('submit',function(e){
    e.preventDefault();
    var erros=validar();
    lista.innerHTML='';
    if(!erros.length){resumo.hidden=true;return;}
    erros.forEach(function(input){
      var campo=input.closest('.campo');
      var li=document.createElement('li');
      var a=document.createElement('a');
      a.href='#'+input.id;
      a.textContent=campo.querySelector('label').textContent.replace('*','').trim()+': '+campo.querySelector('.erro').textContent;
      li.appendChild(a);
      lista.appendChild(li);
    });
    resumo.querySelector('h2').textContent=erros.length===1?'Há 1 problema nesta etapa':'Há '+erros.length+' problemas nesta etapa';
    resumo.hidden=false;
    resumo.focus();
  });
  form.addEventListener('focusout',function(e){
    var c=e.target.closest?e.target.closest('.campo'):null;
    if(c&&c.querySelector('.obrig')) checarCampo(c);
  });
  function copiar(){
    if(!mesmo||!mesmo.checked) return;
    pares.forEach(function(p){
      document.getElementById(p[1]).value=document.getElementById(p[0]).value;
    });
  }
  if(mesmo) mesmo.addEventListener('change',copiar);
  form.addEventListener('input',copiar);
  form.addEventListener('change',copiar);
  function ativar(aba){
    abas.forEach(function(a){
      var sel=a===aba;
      a.setAttribute('aria-selected',sel?'true':'false');
      a.tabIndex=sel?0:-1;
      a.classList.toggle('aba-ativa',sel);
      document.getElementById(a.getAttribute('aria-controls')).hidden=!sel;
    });
    aba.focus();
  }
  abas.forEach(function(a,i){
    a.setAttribute('aria-selected',a.classList.contains('aba-ativa')?'true':'false');
    if(!a.classList.contains('aba-ativa')) a.tabIndex=-1;
    a.addEventListener('click',function(){ativar(a);});
    a.addEventListener('keydown',function(e){
      var n=abas.length,j;
      if(e.key==='ArrowRight') j=(i+1)%n;
      else if(e.key==='ArrowLeft') j=(i-1+n)%n;
      else return;
      e.preventDefault();
      ativar(abas[j]);
    });
  });
})();
</script>
</body>
