(function () {
  var ultimoFoco = null;
  var fundoPrincipal = document.querySelectorAll('body > header, body > .layout, body > footer');

  function abrir(modal) {
    ultimoFoco = document.activeElement;
    fundoPrincipal.forEach(function (el) { el.inert = true; });
    modal.hidden = false;
    var botoes = modal.querySelectorAll('button');
    botoes[botoes.length - 1].focus();
  }

  function fechar(modal) {
    modal.hidden = true;
    fundoPrincipal.forEach(function (el) { el.inert = false; });
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrir(document.getElementById(b.getAttribute('data-abrir')));
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      fechar(b.closest('[data-modal]'));
    });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key === 'Tab') {
      var botoes = aberto.querySelectorAll('button');
      var primeiro = botoes[0];
      var ultimo = botoes[botoes.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('th').textContent.trim();
    tr.querySelectorAll('td button').forEach(function (b) {
      var s = document.createElement('span');
      s.className = 'sr-only';
      s.textContent = ' de ' + nome;
      b.appendChild(s);
    });
  });

  document.querySelectorAll('.estado').forEach(function (e) {
    var p = e.querySelector('.ponto');
    if (!p) return;
    var t = document.createElement('span');
    t.textContent = p.getAttribute('aria-label');
    p.removeAttribute('role');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    e.appendChild(t);
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var titulo = document.getElementById('h-pref');
    titulo.tabIndex = -1;
    titulo.focus();
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
