(function () {
  var live = document.getElementById('live');
  var contagem = document.getElementById('contagem-acessos');
  var gatilhoAtual = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrir(id, gatilho) {
    var fundo = document.getElementById(id);
    gatilhoAtual = gatilho;
    if (id === 'fundo-revogar') {
      document.getElementById('app-revogar').textContent = gatilho.getAttribute('data-app');
    }
    fundo.hidden = false;
    var botoes = fundo.querySelectorAll('button');
    botoes[botoes.length - 1].focus();
  }

  function fechar(fundo) {
    fundo.hidden = true;
    if (gatilhoAtual) gatilhoAtual.focus();
    gatilhoAtual = null;
  }

  function confirmar(acao, fundo) {
    if (acao === 'revogar' && gatilhoAtual) {
      var app = gatilhoAtual.getAttribute('data-app');
      var linha = gatilhoAtual.closest('tr');
      linha.querySelector('.estado').innerHTML = '<span class="ponto exp" aria-hidden="true"></span>Revogado';
      gatilhoAtual.disabled = true;
      gatilhoAtual.textContent = 'Revogado';
      var restantes = document.querySelectorAll('[data-abrir="fundo-revogar"]:not([disabled])').length;
      contagem.textContent = restantes + (restantes === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
      gatilhoAtual = null;
      fundo.hidden = true;
      contagem.setAttribute('tabindex', '-1');
      contagem.focus();
      anunciar('Acesso de ' + app + ' revogado.');
    } else if (acao === 'excluir') {
      gatilhoAtual = null;
      fundo.hidden = true;
      var titulo = document.getElementById('h-perigo');
      titulo.setAttribute('tabindex', '-1');
      titulo.focus();
      anunciar('Pedido de exclusão registrado.');
    }
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      confirmar(b.getAttribute('data-confirmar'), b.closest('[data-modal]'));
    });
  });

  document.querySelectorAll('[data-encerrar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var linha = b.closest('tr');
      var th = linha.querySelector('th');
      var nome = th.textContent;
      b.disabled = true;
      b.textContent = 'Sessão encerrada';
      th.setAttribute('tabindex', '-1');
      th.focus();
      anunciar('Sessão de ' + nome + ' encerrada.');
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var banner = document.getElementById('banner-sucesso');
    var titulo = document.getElementById('h-pref');
    titulo.setAttribute('tabindex', '-1');
    banner.hidden = true;
    titulo.focus();
  });

  document.addEventListener('keydown', function (e) {
    var fundo = document.querySelector('[data-modal]:not([hidden])');
    if (!fundo) return;
    if (e.key === 'Escape') {
      fechar(fundo);
      return;
    }
    if (e.key === 'Tab') {
      var foco = fundo.querySelectorAll('button:not([disabled])');
      var primeiro = foco[0];
      var ultimo = foco[foco.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        primeiro.focus();
      }
    }
  });
})();
