var live = document.getElementById('live');
function anunciar(msg) { live.textContent = ''; setTimeout(function () { live.textContent = msg; }, 50); }
var gatilhoAtual = null;
function abrir(id, gatilho) {
  gatilhoAtual = gatilho || null;
  var fundo = document.getElementById(id);
  if (id === 'fundo-excluir') {
    document.getElementById('confirmar-exclusao').value = '';
    document.getElementById('btn-confirmar-exclusao').disabled = true;
  }
  fundo.hidden = false;
  var alvo = fundo.querySelector('input') || fundo.querySelector('.btn.perigo') || fundo.querySelector('button');
  alvo.focus();
}
function fechar(fundo) {
  fundo.hidden = true;
  if (gatilhoAtual) gatilhoAtual.focus();
  gatilhoAtual = null;
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    var id = b.getAttribute('data-abrir');
    if (id === 'fundo-revogar') {
      document.getElementById('dlg-revogar-d').textContent = 'O aplicativo ' + b.getAttribute('data-app') + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    abrir(id, b);
  });
});
document.querySelectorAll('[data-modal]').forEach(function (fundo) {
  fundo.addEventListener('click', function (e) { if (e.target === fundo) fechar(fundo); });
  fundo.addEventListener('keydown', function (e) { if (e.key === 'Escape') fechar(fundo); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
});
var confirmarInput = document.getElementById('confirmar-exclusao');
var btnExcluir = document.getElementById('btn-confirmar-exclusao');
confirmarInput.addEventListener('input', function () {
  btnExcluir.disabled = confirmarInput.value.trim().toUpperCase() !== 'EXCLUIR';
});
btnExcluir.addEventListener('click', function () {
  // Integrar aqui a chamada de exclusão da conta.
  fechar(document.getElementById('fundo-excluir'));
});
document.getElementById('btn-confirmar-revogar').addEventListener('click', function () {
  // Integrar aqui a chamada de revogação do acesso.
  fechar(document.getElementById('fundo-revogar'));
});
document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
});
document.querySelector('[data-retentar]').addEventListener('click', function () {
  location.reload();
});
function marcar(campo, erro, invalido) {
  campo.closest('.campo').classList.toggle('campo-erro', invalido);
  campo.setAttribute('aria-invalid', invalido ? 'true' : 'false');
  erro.hidden = !invalido;
}
document.getElementById('form-perfil').addEventListener('submit', function (e) {
  e.preventDefault();
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email.value.trim());
  var digitos = tel.value.replace(/\D/g, '').length;
  var telOk = digitos === 10 || digitos === 11;
  marcar(email, document.getElementById('erro-email'), !emailOk);
  marcar(tel, document.getElementById('erro-telefone'), !telOk);
  if (!emailOk) { email.focus(); anunciar('Corrija o e-mail antes de salvar.'); return; }
  if (!telOk) { tel.focus(); anunciar('Corrija o telefone antes de salvar.'); return; }
  // Enviar os dados do perfil ao servidor aqui.
  anunciar('Perfil salvo.');
});
document.getElementById('form-prefs').addEventListener('submit', function (e) {
  e.preventDefault();
  var hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  document.getElementById('msg-sucesso').textContent = 'Preferências salvas às ' + hora + '.';
  document.getElementById('banner-sucesso').hidden = false;
  // Enviar as preferências ao servidor aqui.
  anunciar('Preferências salvas.');
});
@@ FIM

