(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  // Estado visível em texto, não só na cor
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var r = document.createElement('span');
    r.textContent = p.getAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.removeAttribute('aria-label');
    p.parentNode.appendChild(r);
  });

  // Diálogos: foco inicial no cancelamento, Esc fecha e o foco volta ao gatilho
  var ultimoFoco = null;
  function abrir(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    m.querySelector('[data-fechar]:not(.perigo)').focus();
  }
  function fechar(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('keydown', function (e) { if (e.key === 'Escape') fechar(m); });
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
    m.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fechar(m); });
    });
  });
  document.querySelectorAll('[data-abrir="fundo-excluir"]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(document.getElementById('fundo-excluir')); });
  });

  // Revogar acesso: ação reversível, então desfazer em vez de confirmar
  var contagem = document.getElementById('contagem-acessos');
  function atualizarContagem() {
    var n = document.querySelector('#acessos table tbody').querySelectorAll('tr:not([hidden])').length;
    contagem.textContent = n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
  }
  var toastTimer = null;
  function toast(msg, acao, fn) {
    var antigo = document.getElementById('toast');
    if (antigo) antigo.remove();
    clearTimeout(toastTimer);
    var t = document.createElement('div');
    t.id = 'toast';
    t.className = 'toast';
    var s = document.createElement('span');
    s.textContent = msg;
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'btn pequeno';
    b.textContent = acao;
    b.addEventListener('click', function () { fn(); t.remove(); });
    t.append(s, b);
    document.body.appendChild(t);
    b.focus();
    anunciar(msg);
    toastTimer = setTimeout(function () { t.remove(); }, 8000);
  }
  document.querySelectorAll('button.perigo-suave').forEach(function (b) {
    b.addEventListener('click', function () {
      var linha = b.closest('tr');
      var nome = linha.querySelector('th').textContent;
      linha.hidden = true;
      atualizarContagem();
      toast('Acesso de ' + nome + ' revogado.', 'Desfazer', function () {
        linha.hidden = false;
        atualizarContagem();
        anunciar(nome + ' autorizado novamente.');
      });
    });
  });

  // Perfil: valida ao tentar enviar, com resumo de erros
  var formPerfil = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  function marcar(input, erro, invalido) {
    input.setAttribute('aria-invalid', String(invalido));
    erro.hidden = !invalido;
    input.closest('.campo').classList.toggle('campo-erro', invalido);
  }
  formPerfil.addEventListener('submit', function (e) {
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim());
    var digitos = tel.value.replace(/\D/g, '').length;
    var telOk = digitos === 10 || digitos === 11;
    marcar(email, document.getElementById('erro-email'), !emailOk);
    marcar(tel, document.getElementById('erro-telefone'), !telOk);
    var itens = [];
    if (!emailOk) itens.push(['email', 'E-mail corporativo: informe um endereço válido.']);
    if (!telOk) itens.push(['telefone', 'Telefone celular: informe DDD e número completo.']);
    lista.textContent = '';
    itens.forEach(function (it) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + it[0];
      a.textContent = it[1];
      li.appendChild(a);
      lista.appendChild(li);
    });
    if (itens.length) {
      e.preventDefault();
      resumo.hidden = false;
      resumo.focus();
    } else {
      resumo.hidden = true;
    }
  });

  // Preferências: confirmação visível e anunciada
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    document.getElementById('txt-sucesso').textContent = 'Preferências salvas às ' + hora + '.';
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências salvas às ' + hora + '.');
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
