  function gaveta(){return document.getElementById('gaveta');}
  function botaoAjuda(){return document.querySelector('[data-alternar="gaveta"]');}
  function abrirModal(m){
    if(!m)return;
    ultimoFoco=document.activeElement;
    m.hidden=false;
    var f=m.querySelector('input,button:not([disabled])');
    if(f)f.focus();
  }
  function fecharModal(m){
    m.hidden=true;
    if(ultimoFoco&&ultimoFoco.focus)ultimoFoco.focus();
  }
  function alternarGaveta(){
    var g=gaveta(),b=botaoAjuda();
    if(g.hidden){
      g.hidden=false;
      b.setAttribute('aria-expanded','true');
      g.querySelector('button,a').focus();
    }else{
      g.hidden=true;
      b.setAttribute('aria-expanded','false');
      b.focus();
    }
  }
  document.addEventListener('click',function(e){
    var t=e.target,el;
    if(el=t.closest('[data-alternar]')){alternarGaveta();return;}
    if(el=t.closest('[data-abrir]')){abrirModal(document.getElementById(el.getAttribute('data-abrir')));return;}
    if(el=t.closest('[data-dispensar]')){
      el.closest('.banner').remove();
