    if(el=t.closest('[data-fechar="gaveta"]')){alternarGaveta();return;}
    if(el=t.closest('[data-fechar],.modal-x')){
      var m=el.closest('.modal');
      if(m)fecharModal(m);
      return;
    }
    if(t.classList&&t.classList.contains('modal')){fecharModal(t);}
  });
  document.addEventListener('keydown',function(e){
    if(e.key!=='Escape')return;
    if(!gaveta().hidden){alternarGaveta();return;}
    var abertos=document.querySelectorAll('.modal:not([hidden])');
    if(abertos.length)fecharModal(abertos[abertos.length-1]);
