var ultimoGatilho = null;

function alternarFundo(ocultar) {
  ['.topo', '.layout', '.rodape'].forEach(function (s) { document.querySelector(s).inert = ocultar; });
}

function abrirModal(id, gatilho) {
  var fundo = document.getElementById(id);
  ultimoGatilho = gatilho;
  alternarFundo(true);
  fundo.hidden = false;
  fundo.querySelectorAll('[data-fechar]')[1].focus();
}

function fecharModal(fundo) {
  fundo.hidden = true;
  alternarFundo(false);
  if (ultimoGatilho) { ultimoGatilho.focus(); ultimoGatilho = null; }
}

document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    var linha = b.closest('tr');
    if (linha) document.getElementById('dlg-revogar-app').textContent = linha.querySelector('th').textContent.trim();
    abrirModal(b.getAttribute('data-abrir'), b);
  });
});

document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});

document.addEventListener('keydown', function (e) {
  var aberto = document.querySelector('[data-modal]:not([hidden])');
  if (!aberto) return;
  if (e.key === 'Escape') { fecharModal(aberto); return; }
  if (e.key === 'Tab') {
    var focaveis = aberto.querySelectorAll('button:not([disabled])');
    var primeiro = focaveis[0], ultimo = focaveis[focaveis.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});

document.querySelectorAll('tbody tr').forEach(function (tr) {
  var nome = tr.querySelector('th').textContent.trim();
  tr.querySelectorAll('button').forEach(function (b) {
    b.setAttribute('aria-label', b.textContent.trim() + ': ' + nome);
  });
});

document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
