<script>
(function () {
  var ajuda = document.querySelector('[aria-controls="gaveta"]');
  var gaveta = document.getElementById('gaveta');
  var ultimoFoco = null;

  function alternarGaveta(abrir) {
    gaveta.classList.toggle('aberta', abrir);
    ajuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) { gaveta.querySelector('a').focus(); } else { ajuda.focus(); }
  }

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var primeiro = m.querySelector('input, button');
    if (primeiro) primeiro.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  ajuda.addEventListener('click', function () {
    alternarGaveta(!gaveta.classList.contains('aberta'));
  });

  var convidar = document.getElementById('enviar-convite');
  var email = document.getElementById('conv-email');
  var erroConv = document.getElementById('conv-erro');
  convidar.addEventListener('click', function () {
    var ok = email.checkValidity();
    email.setAttribute('aria-invalid', String(!ok));
    erroConv.hidden = ok;
    if (!ok) email.focus();
  });

  document.addEventListener('click', function (e) {
    var abre = e.target.closest('[data-abre]');
    if (abre) abrirModal(document.getElementById(abre.getAttribute('data-abre')));
    var fecha = e.target.closest('.modal-x, [data-fecha]');
    if (fecha) fecharModal(fecha.closest('.modal'));
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var modal = document.querySelector('.modal:not([hidden])');
    if (modal) fecharModal(modal);
    else if (gaveta.classList.contains('aberta')) alternarGaveta(false);
  });
})();
</script>
