(function () {
  var live = document.getElementById('live');
  var origem = null;
  var regiaoInerte = [document.getElementById('topo'), document.querySelector('.layout'), document.querySelector('.rodape')];

  function linhaDe(el) {
    var tr = el.closest('tr');
    var th = tr && tr.querySelector('th');
    return th ? th.textContent.trim() : '';
  }

  // Tabelas roláveis no celular e focáveis pelo teclado
  document.querySelectorAll('table').forEach(function (t) {
    var w = document.createElement('div');
    w.className = 'tabela-rolagem';
    w.tabIndex = 0;
    t.parentNode.insertBefore(w, t);
    w.appendChild(t);
  });

  // Status com texto visível, não apenas cor
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var texto = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    var s = document.createElement('span');
    s.textContent = texto;
    p.parentNode.appendChild(s);
  });

  // Ações repetidas com nome específico para leitores de tela
  document.querySelectorAll('button').forEach(function (b) {
    var txt = b.textContent.trim();
    if (txt === 'Revogar acesso') {
      b.setAttribute('aria-label', 'Revogar acesso de ' + linhaDe(b));
    } else if (txt === 'Encerrar sessão') {
      b.setAttribute('aria-label', 'Encerrar sessão de ' + linhaDe(b));
    }
  });

  // Modais: foco, Escape, Tab preso e região de fundo inerte
  function abrir(m, gatilho) {
    origem = gatilho;
    m.hidden = false;
    regiaoInerte.forEach(function (r) { if (r) r.inert = true; });
    var primario = m.querySelector('.modal .btn:not(.perigo)');
    if (primario) primario.focus();
  }

  function fechar(m) {
    m.hidden = true;
    regiaoInerte.forEach(function (r) { if (r) r.inert = false; });
    if (origem) origem.focus();
    origem = null;
  }

  function modalAberto() {
    return document.querySelector('[data-modal]:not([hidden])');
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var m = document.getElementById(b.getAttribute('data-abrir'));
      if (m.id === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + linhaDe(b) + '?';
      }
      abrir(m, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
  });

  document.addEventListener('keydown', function (e) {
    var m = modalAberto();
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var botoes = m.querySelectorAll('button:not([disabled])');
    var primeiro = botoes[0];
    var ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) {
      e.preventDefault();
      ultimo.focus();
    } else if (!e.shiftKey && document.activeElement === ultimo) {
      e.preventDefault();
      primeiro.focus();
    }
  });

  // Salvar perfil só fica ativo após alteração
  var formPerfil = document.getElementById('form-perfil');
  var btnPerfil = document.getElementById('salvar-perfil');
  formPerfil.addEventListener('input', function () { btnPerfil.disabled = false; });
  formPerfil.addEventListener('change', function () { btnPerfil.disabled = false; });
  formPerfil.addEventListener('reset', function () {
    setTimeout(function () { btnPerfil.disabled = true; }, 0);
  });
  formPerfil.addEventListener('submit', function () {
    btnPerfil.disabled = true;
    btnPerfil.textContent = 'Salvando…';
    live.textContent = 'Salvando alterações do perfil.';
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
