(function () {
  var live = document.getElementById('live');
  var resumo = document.getElementById('resumo-erros');
  var email = document.getElementById('email');
  var tel = document.getElementById('telefone');
  var bio = document.getElementById('bio');
  var banner = document.getElementById('banner-sucesso');
  var ultimoFoco = null;
  var modalAberto = null;
  var reEmail = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  var reTel = /^\(\d{2}\) 9?\d{4}-\d{4}$/;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrirModal(m, gatilho, nomeApp) {
    ultimoFoco = gatilho;
    modalAberto = m;
    var nome = m.querySelector('[data-app-nome]');
    if (nome) nome.textContent = nomeApp || '';
    m.hidden = false;
    var cancelar = m.querySelector('.acoes .btn:not(.perigo)');
    if (cancelar) cancelar.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    modalAberto = null;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abrir')), b, b.getAttribute('data-app'));
    });
  });

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fecharModal(m); });
    m.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () {
        if (b.hasAttribute('data-confirmar')) anunciar('Sessão encerrada.');
        fecharModal(m);
      });
    });
  });

  document.addEventListener('keydown', function (e) {
    if (!modalAberto) return;
    if (e.key === 'Escape') { fecharModal(modalAberto); return; }
    if (e.key !== 'Tab') return;
    var f = modalAberto.querySelectorAll('button:not([disabled])');
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    banner.hidden = true;
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var agora = new Date();
    var hora = String(agora.getHours()).padStart(2, '0') + ':' + String(agora.getMinutes()).padStart(2, '0');
    banner.querySelector('.banner-txt > span').textContent = 'Suas preferências de notificação foram salvas às ' + hora + '.';
    banner.hidden = false;
    anunciar('Preferências salvas.');
  });

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var emailOk = reEmail.test(email.value.trim());
    var telOk = reTel.test(tel.value.trim());
    [[email, emailOk, 'erro-email'], [tel, telOk, 'erro-telefone']].forEach(function (c) {
      c[0].setAttribute('aria-invalid', String(!c[1]));
      c[0].closest('.campo').classList.toggle('campo-erro', !c[1]);
      document.getElementById(c[2]).hidden = c[1];
    });
    resumo.querySelector('a[href="#email"]').parentNode.hidden = emailOk;
    resumo.querySelector('a[href="#telefone"]').parentNode.hidden = telOk;
    var invalidos = (emailOk ? 0 : 1) + (telOk ? 0 : 1);
    resumo.hidden = invalidos === 0;
    if (invalidos) {
      resumo.querySelector('h2').textContent = 'Corrija ' + invalidos + (invalidos === 1 ? ' campo' : ' campos') + ' para salvar o perfil';
      resumo.focus();
    } else {
      anunciar('Perfil salvo.');
    }
  });

  function contarBio() {
    document.getElementById('contador-bio').textContent = 'Restam ' + (200 - bio.value.length) + ' caracteres.';
  }
  bio.addEventListener('input', contarBio);
  contarBio();
})();
@@ FIM

