<script>
(function(){
  var ultimoFoco = null;
  var gaveta = document.getElementById('gaveta');
  var ajuda = document.querySelector('[aria-controls="gaveta"]');

  function abrirModal(m){
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var alvo = m.querySelector('input') || m.querySelector('.modal-acoes .btn-prim') || m.querySelector('.modal-x');
    if (alvo) alvo.focus();
  }
  function fecharModal(m){
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  function toggleAjuda(abrir){
    gaveta.hidden = !abrir;
    ajuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) { var l = gaveta.querySelector('a'); if (l) l.focus(); }
    else { ajuda.focus(); }
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click', function(){
      var m = document.getElementById(b.getAttribute('aria-controls'));
      if (m) abrirModal(m);
    });
  });

  ajuda.addEventListener('click', function(){ toggleAjuda(gaveta.hidden); });

  document.addEventListener('click', function(e){
    var m = e.target.closest('.modal');
    if (!m) return;
    if (e.target === m || e.target.closest('.modal-x') || e.target.textContent.trim() === 'Cancelar') {
      fecharModal(m);
    }
  });

  document.addEventListener('keydown', function(e){
    var aberto = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (aberto) fecharModal(aberto);
      else if (!gaveta.hidden) toggleAjuda(false);
      return;
    }
    if (e.key === 'Tab' && aberto) {
      var f = aberto.querySelectorAll('button,input,a[href]');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  var banner = document.querySelector('.banner');
  document.querySelector('.banner .btn-txt').addEventListener('click', function(){
    document.getElementById('conteudo').focus();
    banner.remove();
  });
})();
</script>
</body>
