<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var btnAjuda = document.getElementById('btn-ajuda');
  var banner = document.querySelector('.banner');
  var ultimoGatilho = null;
  var modalAberto = null;

  btnAjuda.addEventListener('click', function () {
    var abrir = gaveta.hidden;
    gaveta.hidden = !abrir;
    btnAjuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) gaveta.querySelector('a').focus();
  });

  banner.querySelector('.btn-txt').addEventListener('click', function () {
    banner.hidden = true;
  });

  function abrirModal(id, gatilho) {
    modalAberto = document.getElementById(id);
    ultimoGatilho = gatilho || document.activeElement;
    modalAberto.hidden = false;
    var foco = modalAberto.querySelector('input') || modalAberto.querySelector('.modal-acoes .btn');
    if (foco) foco.focus();
  }

  function fecharModal() {
    if (!modalAberto) return;
    modalAberto.hidden = true;
    modalAberto = null;
    if (ultimoGatilho) ultimoGatilho.focus();
  }

  window.abrirModal = abrirModal;

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fecharModal(); });
    m.querySelectorAll('.modal-x, .modal-acoes .btn:not(.btn-prim):not(.btn-perigo)').forEach(function (b) {
      b.addEventListener('click', fecharModal);
    });
  });

  var email = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  document.getElementById('btn-convidar').addEventListener('click', function () {
    var valido = email.checkValidity() && email.value.trim() !== '';
    email.setAttribute('aria-invalid', String(!valido));
    erro.hidden = valido;
    if (valido) fecharModal(); else email.focus();
  });
  email.addEventListener('input', function () {
    if (email.checkValidity()) {
      email.setAttribute('aria-invalid', 'false');
      erro.hidden = true;
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      if (modalAberto) {
        fecharModal();
      } else if (!gaveta.hidden) {
        gaveta.hidden = true;
        btnAjuda.setAttribute('aria-expanded', 'false');
        btnAjuda.focus();
      }
      return;
    }
    if (e.key === 'Tab' && modalAberto) {
      var focaveis = modalAberto.querySelectorAll('button, input, a[href]');
      var primeiro = focaveis[0];
      var ultimo = focaveis[focaveis.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault(); ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault(); primeiro.focus();
      }
    }
  });
})();
</script>
</body>
