(function () {
  var ultimoFoco = null;
  var okEmail = function (v) { return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v); };
  var okTel = function (v) { return v.replace(/\D/g, '').length === 11; };

  function validar(id, erroId, ok) {
    var el = document.getElementById(id);
    var erro = document.getElementById(erroId);
    var valido = ok(el.value);
    el.setAttribute('aria-invalid', valido ? 'false' : 'true');
    el.setAttribute('aria-describedby', 'dica-' + id + (valido ? '' : ' ' + erroId));
    erro.hidden = valido;
    el.closest('.campo').classList.toggle('campo-erro', !valido);
    return valido;
  }

  function abrir(modal) {
    ultimoFoco = document.activeElement;
    modal.hidden = false;
    var primeiro = modal.querySelector('[data-fechar]');
    (primeiro || modal).focus();
  }

  function fechar(modal) {
    modal.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrir(document.getElementById(b.getAttribute('data-abrir')));
    });
  });

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
    m.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fechar(m); });
    });
  });

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key === 'Tab') {
      var botoes = aberto.querySelectorAll('button:not([disabled])');
      var primeiro = botoes[0];
      var ultimo = botoes[botoes.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var form = document.getElementById('form-perfil');
  var salvar = form.querySelector('button[type="submit"]');

  function validarTudo() {
    var a = validar('email', 'erro-email', okEmail);
    var b = validar('telefone', 'erro-telefone', okTel);
    return a && b;
  }

  validarTudo();

  form.addEventListener('input', function (e) {
    salvar.disabled = false;
    if (e.target.id === 'email') validar('email', 'erro-email', okEmail);
    if (e.target.id === 'telefone') validar('telefone', 'erro-telefone', okTel);
  });

  form.addEventListener('reset', function () {
    setTimeout(function () { salvar.disabled = true; validarTudo(); }, 0);
  });

  form.addEventListener('submit', function (e) {
    if (!validarTudo()) {
      e.preventDefault();
      var primeiroErro = form.querySelector('[aria-invalid="true"]');
      if (primeiroErro) primeiroErro.focus();
    }
  });
})();
