var ultimoFoco = null;
var live = document.getElementById('live');

function abrirModal(id) {
  var modal = document.getElementById(id);
  ultimoFoco = document.activeElement;
  modal.hidden = false;
  var primeiro = modal.querySelector('[data-fechar]');
  if (primeiro) primeiro.focus();
}

function fecharModal(modal) {
  modal.hidden = true;
  if (ultimoFoco) ultimoFoco.focus();
}

function alternarRevogacao(botao) {
  var linha = botao.closest('tr');
  var nome = linha.querySelector('th').textContent.trim();
  var ponto = linha.querySelector('.ponto');
  var estavaRevogado = ponto.classList.contains('exp');
  ponto.className = 'ponto ' + (estavaRevogado ? 'ok' : 'exp');
  ponto.setAttribute('aria-label', estavaRevogado ? 'Ativo' : 'Revogado');
  botao.textContent = estavaRevogado ? 'Revogar acesso' : 'Desfazer';
  live.textContent = estavaRevogado ? 'Acesso de ' + nome + ' restaurado.' : 'Acesso de ' + nome + ' revogado.';
}

document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    var alvo = b.getAttribute('data-abrir');
    if (alvo === 'fundo-revogar') { alternarRevogacao(b); } else { abrirModal(alvo); }
  });
});

document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});

document.addEventListener('keydown', function (e) {
  if (e.key !== 'Escape') return;
  var aberto = document.querySelector('[data-modal]:not([hidden])');
  if (aberto) fecharModal(aberto);
});

document.getElementById('btn-dispensar').addEventListener('click', function () {
