(function () {
  var live = document.getElementById('live');
  var h = document.getElementById('h-acessos');
  h.setAttribute('tabindex', '-1');

  function anunciar(t) { live.textContent = t; }

  var ultimoFoco = null;
  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    (m.querySelector('[data-cancelar]') || m.querySelector('button')).focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abrir')));
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fecharModal(m); });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(m); return; }
      if (e.key !== 'Tab') return;
      var botoes = m.querySelectorAll('button');
      var primeiro = botoes[0], ultimo = botoes[botoes.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });
  document.querySelector('[data-confirmar-exclusao]').addEventListener('click', function () {
    anunciar('Solicitação de exclusão da conta registrada.');
  });

  var toast = document.getElementById('desfazer');
  var txt = document.getElementById('desfazer-txt');
  var btnDesfazer = document.getElementById('btn-desfazer');
  var pendente = null, timer = null;

  function contar() {
    var n = 0;
    document.querySelectorAll('[data-revogar]').forEach(function (b) {
      if (!b.closest('tr').hidden) n++;
    });
    document.getElementById('contagem-acessos').textContent =
      n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
  }
  function finalizar() {
    clearTimeout(timer);
    if (pendente) { pendente.remove(); pendente = null; }
    if (toast.contains(document.activeElement)) h.focus();
    toast.hidden = true;
  }
  function desfazer() {
    clearTimeout(timer);
    if (pendente) { pendente.hidden = false; pendente = null; }
    toast.hidden = true;
    contar();
    h.focus();
    anunciar('Acesso restaurado.');
  }
  document.querySelectorAll('[data-revogar]').forEach(function (b) {
    b.addEventListener('click', function () {
      finalizar();
      var linha = b.closest('tr');
      var nome = linha.querySelector('th').textContent;
      linha.hidden = true;
      pendente = linha;
      contar();
      txt.textContent = 'Acesso de ' + nome + ' revogado.';
      toast.hidden = false;
      btnDesfazer.focus();
      anunciar('Acesso de ' + nome + ' revogado. Você pode desfazer por 8 segundos.');
      timer = setTimeout(finalizar, 8000);
    });
  });
  btnDesfazer.addEventListener('click', desfazer);

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var formPerfil = document.getElementById('form-perfil');
  var email = document.getElementById('email'), erroEmail = document.getElementById('erro-email');
  var tel = document.getElementById('telefone'), erroTel = document.getElementById('erro-telefone');
  function emailValido() { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim()); }
  function telValido() { var d = tel.value.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }
  function marcar(campo, erro, ok) {
    erro.hidden = ok;
    campo.setAttribute('aria-invalid', String(!ok));
    campo.closest('.campo').classList.toggle('campo-erro', !ok);
  }
  email.addEventListener('input', function () { if (!erroEmail.hidden) marcar(email, erroEmail, emailValido()); });
  tel.addEventListener('input', function () { if (!erroTel.hidden) marcar(tel, erroTel, telValido()); });
  formPerfil.addEventListener('submit', function (e) {
    e.preventDefault();
    var okE = emailValido(), okT = telValido();
    marcar(email, erroEmail, okE);
    marcar(tel, erroTel, okT);
    if (!okE || !okT) {
      (okE ? tel : email).focus();
      anunciar('Corrija os campos destacados antes de salvar.');
      return;
    }
    anunciar('Perfil salvo.');
  });
  formPerfil.addEventListener('reset', function () {
    marcar(email, erroEmail, true);
    marcar(tel, erroTel, true);
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
  });

  contar();
})();
@@ FIM

