<script>
(function () {
  var ajuda = document.querySelector('[aria-controls="gaveta"]');
  var gaveta = document.getElementById('gaveta');
  var ultimoFoco = null;

  ajuda.addEventListener('click', function () {
    var aberta = ajuda.getAttribute('aria-expanded') === 'true';
    ajuda.setAttribute('aria-expanded', String(!aberta));
    gaveta.hidden = aberta;
    gaveta.classList.toggle('aberta', !aberta);
  });

  function abrir(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var alvo = m.querySelector('input') ||
               m.querySelector('.modal-acoes button:not(.btn-perigo)') ||
               m.querySelector('button');
    if (alvo) alvo.focus();
  }

  function fechar(m) {
    m.hidden = true;
    if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus();
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (gatilho) {
    gatilho.addEventListener('click', function () {
      abrir(document.getElementById(gatilho.getAttribute('aria-controls')));
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x, [data-fechar]')) fechar(m);
    });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal:not([hidden])').forEach(fechar);
    }
  });

  var m0 = document.getElementById('m0');
  var email = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  m0.querySelector('.btn-prim').addEventListener('click', function () {
    if (!email.checkValidity()) {
      erro.hidden = false;
      email.setAttribute('aria-invalid', 'true');
      email.focus();
    } else {
      email.removeAttribute('aria-invalid');
      erro.hidden = true;
      fechar(m0);
    }
  });

  var banner = document.querySelector('.banner');
  banner.querySelector('.btn-txt').addEventListener('click', function () {
    banner.remove();
    document.getElementById('conteudo').focus();
  });
})();
</script>
</body>
