(function () {
  var cabecalhos = document.querySelectorAll('.tabela thead .ord');
  var sw = document.querySelector('.sw');
  var resumo = document.getElementById('filtros-ativos');

  cabecalhos.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var th = btn.parentElement;
      var novo = th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
      cabecalhos.forEach(function (o) {
        o.parentElement.setAttribute('aria-sort', 'none');
        o.querySelector('.seta').textContent = '⇅';
      });
      th.setAttribute('aria-sort', novo);
      btn.querySelector('.seta').textContent = novo === 'ascending' ? '▲' : '▼';
    });
  });

  document.querySelectorAll('button.ac-b[aria-controls]').forEach(function (b) {
    b.addEventListener('click', function () {
      var aberto = b.getAttribute('aria-expanded') === 'true';
      b.setAttribute('aria-expanded', String(!aberto));
      var p = document.getElementById(b.getAttribute('aria-controls'));
      if (p) p.hidden = aberto;
    });
  });

  function contarFiltros() {
    var n = document.querySelectorAll('input[name="status"]:checked, input[name="tipo"]:checked').length;
    var faixa = document.querySelector('input[name="faixa"]:checked');
    if (faixa && faixa.value) n++;
    if (sw.getAttribute('aria-checked') === 'true') n++;
    resumo.textContent = n === 0 ? 'Nenhum filtro ativo' : n + (n === 1 ? ' filtro ativo' : ' filtros ativos');
  }

  sw.addEventListener('click', function () {
    sw.setAttribute('aria-checked', String(sw.getAttribute('aria-checked') !== 'true'));
    contarFiltros();
  });

  document.querySelectorAll('.filtros input').forEach(function (i) {
    i.addEventListener('change', contarFiltros);
  });

  document.getElementById('limpar').addEventListener('click', function () {
    document.querySelectorAll('.filtros input[name="status"], .filtros input[name="tipo"]').forEach(function (i) { i.checked = false; });
    document.querySelector('input[name="faixa"][value=""]').checked = true;
    sw.setAttribute('aria-checked', 'false');
    contarFiltros();
  });

  contarFiltros();
})();
@@ FIM

