  var m = document.getElementById(id);
  gatilho = document.activeElement;
  m.hidden = false;
  m.querySelector('.btn:not(.perigo)').focus();
}
function fecharModal(m) {
  m.hidden = true;
  if (gatilho) gatilho.focus();
}
document.querySelectorAll('[data-abrir="fundo-excluir"]').forEach(function (b) {
  b.addEventListener('click', function () { abrirModal('fundo-excluir'); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.querySelector('[data-confirmar="excluir"]').addEventListener('click', function () {
  fecharModal(document.getElementById('fundo-excluir'));
  document.dispatchEvent(new CustomEvent('conta-exclusao-confirmada'));
});
document.addEventListener('keydown', function (e) {
  if (e.key !== 'Escape') return;
  var aberto = document.querySelector('[data-modal]:not([hidden])');
  if (aberto) fecharModal(aberto);
});

var pendente = null;
function efetivarRevogacao() {
  if (!pendente) return;
  clearTimeout(pendente.t);
  pendente.toast.remove();
  document.dispatchEvent(new CustomEvent('acesso-revogado', { detail: pendente.app }));
  pendente = null;
  var corpo = document.querySelector('#acessos table tbody');
  var n = Array.prototype.filter.call(corpo.rows, function (r) { return !r.hidden; }).length;
  document.getElementById('contagem-acessos').textContent = n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
}
document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
  var linha = b.closest('tr');
  var app = linha.querySelector('th').textContent;
  b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  b.addEventListener('click', function () {
    efetivarRevogacao();
    linha.hidden = true;
    var toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    var msg = document.createElement('span');
    msg.textContent = 'Acesso de ' + app + ' revogado.';
    var desfazer = document.createElement('button');
    desfazer.type = 'button';
    desfazer.className = 'btn pequeno';
    desfazer.textContent = 'Desfazer';
    toast.append(msg, desfazer);
    document.body.appendChild(toast);
    var p = { app: app, toast: toast };
    p.t = setTimeout(efetivarRevogacao, 8000);
    pendente = p;
    desfazer.focus();
    desfazer.addEventListener('click', function () {
      clearTimeout(p.t);
      toast.remove();
      linha.hidden = false;
      pendente = null;
      b.focus();
    });
  });
});

document.getElementById('btn-dispensar').addEventListener('click', function () { document.getElementById('banner-sucesso').hidden = true; });

document.getElementById('form-prefs').addEventListener('submit', function (e) {
  e.preventDefault();
  document.getElementById('banner-sucesso').hidden = false;
  document.getElementById('live').textContent = 'Preferências de notificação salvas.';
});

document.getElementById('form-perfil').addEventListener('submit', function (e) {
  e.preventDefault();
  var resumo = document.getElementById('resumo-perfil');
  var lista = document.getElementById('lista-erros');
  var checks = [
    { id: 'email', erro: 'erro-email', falhou: !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(document.getElementById('email').value.trim()) },
    { id: 'telefone', erro: 'erro-telefone', falhou: !/^\d{2}9\d{8}$/.test(document.getElementById('telefone').value.replace(/\D/g, '')) }
  ];
  lista.textContent = '';
  var primeiro = null;
  checks.forEach(function (c) {
    var input = document.getElementById(c.id);
    var msg = document.getElementById(c.erro);
    input.setAttribute('aria-invalid', c.falhou ? 'true' : 'false');
    input.closest('.campo').classList.toggle('campo-erro', c.falhou);
    msg.hidden = !c.falhou;
    if (c.falhou) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + c.id;
      a.textContent = msg.textContent;
      li.appendChild(a);
      lista.appendChild(li);
      primeiro = primeiro || input;
    }
  });
  if (primeiro) {
    resumo.hidden = false;
    resumo.focus();
  } else {
    resumo.hidden = true;
    document.getElementById('live').textContent = 'Perfil salvo.';
  }
});
