    m.querySelector('input, button').focus();
  }

  function fecharModal() {
    if (!modalAtivo) return;
    modalAtivo.hidden = true;
    modalAtivo = null;
    if (gatilho) gatilho.focus();
  }

  btnAjuda.addEventListener('click', function () {
    abrirGaveta(!gaveta.classList.contains('aberta'));
  });
  btnFecharGaveta.addEventListener('click', function () {
    abrirGaveta(false);
  });

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(b.getAttribute('aria-controls'), b);
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      var t = e.target;
      if (t === m || (t.tagName === 'BUTTON' && t.type === 'button')) fecharModal();
    });
  });

  var emailConv = document.getElementById('conv-email');
  var erroConv = document.getElementById('conv-erro');
  document.querySelector('#m0 button[type="submit"]').addEventListener('click', function () {
