<script>
(function () {
  var gaveta = document.getElementById('gaveta');
  var botaoAjuda = document.querySelector('[aria-controls="gaveta"]');
  var ultimoFoco = null;

  function abrirModal(m) {
    ultimoFoco = document.activeElement;
    m.hidden = false;
    var primeiro = m.querySelector('input, button');
    if (primeiro) primeiro.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }

  function alternarGaveta() {
    var abrir = gaveta.hidden;
    gaveta.hidden = !abrir;
    botaoAjuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) gaveta.focus();
  }

  botaoAjuda.addEventListener('click', alternarGaveta);

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    var m = document.getElementById(b.getAttribute('aria-controls'));
    if (m) b.addEventListener('click', function () { abrirModal(m); });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fecharModal(m); });
    m.querySelectorAll('.modal-x, [data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fecharModal(m); });
    });
  });

  var email = document.getElementById('conv-email');
  var erroEmail = document.getElementById('conv-erro');
  document.getElementById('conv-enviar').addEventListener('click', function () {
    if (email.checkValidity()) {
      email.setAttribute('aria-invalid', 'false');
      erroEmail.hidden = true;
      fecharModal(document.getElementById('m0'));
    } else {
      email.setAttribute('aria-invalid', 'true');
      erroEmail.hidden = false;
      email.focus();
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal:not([hidden])').forEach(function (m) { fecharModal(m); });
      if (!gaveta.hidden) { alternarGaveta(); botaoAjuda.focus(); }
    }
    if (e.key === 'Tab') {
      var aberto = document.querySelector('.modal:not([hidden])');
      if (!aberto) return;
      var f = aberto.querySelectorAll('button, input');
      var primeiroF = f[0], ultimoF = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiroF) { e.preventDefault(); ultimoF.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimoF) { e.preventDefault(); primeiroF.focus(); }
    }
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function (b) {
    b.addEventListener('click', function () {
      document.getElementById('conteudo').focus();
      b.closest('.banner').remove();
    });
  });
})();
</script>
