<script>
(function () {
  var origemFoco = null;

  function abrir(id, origem) {
    var f = document.getElementById(id);
    origemFoco = origem;
    f.hidden = false;
    (f.querySelector('input') || f.querySelector('[data-fechar]:not(.perigo)')).focus();
  }

  function fechar(f) {
    f.hidden = true;
    if (origemFoco) origemFoco.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        var app = b.closest('tr').querySelector('th').textContent;
        document.getElementById('dlg-revogar-d').textContent =
          'O aplicativo ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(id, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.addEventListener('keydown', function (e) {
    var m = document.querySelector('[data-modal]:not([hidden])');
    if (!m) return;
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key !== 'Tab') return;
    var foco = m.querySelectorAll('input, button:not([disabled])');
    var primeiro = foco[0], ultimo = foco[foco.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  var conf = document.getElementById('confirma-excluir');
  var btnConf = document.getElementById('btn-confirma-excluir');
  conf.addEventListener('input', function () {
    btnConf.disabled = conf.value.trim().toUpperCase() !== 'EXCLUIR';
  });

  document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
    var app = b.closest('tr').querySelector('th').textContent;
    b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  });

  document.querySelectorAll('td button').forEach(function (b) {
    if (b.textContent.trim() === 'Encerrar sessão') {
      var d = b.closest('tr').querySelector('th').textContent;
      b.setAttribute('aria-label', 'Encerrar sessão em ' + d);
    }
  });

  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var t = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', t);
  });

  function validar(input, erro, msg, ok) {
    erro.textContent = ok ? '' : msg;
    erro.hidden = ok;
    input.setAttribute('aria-invalid', ok ? 'false' : 'true');
    input.closest('.campo').classList.toggle('campo-erro', !ok);
    return ok;
  }

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    var email = document.getElementById('email');
    var tel = document.getElementById('telefone');
    var digitos = tel.value.replace(/\D/g, '');
    var okEmail = validar(email, document.getElementById('erro-email'),
      'Digite o e-mail completo, por exemplo nome@escola.com.br.',
      /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim()));
    var okTel = validar(tel, document.getElementById('erro-telefone'),
      'Digite o DDD e o número do celular, por exemplo (11) 91234-5678.',
      digitos.length === 10 || digitos.length === 11);
    if (!okEmail || !okTel) {
      e.preventDefault();
      (okEmail ? tel : email).focus();
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
