  el.addEventListener('input',function(){
    el.value=el.value.replace(/\D/g,'').slice(0,1);
    if(el.value&&otps[i+1]){otps[i+1].focus();}
  });
  el.addEventListener('keydown',function(e){
    if(e.key==='Backspace'&&!el.value&&otps[i-1]){otps[i-1].focus();}
  });
  el.addEventListener('paste',function(e){
    var t=(e.clipboardData||window.clipboardData).getData('text').replace(/\D/g,'');
    if(!t){return;}
    e.preventDefault();
    for(var k=0;k<t.length&&i+k<otps.length;k++){otps[i+k].value=t[k];}
    otps[Math.min(i+t.length,otps.length)-1].focus();
