<script>
(function () {
  var form = document.getElementById('form-checkout');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var tituloBase = document.title;
  var enviando = false;

  form.querySelectorAll('input[name^="otp"]').forEach(function (el) {
    if (!el.id) el.id = el.name;
  });

  function visivel(el) {
    for (var n = el; n && n !== form; n = n.parentElement) {
      if (n.hidden) return false;
    }
    return true;
  }

  function rotulo(el) {
    var l = form.querySelector('label[for="' + el.id + '"]');
    if (l) return l.textContent.replace(/\(opcional\)/, '').trim();
    return el.getAttribute('aria-label') || el.name;
  }

  function erroDe(el) {
    var v = el.value.trim();
    if (v === '') return el.hasAttribute('required') ? 'Preencha ' + rotulo(el) + '.' : '';
    if (el.validity && el.validity.patternMismatch) return el.title + '.';
    var d = v.replace(/\D/g, '');
    switch (el.id) {
      case 'email':
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) ? '' : 'Informe um e-mail válido, como nome@empresa.com.br.';
      case 'tel':
        return (d.length >= 10 && d.length <= 11) ? '' : 'Informe o telefone com DDD, com 10 ou 11 números. Ex.: (78) 91862-2428.';
      case 'ent-cep':
      case 'cob-cep':
        return d.length === 8 ? '' : 'Informe o CEP com 8 números. Ex.: 74003-010.';
      case 'cc-num':
        return (d.length >= 13 && d.length <= 19) ? '' : 'Informe o número do cartão, com 13 a 19 números.';
      case 'cc-exp':
        return /^(0[1-9]|1[0-2])\/\d{2}$/.test(v) ? '' : 'Informe a validade no formato MM/AA. Ex.: 08/29.';
      case 'cc-csc':
        return /^\d{3,4}$/.test(v) ? '' : 'Informe o código de segurança com 3 ou 4 números.';
      default:
        return '';
    }
  }

  function campos() {
    return Array.prototype.filter.call(form.querySelectorAll('input, select'), function (el) {
      return el.type !== 'radio' && el.type !== 'checkbox' && !el.disabled && visivel(el);
    });
  }

  function marcar(el, msg) {
    var errId = 'err-' + el.id;
    var p = document.createElement('p');
    p.className = 'erro-campo';
    p.id = errId;
    p.setAttribute('data-erro', '');
    var s = document.createElement('span');
    s.className = 'sr-only';
    s.textContent = 'Erro: ';
    p.appendChild(s);
    p.appendChild(document.createTextNode(msg));
    (el.closest('.campo') || el.parentElement).appendChild(p);
    el.setAttribute('aria-invalid', 'true');
    el.setAttribute('aria-describedby', ((el.getAttribute('aria-describedby') || '') + ' ' + errId).trim());
  }

  function limparErros() {
    form.querySelectorAll('[data-erro]').forEach(function (p) { p.parentNode.removeChild(p); });
    form.querySelectorAll('[aria-invalid]').forEach(function (el) {
      el.removeAttribute('aria-invalid');
      var d = (el.getAttribute('aria-describedby') || '').split(' ').filter(function (x) {
        return x && x.indexOf('err-') !== 0;
      });
      if (d.length) el.setAttribute('aria-describedby', d.join(' '));
      else el.removeAttribute('aria-describedby');
    });
  }

  function mostrarResumo(erros) {
    while (lista.firstChild) lista.removeChild(lista.firstChild);
    erros.forEach(function (e) {
      var li = document.createElement('li');
      var s = document.createElement('span');
      s.className = 'sr-only';
      s.textContent = 'Erro: ';
      var a = document.createElement('a');
      a.href = '#' + e.el.id;
      a.textContent = e.msg;
      li.appendChild(s);
      li.appendChild(a);
      lista.appendChild(li);
    });
    resumo.hidden = false;
    document.title = 'Erro: ' + tituloBase;
    resumo.focus();
  }

  form.addEventListener('submit', function (ev) {
    limparErros();
    var erros = [];
    campos().forEach(function (el) {
      var msg = erroDe(el);
      if (msg) erros.push({ el: el, msg: msg });
    });
    if (erros.length) {
      ev.preventDefault();
      erros.forEach(function (e) { marcar(e.el, e.msg); });
      mostrarResumo(erros);
      return;
    }
    resumo.hidden = true;
    lista.textContent = '';
    document.title = tituloBase;
    if (enviando) { ev.preventDefault(); return; }
    enviando = true;
    var b = document.getElementById('btn-pagar');
    b.textContent = 'Processando pagamento...';
    b.setAttribute('aria-busy', 'true');
  });

  var mesmo = document.getElementById('mesmo-end');
  var cobranca = document.getElementById('bloco-cobranca');
  function atualizarCobranca() { cobranca.hidden = mesmo.checked; }
  mesmo.addEventListener('change', atualizarCobranca);
  atualizarCobranca();

  var cartao = document.getElementById('cartao');
  var blocoOtp = document.getElementById('bloco-otp');
  function atualizarPagamento() {
    var m = form.querySelector('input[name="metodo"]:checked').value;
    cartao.hidden = m !== 'cartao';
    blocoOtp.hidden = m !== 'cartao';
  }
  form.querySelectorAll('input[name="metodo"]').forEach(function (r) {
    r.addEventListener('change', atualizarPagamento);
  });
  atualizarPagamento();

  document.getElementById('buscar-cep').addEventListener('click', function () {
    document.getElementById('cep-status').textContent = 'Não foi possível buscar o CEP agora. Preencha o endereço manualmente.';
  });

  document.getElementById('outro-cartao').addEventListener('click', function () {
    document.getElementById('cc-num').focus();
  });

  document.getElementById('aplicar-cupom').addEventListener('click', function () {
    var c = document.getElementById('cupom');
    document.getElementById('cupom-status').textContent = c.value.trim()
      ? 'Não foi possível validar o cupom agora. Tente novamente.'
      : 'Digite o código do cupom.';
    c.focus();
  });

  document.getElementById('reenviar').addEventListener('click', function () {
    document.getElementById('reenviar-status').textContent = 'Não foi possível reenviar o código agora. Tente novamente em instantes.';
  });

  var veu = document.getElementById('veu');
  var dlgP = document.getElementById('dlg-p');
  var gatilho = null;

  function abrirDialogo(nome, botao) {
    gatilho = botao;
    dlgP.textContent = nome + ' será removido do pedido.';
    veu.hidden = false;
    document.getElementById('dlg-manter').focus();
  }

  function fecharDialogo() {
    veu.hidden = true;
    if (gatilho) gatilho.focus();
    gatilho = null;
  }

  document.getElementById('dlg-manter').addEventListener('click', fecharDialogo);
  document.getElementById('dlg-remover').addEventListener('click', fecharDialogo);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !veu.hidden) fecharDialogo();
  });

  document.querySelectorAll('#itens tbody tr').forEach(function (tr) {
    var nome = tr.querySelector('.col-nome').textContent.trim();
    var b = tr.querySelector('.col-acao button');
    b.removeAttribute('onclick');
    b.setAttribute('aria-label', 'Remover ' + nome);
    b.addEventListener('click', function () { abrirDialogo(nome, b); });
  });
})();
</script>
