var ultimoFoco = null;
function modalAberto() { return document.querySelector('[data-modal]:not([hidden])'); }
function abrirModal(id, gatilho) {
  ultimoFoco = gatilho;
  var fundo = document.getElementById(id);
  fundo.hidden = false;
  var alvo = fundo.querySelector('input') || fundo.querySelector('[data-fechar]:not(.perigo)');
  if (alvo) alvo.focus();
}
function fecharModal(fundo) {
  fundo.hidden = true;
  var campo = fundo.querySelector('#confirmar-exclusao');
  if (campo) { campo.value = ''; document.getElementById('btn-confirmar-exclusao').disabled = true; }
  if (ultimoFoco) { ultimoFoco.focus(); ultimoFoco = null; }
}
document.addEventListener('keydown', function (e) {
  var m = modalAberto();
  if (!m) return;
  if (e.key === 'Escape') { fecharModal(m); return; }
  if (e.key === 'Tab') {
    var foc = m.querySelectorAll('input, button:not([disabled])');
    var primeiro = foc[0], ultimo = foc[foc.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir'), b); });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
var confirmacao = document.getElementById('confirmar-exclusao');
confirmacao.addEventListener('input', function () {
  document.getElementById('btn-confirmar-exclusao').disabled = confirmacao.value !== 'EXCLUIR';
});
document.getElementById('btn-dispensar').addEventListener('click', function () { document.getElementById('banner-sucesso').hidden = true; });
document.querySelectorAll('#acessos tbody tr').forEach(function (tr) {
  var nome = tr.querySelector('th').textContent.trim();
  tr.querySelectorAll('button').forEach(function (b) {
    b.setAttribute('aria-label', b.textContent.trim() + ' — ' + nome);
  });
});
document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
  var texto = p.getAttribute('aria-label');
  p.removeAttribute('aria-label');
  p.setAttribute('aria-hidden', 'true');
  var s = document.createElement('span');
  s.textContent = texto;
  p.parentNode.appendChild(s);
});
var bio = document.getElementById('bio');
var contador = document.getElementById('contador-bio');
function atualizarContador() { contador.textContent = bio.value.length + '/200'; }
bio.addEventListener('input', atualizarContador);
atualizarContador();
