<script>
(function(){
  var ultimoFoco=null;
  var gaveta=document.getElementById('gaveta');
  var btnAjuda=document.querySelector('[aria-controls="gaveta"]');

  function abrirModal(m){
    ultimoFoco=document.activeElement;
    m.hidden=false;
    var alvo=m.querySelector('input')||m.querySelector('.btn-prim')||m.querySelector('button');
    alvo.focus();
  }
  function fecharModal(m){
    m.hidden=true;
    if(ultimoFoco) ultimoFoco.focus();
  }
  function alternarGaveta(abrir){
    gaveta.hidden=!abrir;
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir) gaveta.querySelector('a').focus(); else btnAjuda.focus();
  }

  btnAjuda.addEventListener('click',function(){ alternarGaveta(gaveta.hidden); });

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click',function(){
      abrirModal(document.getElementById(b.getAttribute('aria-controls')));
    });
  });

  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      var botao=e.target.closest('button');
      var fecha = e.target===m
        || (botao && botao.classList.contains('modal-x'))
        || (botao && botao.parentNode.classList.contains('modal-acoes') && botao.id!=='conv-enviar');
      if(fecha) fecharModal(m);
    });
  });

  var email=document.getElementById('conv-email');
  var erro=document.getElementById('conv-erro');
  document.getElementById('conv-enviar').addEventListener('click',function(){
    if(email.checkValidity()){
      email.removeAttribute('aria-invalid');
      erro.hidden=true;
      fecharModal(document.getElementById('m0'));
    } else {
      email.setAttribute('aria-invalid','true');
      erro.hidden=false;
      email.focus();
    }
  });

  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){
      b.closest('.banner').hidden=true;
      document.getElementById('conteudo').focus();
    });
  });

  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      var aberto=document.querySelector('.modal:not([hidden])');
      if(aberto) fecharModal(aberto);
      else if(!gaveta.hidden) alternarGaveta(false);
      return;
    }
    if(e.key!=='Tab') return;
    var m=document.querySelector('.modal:not([hidden])');
    if(!m) return;
    var f=m.querySelectorAll('button,input');
    var primeiro=f[0], ultimo=f[f.length-1];
    if(e.shiftKey && document.activeElement===primeiro){ e.preventDefault(); ultimo.focus(); }
    else if(!e.shiftKey && document.activeElement===ultimo){ e.preventDefault(); primeiro.focus(); }
  });
})();
</script>
