<script>
(function(){
  var form=document.querySelector('form');
  var resumo=document.getElementById('resumo-erros');
  var titulo=document.getElementById('titulo-erros');
  var lista=document.getElementById('lista-erros');
  var mesmo=document.getElementById('mesmo');
  var tentou=false;

  var vazio=function(v){return v.trim()!=='';};
  var cep=function(v){return /^\d{8}$/.test(v.replace(/\D/g,''));};
  var campos=[
    {id:'nome',msg:'Informe nome e sobrenome.',ok:function(v){return v.trim().split(/\s+/).length>=2;}},
    {id:'cpf',msg:'Informe um CPF válido com 11 dígitos.',ok:function(v){return cpfOk(v.replace(/\D/g,''));}},
    {id:'dia',msg:'Informe um dia válido.',ok:function(v){return /^\d{1,2}$/.test(v)&&+v>=1&&+v<=31;}},
    {id:'mes',msg:'Informe um mês válido.',ok:function(v){return /^\d{1,2}$/.test(v)&&+v>=1&&+v<=12;}},
    {id:'ano',msg:'Informe o ano com 4 dígitos.',ok:function(v){return /^\d{4}$/.test(v)&&+v>=1900&&+v<=new Date().getFullYear();}},
    {id:'email',msg:'Informe um e-mail válido.',ok:function(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);}},
    {id:'tel',msg:'Informe o telefone com DDD (10 ou 11 dígitos).',ok:function(v){return /^\d{10,11}$/.test(v.replace(/\D/g,''));}},
    {id:'cep-res',msg:'Informe o CEP com 8 dígitos.',ok:cep},
    {id:'rua-res',msg:'Informe a rua.',ok:vazio},
    {id:'num-res',msg:'Informe o número.',ok:vazio},
    {id:'cidade-res',msg:'Informe a cidade.',ok:vazio},
    {id:'uf-res',msg:'Selecione a UF.',ok:vazio}
  ];
  var campos_cor=[
    {id:'cep-cor',msg:'Informe o CEP com 8 dígitos.',ok:cep},
    {id:'rua-cor',msg:'Informe a rua.',ok:vazio},
    {id:'num-cor',msg:'Informe o número.',ok:vazio},
    {id:'cidade-cor',msg:'Informe a cidade.',ok:vazio},
    {id:'uf-cor',msg:'Selecione a UF.',ok:vazio}
  ];
  var mapa=[['cep-res','cep-cor'],['rua-res','rua-cor'],['num-res','num-cor'],['comp-res','comp-cor'],['bairro-res','bairro-cor'],['cidade-res','cidade-cor'],['uf-res','uf-cor']];

  function cpfOk(c){
    if(!/^\d{11}$/.test(c)||/^(\d)\1{10}$/.test(c))return false;
    for(var t=9;t<11;t++){
      var s=0;
      for(var i=0;i<t;i++)s+=+c[i]*(t+1-i);
      var d=((s*10)%11)%10;
      if(d!==+c[t])return false;
    }
    return true;
  }
  function erro(el){
    var id='e-'+el.id, e=document.getElementById(id);
    if(!e){
      e=document.createElement('p');
      e.className='erro'; e.id=id; e.hidden=true;
      var campo=el.closest('.campo');
      if(campo) campo.appendChild(e); else el.closest('label').insertAdjacentElement('afterend',e);
    }
    return e;
  }
  function marca(el,msg){
    var e=erro(el);
    if(!e.textContent.trim()) e.textContent=msg;
    e.hidden=false;
    el.setAttribute('aria-invalid','true');
    var d=(el.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
    if(d.indexOf(e.id)<0) d.push(e.id);
    el.setAttribute('aria-describedby',d.join(' '));
    var c=el.closest('.campo')||el.closest('.check');
    if(c) c.classList.add('tem-erro');
  }
  function limpa(el){
    var e=document.getElementById('e-'+el.id);
    if(e) e.hidden=true;
    el.removeAttribute('aria-invalid');
    var d=(el.getAttribute('aria-describedby')||'').split(' ').filter(function(x){return x&&x!=='e-'+el.id;});
    if(d.length) el.setAttribute('aria-describedby',d.join(' ')); else el.removeAttribute('aria-describedby');
    var c=el.closest('.campo')||el.closest('.check');
    if(c) c.classList.remove('tem-erro');
  }
  function rotulo(el){
    var l=document.querySelector('label[for="'+el.id+'"]')||el.closest('label');
    return l?l.textContent.replace('*','').trim():el.id;
  }
  function revalida(el){
    var par=mapa.filter(function(p){return p[0]===el.id;})[0];
    if(par&&mesmo.checked) document.getElementById(par[1]).value=el.value;
    if(el.id==='aceite'){
      if(tentou){ if(el.checked) limpa(el); else marca(el,'Aceite os termos para continuar.'); }
      return;
    }
    if(!tentou) return;
    var c=campos.concat(campos_cor).filter(function(x){return x.id===el.id;})[0];
    if(!c) return;
    if(c.ok(el.value)) limpa(el); else marca(el,c.msg);
  }

  form.addEventListener('input',function(ev){revalida(ev.target);});
  form.addEventListener('change',function(ev){revalida(ev.target);});

  mesmo.addEventListener('change',function(){
    if(mesmo.checked){
      mapa.forEach(function(p){document.getElementById(p[1]).value=document.getElementById(p[0]).value;});
      campos_cor.forEach(function(c){limpa(document.getElementById(c.id));});
    }
  });

  form.addEventListener('submit',function(ev){
    tentou=true;
    var todos=campos.slice();
    if(!mesmo.checked) todos=todos.concat(campos_cor);
    var erros=[];
    todos.forEach(function(c){
      var el=document.getElementById(c.id);
      if(c.ok(el.value)) limpa(el); else {marca(el,c.msg); erros.push(el);}
    });
    var ac=document.getElementById('aceite');
    if(ac.checked) limpa(ac); else {marca(ac,'Aceite os termos para continuar.'); erros.push(ac);}
    var arq=document.getElementById('arquivo');
    if(arq.files.length&&arq.files[0].size>10485760){marca(arq,'O arquivo passa de 10 MB.'); erros.push(arq);}
    else limpa(arq);

    if(!erros.length){ resumo.hidden=true; return; }

    ev.preventDefault();
    titulo.textContent='Há '+erros.length+(erros.length===1?' problema':' problemas')+' nesta etapa';
    lista.innerHTML='';
    erros.forEach(function(el){
      var li=document.createElement('li'), a=document.createElement('a');
      a.href='#'+el.id;
      a.textContent=rotulo(el)+': '+document.getElementById('e-'+el.id).textContent.trim();
      a.addEventListener('click',function(e){e.preventDefault(); el.focus();});
      li.appendChild(a); lista.appendChild(li);
    });
    resumo.hidden=false;
    resumo.focus();
  });

  var abas=[].slice.call(document.querySelectorAll('[role=tab]'));
  function ativa(i){
    abas.forEach(function(t,k){
      var sel=k===i;
      t.setAttribute('aria-selected',String(sel));
      t.tabIndex=sel?0:-1;
      t.classList.toggle('aba-ativa',sel);
      document.getElementById(t.getAttribute('aria-controls')).hidden=!sel;
    });
  }
  abas.forEach(function(t,i){
    t.addEventListener('click',function(){ativa(i);});
    t.addEventListener('keydown',function(e){
      var j=e.key==='ArrowRight'?(i+1)%abas.length:e.key==='ArrowLeft'?(i-1+abas.length)%abas.length:-1;
      if(j<0) return;
      e.preventDefault(); ativa(j); abas[j].focus();
    });
  });
  ativa(0);
})();
</script>
</body>
@@ FIM

