<script>
(function(){
  var ultimo=null;
  function abrir(el){
    ultimo=document.activeElement;
    el.hidden=false;
    var f=el.querySelector('input,button,a[href]');
    if(f) f.focus();
  }
  function fechar(el){
    el.hidden=true;
    var t=document.querySelector('[aria-controls="'+el.id+'"]');
    if(t&&t.hasAttribute('aria-expanded')) t.setAttribute('aria-expanded','false');
    if(ultimo) ultimo.focus();
  }
  document.querySelectorAll('[aria-controls]').forEach(function(b){
    var el=document.getElementById(b.getAttribute('aria-controls'));
    if(!el) return;
    b.addEventListener('click',function(){
      if(el.classList.contains('gaveta')){
        if(el.hidden){
          ultimo=b;
          el.hidden=false;
          b.setAttribute('aria-expanded','true');
          el.querySelector('button').focus();
        } else {
          fechar(el);
        }
      } else {
        abrir(el);
      }
    });
  });
  document.querySelectorAll('.modal,.gaveta').forEach(function(el){
    el.addEventListener('click',function(e){
      if((el.classList.contains('modal')&&e.target===el)||e.target.closest('.js-fechar,.modal-x')) fechar(el);
    });
  });
  document.addEventListener('keydown',function(e){
    if(e.key!=='Escape') return;
    var a=document.querySelector('.modal:not([hidden]),.gaveta:not([hidden])');
    if(a) fechar(a);
  });
  var em=document.getElementById('conv-email'), er=document.getElementById('conv-erro');
  function validar(){
    var ok=em.checkValidity();
    er.hidden=ok;
    em.setAttribute('aria-invalid',String(!ok));
    return ok;
  }
  em.addEventListener('blur',function(){ if(em.value) validar(); });
  document.getElementById('conv-enviar').addEventListener('click',function(){
    if(!validar()) em.focus();
  });
})();
</script>
</body>
