<script>
(function () {
  var live = document.getElementById('live');
  var gatilho = null;
  var modalAberto = null;
  var appAtual = '';

  function anunciar(texto) {
    live.textContent = '';
    setTimeout(function () { live.textContent = texto; }, 100);
  }

  function nomeDaLinha(el) {
    var linha = el.closest('tr');
    return linha ? linha.querySelector('th').textContent.trim() : '';
  }

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var rotulo = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', rotulo);
  });

  document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
    b.setAttribute('aria-label', 'Revogar acesso de ' + nomeDaLinha(b));
  });
  document.querySelectorAll('table .btn').forEach(function (b) {
    if (b.textContent.trim() === 'Encerrar sessão') {
      b.setAttribute('aria-label', 'Encerrar sessão em ' + nomeDaLinha(b));
    }
  });

  function abrir(id, gatilhoEl) {
    var m = document.getElementById(id);
    gatilho = gatilhoEl;
    modalAberto = m;
    if (id === 'fundo-revogar') {
      appAtual = nomeDaLinha(gatilhoEl);
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + appAtual + '?';
      document.getElementById('dlg-revogar-d').textContent = appAtual + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    if (id === 'fundo-excluir') {
      var campo = document.getElementById('confirmar-exclusao');
      campo.value = '';
      campo.removeAttribute('aria-invalid');
      document.getElementById('erro-exclusao').hidden = true;
    }
    m.hidden = false;
    var foco = id === 'fundo-excluir' ? document.getElementById('confirmar-exclusao') : m.querySelector('[data-fechar]');
    foco.focus();
  }

  function fechar() {
    if (!modalAberto) return;
    modalAberto.hidden = true;
    modalAberto = null;
    if (gatilho) gatilho.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fechar);
  });

  document.querySelector('[data-confirmar="revogar"]').addEventListener('click', function () {
    var nome = appAtual;
    fechar();
    anunciar('Acesso de ' + nome + ' revogado.');
  });

  document.querySelector('[data-confirmar="excluir"]').addEventListener('click', function () {
    var campo = document.getElementById('confirmar-exclusao');
    if (campo.value.trim() !== 'EXCLUIR') {
      document.getElementById('erro-exclusao').hidden = false;
      campo.setAttribute('aria-invalid', 'true');
      campo.focus();
      return;
    }
    fechar();
    anunciar('Exclusão da conta solicitada.');
  });

  document.addEventListener('keydown', function (e) {
    if (!modalAberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key !== 'Tab') return;
    var focaveis = modalAberto.querySelectorAll('button, input');
    var primeiro = focaveis[0];
    var ultimo = focaveis[focaveis.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
})();
</script>
@@ FIM

