(function () {
  var live = document.getElementById('live');
  var banner = document.getElementById('banner-sucesso');
  var modalAberto = null;
  var ultimoFoco = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  // Status visível em texto, não apenas por cor
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var rotulo = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    var t = document.createElement('span');
    t.textContent = rotulo;
    p.parentNode.appendChild(t);
  });

  function abrir(id, gatilho) {
    var fundo = document.getElementById(id);
    if (id === 'fundo-revogar' && gatilho) {
      var nome = gatilho.closest('tr').querySelector('th').textContent;
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nome + '?';
    }
    ultimoFoco = gatilho || null;
    modalAberto = fundo;
    fundo.hidden = false;
    fundo.querySelector('[role="alertdialog"]').focus();
  }

  function fechar() {
    if (!modalAberto) return;
    modalAberto.hidden = true;
    modalAberto = null;
    if (ultimoFoco && document.body.contains(ultimoFoco)) ultimoFoco.focus();
    ultimoFoco = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fechar);
  });

  document.addEventListener('keydown', function (e) {
    if (!modalAberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var focaveis = modalAberto.querySelectorAll('button:not([disabled])');
      var primeiro = focaveis[0];
      var ultimo = focaveis[focaveis.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    banner.hidden = true;
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    banner.querySelector('span').textContent = 'Suas preferências de notificação foram salvas às ' + hora + '.';
    banner.hidden = false;
    anunciar('Preferências de notificação salvas');
  });
})();
