(function () {
  var ultimoFoco = null;
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }
  function abrir(id) {
    ultimoFoco = document.activeElement;
    var f = document.getElementById(id);
    f.hidden = false;
    var c = f.querySelector('input') || f.querySelector('.btn:not(.perigo)');
    if (c) c.focus();
  }
  function fechar(f) {
    f.hidden = true;
    if (ultimoFoco) ultimoFoco.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir')); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (aberto) fechar(aberto);
  });
  var campoExcluir = document.getElementById('texto-excluir');
  var btnExcluir = document.getElementById('btn-confirmar-excluir');
  campoExcluir.addEventListener('input', function () {
    btnExcluir.disabled = campoExcluir.value.trim() !== 'EXCLUIR';
  });
  btnExcluir.addEventListener('click', function () {
    campoExcluir.value = '';
    btnExcluir.disabled = true;
    fechar(document.getElementById('fundo-excluir'));
    anunciar('Pedido de exclusão da conta registrado.');
  });
  document.getElementById('btn-confirmar-revogar').addEventListener('click', function () {
    fechar(document.getElementById('fundo-revogar'));
    anunciar('Acesso do aplicativo revogado.');
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });
  function validarPerfil() {
    var email = document.getElementById('email');
    var tel = document.getElementById('telefone');
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
    var digitos = tel.value.replace(/\D/g, '');
    var telOk = digitos.length === 10 || digitos.length === 11;
    email.setAttribute('aria-invalid', String(!emailOk));
    document.getElementById('erro-email').hidden = emailOk;
    tel.setAttribute('aria-invalid', String(!telOk));
    document.getElementById('erro-telefone').hidden = telOk;
    if (!emailOk) return email;
    if (!telOk) return tel;
    return null;
  }
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var primeiro = validarPerfil();
    if (primeiro) { primeiro.focus(); anunciar('Corrija os campos destacados para salvar.'); return; }
    anunciar('Perfil salvo.');
  });
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    var hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    document.getElementById('texto-prefs').textContent = 'Suas preferências de notificação foram salvas às ' + hora + '.';
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências salvas.');
  });
})();
@@ FIM

