(function () {
  var tituloBase = document.title;
  var live = document.getElementById('live');
  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var regras = [
    { id: 'nome', dica: null, valido: function (v) { return v.trim() !== ''; } },
    { id: 'email', dica: 'dica-email', valido: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
    { id: 'telefone', dica: 'dica-telefone', valido: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; } }
  ];

  function atualizarCampos(falhas) {
    lista.innerHTML = '';
    regras.forEach(function (r) {
      var input = document.getElementById(r.id);
      var erro = document.getElementById('erro-' + r.id);
      var ruim = falhas.indexOf(r.id) !== -1;
      erro.hidden = !ruim;
      if (ruim) { input.setAttribute('aria-invalid', 'true'); } else { input.removeAttribute('aria-invalid'); }
      var ids = [];
      if (r.dica) { ids.push(r.dica); }
      if (ruim) { ids.push(erro.id); }
      if (ids.length) { input.setAttribute('aria-describedby', ids.join(' ')); } else { input.removeAttribute('aria-describedby'); }
      if (ruim) {
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + r.id;
        a.textContent = erro.textContent;
        li.appendChild(a);
        lista.appendChild(li);
      }
    });
    resumo.hidden = falhas.length === 0;
    document.title = falhas.length ? 'Erro: ' + tituloBase : tituloBase;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var falhas = regras.filter(function (r) { return !r.valido(document.getElementById(r.id).value); })
                       .map(function (r) { return r.id; });
    atualizarCampos(falhas);
    if (falhas.length) {
      resumo.focus();
    } else {
      live.textContent = '';
      live.textContent = 'Perfil salvo.';
    }
  });
  form.addEventListener('reset', function () {
    setTimeout(function () { atualizarCampos([]); }, 0);
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    live.textContent = '';
    live.textContent = 'Preferências salvas.';
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var ultimoFoco = null;
  var linhaAtual = null;

  function abrir(modal, foco) {
    ultimoFoco = document.activeElement;
    modal.hidden = false;
    foco.focus();
  }
  function fechar(modal) {
    modal.hidden = true;
    if (ultimoFoco) { ultimoFoco.focus(); }
  }
  function limparExclusao() {
    var c = document.getElementById('confirma-excluir');
    c.value = '';
    c.removeAttribute('aria-invalid');
    c.removeAttribute('aria-describedby');
    document.getElementById('erro-confirma').hidden = true;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var modal = document.getElementById(b.getAttribute('data-abrir'));
      var app = b.getAttribute('data-app');
      linhaAtual = b.closest('tr');
      if (app) { document.getElementById('dlg-revogar-nome').textContent = app; }
      if (modal.id === 'fundo-excluir') { limparExclusao(); }
      abrir(modal, modal.querySelector('[data-fechar]'));
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(m); return; }
      if (e.key !== 'Tab') { return; }
      var f = m.querySelectorAll('button:not([disabled]), input');
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  document.getElementById('btn-confirmar-revogar').addEventListener('click', function () {
    var modal = document.getElementById('fundo-revogar');
    var app = document.getElementById('dlg-revogar-nome').textContent;
    if (linhaAtual) { linhaAtual.remove(); }
    linhaAtual = null;
    var n = document.querySelectorAll('#cap-apps ~ tbody tr').length;
    var cont = document.getElementById('contagem-acessos');
    cont.textContent = n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
    live.textContent = '';
    live.textContent = 'Acesso de ' + app + ' revogado.';
    ultimoFoco = cont;
    fechar(modal);
  });

  var conf = document.getElementById('confirma-excluir');
  document.getElementById('form-excluir').addEventListener('submit', function (e) {
    if (conf.value.trim() === 'EXCLUIR') { return; }
    e.preventDefault();
    document.getElementById('erro-confirma').hidden = false;
    conf.setAttribute('aria-invalid', 'true');
    conf.setAttribute('aria-describedby', 'erro-confirma');
    conf.focus();
  });
})();
@@ FIM

