    foco=document.activeElement;
    m.hidden=false;
    var p=m.querySelector('input,button');
    if(p)p.focus();
  }
  function fechar(m){
    if(!m)return;
    m.hidden=true;
    if(foco)foco.focus();
    foco=null;
  }
  document.addEventListener('click',function(e){
    var t=e.target;
    var abre=t.closest('[data-abrir]');
    if(abre){abrir(document.getElementById(abre.getAttribute('data-abrir')));return;}
    var fecha=t.closest('.modal-x,[data-fechar]');
    if(fecha){fechar(fecha.closest('.modal'));return;}
    var g=t.closest('[data-gaveta]');
    if(g){
      var gav=document.getElementById('gaveta');
      var abrindo=gav.hidden;
      gav.hidden=!abrindo;
      g.setAttribute('aria-expanded',String(abrindo));
      if(abrindo){var a=gav.querySelector('a');if(a)a.focus();}
      return;
    }
    var d=t.closest('[data-dispensar]');
    if(d){d.closest('.banner').hidden=true;return;}
    var v=t.closest('[data-validar-convite]');
    if(v){
      var input=document.getElementById('conv-email');
      var erro=document.getElementById('conv-erro');
      if(!input.checkValidity()){
        erro.hidden=false;
        input.setAttribute('aria-invalid','true');
        input.focus();
      }else{
        input.removeAttribute('aria-invalid');
        erro.hidden=true;
        fechar(v.closest('.modal'));
      }
    }
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      var m=document.querySelector('.modal:not([hidden])');
      if(m)fechar(m);
    }
  });
})();
</script>
</body>
