  function nomeDaLinha(botao) {
    var linha = botao.closest('tr');
    var cab = linha ? linha.querySelector('th') : null;
    return cab ? cab.textContent.trim() : '';
  }

  function acrescentarOculto(elemento, texto) {
    var s = document.createElement('span');
    s.className = 'sr-only';
    s.textContent = texto;
    elemento.appendChild(s);
  }

  function abrir(modal, gatilho) {
    gatilhoAtual = gatilho;
    modal.hidden = false;
    var alvo = modal.querySelector('[data-foco]') || modal.querySelector('[data-fechar]');
    if (alvo) alvo.focus();
  }

  function fechar(modal) {
