(function () {
  var TITULO = 'Configurações da conta - Grupo Pessoas & Cia';
  var live = document.getElementById('live');

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  /* Modais: foco inicial no Cancelar, Esc fecha, Tab fica preso e o foco volta ao gatilho */
  var modalAtivo = null, gatilho = null;

  function abrirModal(id, origem) {
    var m = document.getElementById(id);
    gatilho = origem;
    modalAtivo = m;
    m.hidden = false;
    m.querySelector('[data-fechar]').focus();
  }

  function fecharModal() {
    if (!modalAtivo) return;
    modalAtivo.hidden = true;
    modalAtivo = null;
    if (gatilho && gatilho.isConnected) gatilho.focus();
    gatilho = null;
  }

  document.addEventListener('keydown', function (e) {
    if (!modalAtivo) return;
    if (e.key === 'Escape') { fecharModal(); return; }
    if (e.key !== 'Tab') return;
    var botoes = modalAtivo.querySelectorAll('button');
    var primeiro = botoes[0], ultimo = botoes[botoes.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent =
          'Revogar o acesso do ' + (b.getAttribute('data-app') || 'aplicativo') + '?';
      }
      abrirModal(id, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', fecharModal);
  });

  document.getElementById('confirmar-revogar').addEventListener('click', function () {
    var linha = gatilho && gatilho.closest('tr');
    var celula = gatilho && gatilho.parentNode;
    var destino = null;
    if (linha && celula) {
      var nome = linha.querySelector('th').textContent;
      linha.querySelector('.estado').innerHTML = '<span class="ponto exp" aria-hidden="true"></span>Revogado';
      celula.innerHTML = '<span class="chip">Acesso revogado</span>';
      var ativos = linha.parentNode.querySelectorAll('button[data-abrir]').length;
      document.getElementById('contagem-acessos').textContent =
        ativos + (ativos === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
      anunciar('Acesso de ' + nome + ' revogado.');
      destino = linha.querySelector('th');
    }
    gatilho = null;
    fecharModal();
    if (destino) { destino.tabIndex = -1; destino.focus(); }
  });

  // Integrar aqui a chamada de exclusão no servidor.
  document.getElementById('confirmar-excluir').addEventListener('click', fecharModal);

  /* Sessões: nome acessível por linha */
  var tabelas = document.querySelectorAll('#acessos table');
  if (tabelas[1]) {
    tabelas[1].querySelectorAll('tbody tr').forEach(function (tr) {
      var b = tr.querySelector('button');
      if (b) b.setAttribute('aria-label', b.textContent + ' ' + tr.querySelector('th').textContent);
    });
  }

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  /* Perfil: valida ao enviar, mostra resumo com links e foca o resumo */
  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-perfil');
  var lista = document.getElementById('lista-erros-perfil');
  var email = document.getElementById('email');
  var telefone = document.getElementById('telefone');
  var erroEmail = document.getElementById('erro-email');
  var erroTelefone = document.getElementById('erro-telefone');

  function marcar(campo, erro, invalido) {
    campo.setAttribute('aria-invalid', invalido ? 'true' : 'false');
    erro.hidden = !invalido;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var itens = [];
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim());
    var telOk = telefone.value.replace(/\D/g, '').length === 11;
    marcar(email, erroEmail, !emailOk);
    marcar(telefone, erroTelefone, !telOk);
    if (!emailOk) itens.push('<li><a href="#email">E-mail corporativo: inclua o domínio depois do @</a></li>');
    if (!telOk) itens.push('<li><a href="#telefone">Telefone celular: informe o DDD e os 9 dígitos</a></li>');
    if (itens.length) {
      lista.innerHTML = itens.join('');
      resumo.hidden = false;
      document.title = 'Erro: ' + TITULO;
      resumo.focus();
      return;
    }
    resumo.hidden = true;
    document.title = TITULO;
    anunciar('Perfil salvo.');
  });

  form.addEventListener('reset', function () {
    setTimeout(function () {
      marcar(email, erroEmail, false);
      marcar(telefone, erroTelefone, false);
      resumo.hidden = true;
      document.title = TITULO;
    }, 0);
  });

  /* Preferências */
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Suas preferências de notificação foram salvas.');
  });
})();
