<script>
(function(){
  function $(id){ return document.getElementById(id); }

  // Nome acessível dos botões "Remover": começa pelo texto visível
  document.querySelectorAll('.col-acao button').forEach(function(b){
    var nome = b.closest('tr').querySelector('.col-nome').textContent.trim();
    b.setAttribute('aria-label', 'Remover ' + nome);
  });

  // Bloco oculto também fica desabilitado: não bloqueia validação nem envio
  function setAtivo(el, ativo){
    el.hidden = !ativo;
    el.querySelectorAll('input,select,textarea').forEach(function(c){ c.disabled = !ativo; });
  }

  // Endereço de cobrança
  var mesmo = $('mesmo-end'), cobranca = $('bloco-cobranca');
  function atualizarCobranca(){ setAtivo(cobranca, !mesmo.checked); }
  mesmo.addEventListener('change', atualizarCobranca);
  atualizarCobranca();

  // Dados do cartão só quando o método escolhido é cartão
  var cartao = $('cartao');
  function atualizarMetodo(){
    var m = document.querySelector('input[name="metodo"]:checked');
    setAtivo(cartao, !!m && m.value === 'cartao');
  }
  document.querySelectorAll('input[name="metodo"]').forEach(function(r){
    r.addEventListener('change', atualizarMetodo);
  });
  atualizarMetodo();

  // Busca de CEP (ViaCEP); em falha, o usuário preenche manualmente
  var btnCep = $('btn-cep'), cepIn = $('ent-cep'), cepSt = $('cep-status');
  btnCep.addEventListener('click', function(){
    var cep = cepIn.value.replace(/\D/g, '');
    if (cep.length !== 8){
      cepSt.textContent = 'Informe um CEP com 8 números.';
      cepIn.focus();
      return;
    }
    cepSt.textContent = 'Buscando endereço...';
    fetch('https://viacep.com.br/ws/' + cep + '/json/')
      .then(function(r){ return r.json(); })
      .then(function(d){
        if (d.erro){
          cepSt.textContent = 'CEP não encontrado. Preencha o endereço manualmente.';
          return;
        }
        if (d.logradouro) $('ent-rua').value = d.logradouro;
        if (d.localidade) $('ent-cidade').value = d.localidade;
        if (d.uf) $('ent-uf').value = d.uf;
        cepSt.textContent = 'Endereço encontrado. Confira e informe o número.';
        $('ent-rua').focus();
      })
      .catch(function(){
        cepSt.textContent = 'Não foi possível buscar o CEP. Preencha o endereço manualmente.';
      });
  });

  // Reenvio do código SMS com espera de 30 s
  var btnReenv = $('btn-reenviar'), ajudaReenv = $('reenviar-d'), timer = null;
  function esperarReenvio(){
    var t = 30;
    btnReenv.disabled = true;
    clearInterval(timer);
    timer = setInterval(function(){
      t--;
      if (t <= 0){
        clearInterval(timer);
        btnReenv.disabled = false;
        ajudaReenv.textContent = 'Você já pode pedir um novo código.';
      } else {
        ajudaReenv.textContent = 'Você poderá pedir um novo código em ' + t + ' segundos.';
      }
    }, 1000);
  }
  btnReenv.addEventListener('click', esperarReenvio);
  esperarReenvio();

  // Cupom: valida só o preenchimento; a validade é decidida pelo servidor
  $('btn-cupom').addEventListener('click', function(){
    var c = $('cupom'), st = $('cupom-status');
    if (!c.value.trim()){
      st.textContent = 'Digite o código do cupom.';
      c.focus();
      return;
    }
    st.textContent = 'Validando cupom...';
  });

  // Diálogo de remoção de item
  var veu = $('veu'), pendente = null, focoAnterior = null;
  window.abrirDialogo = function(nome){
    pendente = nome;
    focoAnterior = document.activeElement;
    $('dlg-p').textContent = nome + ' será removido do pedido.';
    veu.hidden = false;
    $('dlg-cancelar').focus();
  };
  window.fecharDialogo = function(){
    veu.hidden = true;
    pendente = null;
    if (focoAnterior) focoAnterior.focus();
    focoAnterior = null;
  };
  window.confirmarRemocao = function(){
    var nome = pendente;
    document.querySelectorAll('tbody tr').forEach(function(tr){
      if (tr.querySelector('.col-nome').textContent.trim() === nome) tr.remove();
    });
    focoAnterior = null;
    window.fecharDialogo();
    var t = $('t-itens');
    t.setAttribute('tabindex', '-1');
    t.focus();
  };
  veu.addEventListener('keydown', function(e){
    if (e.key === 'Escape') window.fecharDialogo();
  });

  // Evita envio duplicado
  $('form-checkout').addEventListener('submit', function(){
    var b = document.querySelector('.btn-pagar');
    b.disabled = true;
    b.textContent = 'Processando pagamento...';
  });
})();
</script>
